const log = (msg) => console.log(`[${new Date().toISOString().slice(11, 19)}] ${msg}`)

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

/**
 * 批三十七：e2e 手机号唯一化——固定号（13800000000 等）在残留数据/共享库上会与其他用例或
 * 历史残留撞号，令「按手机号检索」类断言与人工排查混淆。
 * 实证（批六十四回库取证）：`sys_user.phonenumber` 是**非唯一**索引（`idx_sys_user_phonenumber`），
 * 库层无唯一约束——唯一化纯靠本函数纪律保证，非"撞唯一索引"。
 * '138' + 时间戳后 8 位 = 11 位合法手机号，每次调用唯一。
 * 同一用例内 create+update 需保持同号时，先存 const 再两处引用。
 */
function e2ePhone() {
  return '138' + String(Date.now()).slice(-8)
}

function ensureDir(dir) {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true })
  }
}

async function screenshot(page, name) {
  const file = path.join(CONFIG.screenshotDir, `${name}.png`)
  await page.screenshot({ path: file, fullPage: false })
  log(`  📷 截图: ${file}`)
}

/**
 * 检测页面是否为真正的 404 错误页
 *
 * 旧实现 `page.locator('text=404')` 会误匹配备份文件名时间戳中的 "404"（如 144804），
 * 导致 /tool/backup 等正常页面被误判为 404。
 *
 * 本实现通过以下条件综合判断：
 * 1. 检查 URL 是否被重定向到 404 路由
 * 2. 检查页面是否存在明显的 404 错误标识（大标题、错误码样式）
 * 3. 检查页面正文是否仅包含 404 错误信息（排除表格数据中的时间戳误匹配）
 *
 * @param {import('playwright').Page} page
 * @param {object} [options] - 选项
 * @param {number} [options.timeout=1000] - 等待超时（毫秒）
 * @returns {Promise<boolean>} true 表示当前页面是 404 错误页
 */
async function is404Page(page, options = {}) {
  const { timeout = 1000 } = options
  // 1. URL 检查：被重定向到 /404 或 /not-found 等 404 路由
  const url = page.url()
  if (/\/(404|not-found)(\?|$|#)/.test(url)) {
    return true
  }
  // 2. 检查专门的 404 错误组件（el-result 或 .error-page 容器中包含 404 标题）
  const errorContainer = page.locator('.el-result, .error-page, .page-404, [class*="error-container"]').first()
  if (
    await errorContainer
      .waitFor({ state: 'visible', timeout })
      .then(() => true)
      .catch(() => false)
  ) {
    const text = await errorContainer.innerText().catch(() => '')
    if (/^\s*404\s*$/.test(text) || /404.*Not Found|页面不存在|Page Not Found/i.test(text)) {
      return true
    }
  }
  // 3. 检查纯 404 文本（仅在 body 文本非常短且以 404 开头时判定，排除表格数据误匹配）
  const bodyText = await page.evaluate(() => document.body.innerText.trim().substring(0, 200)).catch(() => '')
  if (/^404\b/.test(bodyText) && bodyText.length < 100) {
    return true
  }
  return false
}

/**
 * 动态路由 goto 重试样板（批次三十六提取，语义与 F94/F95/F97 原三处内联循环一致）：
 * 主流程 UI 登录后菜单路由 addRoute 异步注册——立即 goto 会 404 回首页，
 * 重试至 URL 命中目标片段（最多 5 次，每次间隔 1.5s）。
 * @param {import('playwright').Page} page
 * @param {string} url 目标完整地址（含 frontendUrl）
 * @param {string} pathToken URL 必须包含的路径片段（用于命中判定）
 */
async function gotoDynamicRoute(page, url, pathToken) {
  let lastErr = null
  for (let i = 0; i < 5; i++) {
    // 导航**超时**同样是"该重试"的结局。旧实现只对"落到错误 URL"重试，`page.goto` 抛错
    // 直接上抛 ⇒ 整个功能（乃至循环里剩余子目标）被一次高负载抖动打断，只剩一条
    // 无归因的"测试执行 异常"（b73 实测：/system/menu 一次 30s load 超时使 F58
    // 的 user/dept/menu/notice 四目标丢掉了 notice 的全部覆盖）。
    try {
      await page.goto(url, { waitUntil: 'load', timeout: 30000 })
      lastErr = null
    } catch (err) {
      lastErr = err
      // 只对"load 超时"重试（高负载抖动的形态）。连接被拒/响应为空说明后端或整台机器
      // 已经没了，重试只是把一个坏环境跑成 5 倍时长——那种情况要它立刻失败。
      if (!/Timeout/i.test(err.message)) break
      log(`  [diag-goto] try ${i}: 导航超时，重试 ${String(err.message).split('\n')[0].slice(0, 70)}`)
      continue
    }
    await page.waitForTimeout(1500)
    log(`  [diag-goto] try ${i}: url=${page.url()}`)
    if (page.url().includes(pathToken)) break
  }
  await page.waitForLoadState('load').catch(() => {})
  if (lastErr) throw new Error(`导航 5 次均未成功（最后异常：${String(lastErr.message).split('\n')[0].slice(0, 90)}）`)
}

/**
 * 剪贴板通道桩（b111）：把 `navigator.clipboard` 与 `document.execCommand` 换成页面内可控实现。
 *
 * 为什么必须桩掉而不能直接读真实剪贴板：headless 浏览器是否放行 clipboard 由策略/权限决定，
 * 把判据建在它上面等于让门禁绿红由环境决定（AGENTS 测试门禁全景 前言 ④）。而本批要证的是
 * **我们这一侧的分支**：两条通道都失败时必须报失败、降级通道返回 true 时必须报成功。
 * 桩只替换浏览器能力，产品代码与点击链路原样执行。
 *
 * 返回是否真的装上——装不上即判红，不得静默跳过（⑥：零捕获 ≠ PASS）。
 */
async function stubClipboard(page, execOk) {
  return page
    .evaluate((ok) => {
      const w = window
      try {
        if (!w.__b111Clipboard) {
          w.__b111Clipboard = {
            clipboard: Object.getOwnPropertyDescriptor(navigator, 'clipboard'),
            exec: Object.getOwnPropertyDescriptor(document, 'execCommand')
          }
        }
        Object.defineProperty(navigator, 'clipboard', { value: undefined, configurable: true })
        Object.defineProperty(document, 'execCommand', { value: () => ok, configurable: true })
        return true
      } catch {
        return false
      }
    }, execOk)
    .catch(() => false)
}

/** 还原 {@link stubClipboard} 改过的两条通道（后续用例不得继承被改造过的环境） */
async function restoreClipboard(page) {
  return page
    .evaluate(() => {
      const w = window
      const saved = w.__b111Clipboard
      if (!saved) return false
      try {
        if (saved.clipboard) Object.defineProperty(navigator, 'clipboard', saved.clipboard)
        else Reflect.deleteProperty(navigator, 'clipboard')
        if (saved.exec) Object.defineProperty(document, 'execCommand', saved.exec)
        else Reflect.deleteProperty(document, 'execCommand')
        delete w.__b111Clipboard
        return true
      } catch {
        return false
      }
    })
    .catch(() => false)
}

/**
 * 全屏通道桩（b112）：把 `documentElement.requestFullscreen` 换成必然 reject 的实现。
 *
 * 为什么必须桩掉而不能真去全屏：headless 里能否进入全屏由窗口/内核策略决定，
 * 把判据建在它上面等于让绿红由环境决定（前言 ④）。本批要证的是**我们这一侧的分支**：
 * 浏览器拒绝时必须有可见提示、图标不得假装已进入全屏。桩只替换浏览器能力。
 *
 * 返回是否真的装上——装不上即判红，不得静默跳过（⑥：零捕获 ≠ PASS）。
 */
async function stubFullscreenDenied(page) {
  return page
    .evaluate(() => {
      const w = window
      try {
        if (!w.__b112Fullscreen) {
          w.__b112Fullscreen = Object.getOwnPropertyDescriptor(document.documentElement, 'requestFullscreen') || null
        }
        Object.defineProperty(document.documentElement, 'requestFullscreen', {
          value: () => Promise.reject(new Error('__b112_denied__')),
          configurable: true
        })
        return typeof document.documentElement.requestFullscreen === 'function'
      } catch {
        return false
      }
    })
    .catch(() => false)
}

/** 还原 {@link stubFullscreenDenied}（按装桩前实测的描述符复原，不假设它原本不存在） */
async function restoreFullscreen(page) {
  return page
    .evaluate(() => {
      const w = window
      const saved = w.__b112Fullscreen
      if (saved === undefined) return false
      try {
        if (saved) Object.defineProperty(document.documentElement, 'requestFullscreen', saved)
        else Reflect.deleteProperty(document.documentElement, 'requestFullscreen')
        delete w.__b112Fullscreen
        return true
      } catch {
        return false
      }
    })
    .catch(() => false)
}

/** 等一条可见的 EP 消息（按文案精确过滤，整页 innerText 不算——时钟/日志里的数字会把它洗绿） */
async function waitToast(page, text, timeout = 6000) {
  return page
    .locator('.el-message')
    .filter({ hasText: text })
    .first()
    .waitFor({ state: 'visible', timeout })
    .then(() => true)
    .catch(() => false)
}

/**
 * 等现有 EP 消息全部自消。
 *
 * 为什么必须等：同一功能内后续断言会数"当前可见的 `.el-message--error|success`"
 * （F66 的"取消同步：0 Toast"就是这么写的），残留一条就把**别人的**判据染红。
 * 这是"构造断言副作用"的反面教训——验证失败态本身没问题，但不能把副作用留在共用页面里。
 */
async function waitToastsCleared(page, timeout = 8000) {
  return page
    .waitForFunction(() => document.querySelectorAll('.el-message').length === 0, undefined, { timeout })
    .then(() => true)
    .catch(() => false)
}

/**
 * 测试债轮抽取的「页面打开五连」样板：presetTourDisabled → goto（动态路由重试）
 * → sleep(1500) → skipTour → is404 判定。
 * 替换 F91/F92/F100/F101 中 16 处重复的「预置 tour → goto → sleep → skipTour → 非404」
 * 组合，行为等价（F91/F92 原 sleep(1200) 统一为 1500ms；goto 升级为 gotoDynamicRoute
 * 重试语义，仅更强不弱——addRoute 异步竞态下原实现偶发 404 回首页）。
 * @param {import('playwright').Page} page
 * @param {string} path 页面路径（以 / 开头自动拼 frontendUrl；传完整 URL 原样使用）
 * @param {string} [pathToken] URL 命中片段（缺省用 path）
 * @returns {Promise<boolean>} false = 落到 404 页（调用方据此早退）
 */
async function openPage(page, path, pathToken) {
  await presetTourDisabled(page)
  const url = path.startsWith('http') ? path : `${CONFIG.frontendUrl}${path}`
  await gotoDynamicRoute(page, url, pathToken || path)
  // .app-container 是 SPA 外壳（路由切换瞬间即存在，等于没等页面渲染）；skipTour 抢在
  // tour 启动前执行会让遮罩后现并拦截后继点击（批三十三全量 F5-11 假失败实证）。
  // 保持固定沉降窗（稳定胜过速度），保证 tour 启动→skipTour 关闭的时序
  await page.waitForTimeout(1500)
  await skipTour(page)
  return !(await is404Page(page))
}

/**
 * 页面"落确定态"判据（批七十四 T1：探针与判据统一收进 `page-state.mjs`）。
 *
 * 本套件此前另写一份，且两份都把**测量对象**选错了：`contentRoot` 在整份 document 上求
 * 可见性（布局外壳恒真）、`text` 取 `body.innerText`（导航菜单恒有字），于是深链落空、
 * 路由未匹配、内容区空白都照样记 ✅。现在判据只此一处，main.mjs 与 deep-e2e 不可能再漂移。
 * 探针自身异常不得冒充产品结论（如实标注"⟵ 断言工具异常"）。
 */
async function assertPageLoaded(page, featureId, name) {
  const v = await page.evaluate(PAGE_STATE_PROBE).catch(() => null)
  if (!v) {
    record(featureId, `${name}（确定态对账）`, false, '⟵ 断言工具异常（evaluate 失败），非产品问题')
    return false
  }
  const verdict = judgePageLoaded(v)
  record(
    featureId,
    `${name}（确定态对账）`,
    verdict.ok,
    `${verdict.detail}${verdict.ok ? '' : ` ⟵ ${verdict.reasons.join(' / ')}`}`
  )
  return verdict.ok
}

/**
 * 通用 API 助手（429 退避重试，语义对齐 mLevelApiSetup 内 api 闭包——批次十八口径）。
 * 测试债轮新增：供 recordSkip 的 API 200 兜底断言与 F110-116 使用（e2e 规范：禁裸 fetch）。
 * @param {string} path 后端路径（以 / 开头）
 * @param {object} [opts] fetch 选项（method/headers/body 等）
 * @param {number} [_tries] 剩余重试次数
 * @returns {Promise<{status: number, body: any}>}
 */
async function apiWithBackoff(path, opts = {}, _tries = 3) {
  const res = await fetch(`${CONFIG.backendUrl}${path}`, opts).catch(() => null)
  if (!res) return { status: 0, body: null }
  // 批次十八 R6/R8 实证：令牌桶 429 按秒回填，1.2s 退避重试不改变断言语义
  if (res.status === 429 && _tries > 0) {
    await sleep(1200)
    return apiWithBackoff(path, opts, _tries - 1)
  }
  const body = await res.json().catch(() => null)
  return { status: res.status, body }
}

// ==================== 测试结果 ====================

const results = []

/**
 * 全局捕获中枢（在 main() 中创建页面后注入）
 * @type {ReturnType<typeof import('./capture-kit.mjs').createCaptureHub>|null}
 */
let captureHub = null

function record(feature, name, passed, detail = '') {
  const entry = { feature, name, passed, detail }
  // 失败时同步附带页面证据（Toast / 失败请求 / 慢请求 / console）；
  // 需要 await 的部分（URL / 页面文本 / 截图）由 flushFailureEvidence() 在功能结束后补写。
  if (!passed) {
    try {
      captureHub?.noteFailure(entry)
    } catch {}
  }
  results.push(entry)
  const tag = passed ? '✅ PASS' : '❌ FAIL'
  log(`${tag} [功能${feature}] ${name}${detail ? ' - ' + detail : ''}`)
}

/**
 * 聚合断言回读：按功能号 + 记录名取既成记录，取不到返回 undefined（调用方按未通过计）。
 *
 * b73 轮 19 真缺陷修复：`assertPageLoaded` 会把记录名写成「X（确定态对账）」，
 * 而 139 处聚合仍按 `r.name === 'X'` 精确回读 ⇒ 恒 undefined ⇒ 聚合恒 ❌
 * （F18 实测「8 项检查通过 7/8」而 8 条子记录全部 ✅，就是这条断链）。
 * 口径：① 先精确同名（保留既有行为，绝不误抢同名他记录）② 再按剥掉对账后缀的名字兜底
 * ③ 两次都取不到才打警告——静默当 false 是最难查的假失败。
 * @param {number} feature 功能号
 * @param {string} name 记录名（可不含「（确定态对账）」后缀）
 */
function readFeatureRecord(feature, name) {
  const list = results.filter((r) => r.feature === feature)
  const exact = list.find((r) => r.name === name)
  if (exact) return exact
  const bare = (s) => String(s).replace(/（(?:确定态对账|结果对账)）$/, '')
  const hit = list.find((r) => bare(r.name) === bare(name))
  if (!hit) log(`  ⚠️ 聚合回读缺失：功能${feature} 无名为「${name}」的记录（本项按未通过计）`)
  return hit
}

/**
 * 测试债轮：SKIP 条目不再冒充 PASS。
 * 原问题：`record(N, name, true, 'SKIP：...')` 把未实际执行的路径记为 passed=true，
 * 汇总统计/明细打印/退出码均按 PASS 处理（假通过）。
 * 最小侵入方案：本助手产出带 skipped:true 标记的条目——汇总明细以 ⏭ SKIP 打印、
 * 汇总行单列 SKIP 数（不再显示 ✅）；同时要求调用点用 api 助手（apiWithBackoff）
 * 补一条 API 200 兜底断言：apiOk=true 时条目计 passed（由真实兜底断言支撑），
 * apiOk=false 兜底失败按 FAIL 处理，apiOk=null 表示场景确无 API 可兜底（注释缘由）。
 * @param {number} feature 功能号
 * @param {string} name 断言名
 * @param {string} reason SKIP 缘由
 * @param {boolean|null} [apiOk] 兜底 API 200 断言结果（null = 无 API 可兜底）
 */
function recordSkip(feature, name, reason, apiOk = null) {
  const passed = apiOk !== false
  const detail = `SKIP：${reason}（兜底 API=${apiOk === null ? '无' : apiOk ? '200 ✓' : '失败 ✗'}）`
  if (!passed) {
    try {
      captureHub?.noteFailure({ feature, name, passed, detail })
    } catch {}
  }
  results.push({ feature, name, passed, detail, skipped: true })
  log(`${passed ? '⏭ SKIP' : '❌ FAIL'} [功能${feature}] ${name} - ${detail}`)
}

/**
 * 补写失败条目的异步证据（URL / 页面文本 / 登录态 / 截图）
 * 在每个功能测试结束后调用（此时页面仍处于该功能的最终状态）。
 *
 * @param {import('playwright').Page} page - 页面对象
 * @param {number|string} featureId - 功能编号，用于截图命名
 */
async function flushFailureEvidence(page, featureId) {
  if (!captureHub) return
  await captureHub.flush(`F${featureId}`).catch(() => {})
}

/**
 * 敏感写面限流适配（b110）：b102 给 `/system/tenant` 加了敏感档
 * （`SENSITIVE_LIMIT_TIERS`：容量 5 / 回填 0.05/s），而本套件在 F69–F74 会于同一秒内
 * 连续开户 + 编辑十余次 ⇒ 必然撞 429（实测：F69 的 2 次 POST + 3 次 PUT 恰好耗尽 5 个令牌，
 * F70 起全部 429、`tenantId=null`，F71–F74 连带"前置失败"）。
 * 429 的语义是**这次没有执行**，按响应头 `Retry-After` 等待后重试是客户端该做的事，
 * 不是把判据放宽；只拦**精确路径** `/system/tenant`（F71 要自己断言 429 契约，
 * 通配 wrapper 会把它一起吞掉）。
 */
async function tenantWrite(url, init = {}, label = '') {
  const maxWaitMs = 180000
  const started = Date.now()
  for (;;) {
    const resp = await fetch(url, init)
    if (resp.status !== 429) return resp
    const ra = Number(resp.headers.get('retry-after'))
    const waitMs = Number.isFinite(ra) && ra > 0 ? ra * 1000 + 300 : 1000
    if (Date.now() - started + waitMs > maxWaitMs) return resp
    log(
      `  ⏳ ${label || 'POST/PUT /system/tenant'} 命中敏感档限流（429），按 Retry-After ${Math.ceil(waitMs / 1000)}s 等待后重试`
    )
    await sleep(waitMs)
  }
}

/**
 * API 登录（fetch 方式，返回 token 或 null）
 * 用于 testFeature25-32 等纯 API 测试场景，失败时记录详细错误信息
 * 内置 429 限流重试 + token 缓存机制（避免重复登录触发限流）
 *
 * 缓存策略：
 * - 按用户名 + extraHeaders 的 key 缓存 token
 * - 同一用户 + 相同 headers 的后续调用直接返回缓存 token（不重新登录）
 * - feature 27 的 XFF 测试使用不同的 extraHeaders，因此独立缓存
 *
 * 429 重试策略：
 * - 最多 3 次，间隔 65 秒（覆盖登录限流 60 秒窗口）
 *
 * @param {object} [extraHeaders] - 额外的请求头（如 X-Forwarded-For）
 * @param {string} [username] - 用户名，默认 CONFIG.username
 * @param {string} [password] - 密码，默认 CONFIG.password
 * @returns {Promise<{token: string|null, detail: string}>}
 */
const _apiLoginCache = new Map()
async function apiLogin(extraHeaders = {}, username = CONFIG.username, password = CONFIG.password) {
  // 缓存 key：用户名 + extraHeaders 的 JSON（不同 headers 独立缓存，如 feature 27 的 XFF 测试）
  const cacheKey = `${username}::${JSON.stringify(extraHeaders)}`
  if (_apiLoginCache.has(cacheKey)) {
    const cached = _apiLoginCache.get(cacheKey)
    return { token: cached, detail: '使用缓存 token（避免重复登录触发限流）' }
  }

  const maxRetries = 3
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      // 验证码开启时先取码再登录（API 自取 uuid 自用，同一次请求天然同源）
      const { code, uuid } = await fetchCaptchaForApi(CONFIG.backendUrl)
      const resp = await fetch(`${CONFIG.backendUrl}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...extraHeaders },
        body: JSON.stringify({ username, password, code, uuid })
      })
      const text = await resp.text()
      let data = null
      try {
        data = JSON.parse(text)
      } catch (_) {}
      if (resp.status === 200 && data?.token) {
        _apiLoginCache.set(cacheKey, data.token)
        return { token: data.token, detail: `status=200, token 获取成功（尝试 ${attempt}/${maxRetries}）` }
      }
      // 429 限流：等待 65 秒后重试（覆盖登录限流 60 秒窗口）
      if (resp.status === 429 && attempt < maxRetries) {
        log(`  ⏳ 登录被限流（429），等待 65 秒后重试（${attempt}/${maxRetries}）...`)
        await sleep(65000)
        continue
      }
      return { token: null, detail: `status=${resp.status}, body=${text.slice(0, 120)}` }
    } catch (err) {
      if (attempt < maxRetries) {
        log(`  ⏳ 登录异常，3 秒后重试: ${err.message.slice(0, 80)}`)
        await sleep(3000)
        continue
      }
      return { token: null, detail: `异常: ${err.message.slice(0, 100)}` }
    }
  }
  return { token: null, detail: '重试次数耗尽' }
}

// ==================== 登录流程 ====================

/**
 * 登录流程（支持自定义账户）
 * @param {import('playwright').Page} page
 * @param {string} [username] - 用户名，默认 CONFIG.username
 * @param {string} [password] - 密码，默认 CONFIG.password
 */
async function login(page, username = CONFIG.username, password = CONFIG.password) {
  log(`=== 登录流程（用户: ${username}）===`)
  // 预置引导完成标记（导航前注入，不打断 SSO 深链 302 重定向链）
  await presetTourDisabled(page)
  // 验证码响应捕获必须在 goto 前注册（与页面显示的验证码图同 uuid 同源）
  const captchaPromise = capturePageCaptcha(page)
  await page.goto(`${CONFIG.frontendUrl}/login`, { waitUntil: 'load' }).catch(() => {
    log('  ⚠️ networkidle 等待超时（可能有长连接），降级继续登录流程')
  })
  await sleep(1500)

  // 关闭 Cookie 同意横幅（若存在）
  const cookieBtn = page.locator('button:has-text("同意")').first()
  if (
    await cookieBtn
      .waitFor({ state: 'visible', timeout: 500 })
      .then(() => true)
      .catch(() => false)
  ) {
    await cookieBtn.click({ timeout: 2000 }).catch(() => {})
    await sleep(300)
    log('  已关闭 Cookie 同意横幅')
  }

  // 验证码真码（后端启用时经 stepby-redis 读取页面同源明文；读不到 fail-fast）
  const captcha = await captchaPromise
  if (captcha === null) {
    log('  ⚠️ 页面未发出 /captchaImage 请求（后端未启用验证码），跳过填码')
  }

  // 等待用户名输入框可见（最多 10 秒），确保 SPA 完成渲染
  // 兼容 i18n 后 placeholder 可能为中文或英文
  const userInput = page
    .locator('input[placeholder="账号"], input[placeholder="Username"], input[name="username"]')
    .first()
  await userInput.waitFor({ state: 'visible', timeout: 10000 }).catch(() => {})
  await userInput.fill(username)

  // 填写密码
  const passInput = page
    .locator('input[placeholder="密码"], input[placeholder="Password"], input[type="password"]')
    .first()
  await passInput.waitFor({ state: 'visible', timeout: 5000 }).catch(() => {})
  await passInput.fill(password)

  // 验证码真码填入（不填假码；后端未启用时跳过）
  await fillCaptchaOnPage(page, captcha)

  // 点击登录按钮（按钮文本含"登 录"/"登录"/"Login"）
  const loginBtn = page
    .locator(
      'button:has-text("登 录"), button:has-text("登录"), button:has-text("Login"), button[type="submit"], .el-button--primary'
    )
    .first()
  await loginBtn.waitFor({ state: 'visible', timeout: 5000 }).catch(() => {})
  await loginBtn.click()

  // 等待跳转：**成功跳转**与**可见错误提示**二者之一先到，谁先到听谁的。
  // 注意：不能使用 '**/index**' glob，因为登录页 URL /login?redirect=/index 也包含 /index，
  // 会导致 waitForURL 立即返回而误判登录成功。改用函数断言：URL 不包含 /login 才算登录成功。
  // b81 起不再"固定等 15s 后一锤定音"：deep-e2e 全量实测过同一形状的假失败
  // （截图里已登录进 /index，只是跳转晚于窗口），环境慢不等于登录坏；
  // 登录真失败时 error toast 会先出现，也不必白等满窗口。
  if (page.url().includes('/login')) {
    const outcome = await Promise.race([
      page
        .waitForURL((url) => !url.toString().includes('/login'), { timeout: 30000 })
        .then(() => 'nav')
        .catch(() => 'timeout'),
      page
        .locator('.el-message--error')
        .first()
        .waitFor({ state: 'visible', timeout: 30000 })
        .then(() => 'error')
        .catch(() => 'timeout')
    ])
    if (outcome === 'timeout' && !page.url().includes('/login')) {
      log('  ⚠️ 登录跳转晚于等待窗口，但 URL 已离开登录页——按成功处理')
    }
  }
  await sleep(2500)
  log(`  当前 URL: ${page.url()}`)

  // 检查是否登录成功
  const isLoggedIn = !page.url().includes('login')
  if (isLoggedIn) {
    log('  ✅ 登录成功')
  } else {
    log('  ❌ 登录失败')
  }
  return isLoggedIn
}

/**
 * 登录前注入：预置新手引导完成标记（e2e 无人值守禁用 Tour 遮罩）。
 * 必须用 addInitScript（每次导航前执行）而非登录后 reload —— reload 会打断
 * SSO 深链登录的 302 重定向链，丢失多参查询（功能 51 回归实证）。
 * 真实用户仍正常看到引导；仅自动化环境显式关闭（测试基建标准做法）。
 */
async function presetTourDisabled(page) {
  await page.addInitScript(() => {
    try {
      localStorage.setItem('stepby-layout-tour', 'completed')
      localStorage.setItem('workbench-tour', 'completed')
      localStorage.setItem('home-tour', 'completed')
    } catch {
      /* localStorage 不可用时保持原行为 */
    }
  })
}

/**
 * 注销当前登录状态
 * @param {import('playwright').Page} page
 */
async function logout(page) {
  log('=== 注销登录 ===')
  try {
    // 清除 localStorage 和 Cookie
    await page.evaluate(() => {
      localStorage.clear()
      sessionStorage.clear()
    })
    await page.context().clearCookies()
    await page.goto(`${CONFIG.frontendUrl}/login`, { waitUntil: 'load' })
    await sleep(1500)
    log('  ✅ 已注销')
  } catch (err) {
    log(`  ⚠️ 注销异常: ${err.message.slice(0, 80)}`)
  }
}

// 跳过 Tour 引导（如果出现）
async function skipTour(page) {
  // 快路径（批三十五）：login/presetTourDisabled 已给全站导航注入 *-tour=completed 抑制标记，
  // 标记在场时 tour 根本不会弹出——跳过 2.5s 晚到窗口（isVisible→waitFor 等价改写后无 tour
  // 的调用点会等满 2.5s，88 处 × 2.5s ≈ +4 分钟全量耗时）。标记在场时仅做即时探测兜底
  // （tour 违约弹出仍会被点到）；标记缺失（独立 newContext 等）保持完整 2500ms 晚到窗口
  // （收尾十三：operlog 页 1/4 步遮罩拦截实证，原 1s 窗口会漏掉晚到的 tour）。
  const tourSuppressed = await page
    .evaluate(() => {
      try {
        return localStorage.getItem('stepby-layout-tour') === 'completed'
      } catch {
        return false
      }
    })
    .catch(() => false)
  const skipBtn = page
    .locator('button:has-text("跳过"), button:has-text("跳过引导"), [class*="tour"] button:has-text("跳")')
    .first()
  if (tourSuppressed) {
    if (await skipBtn.isVisible().catch(() => false)) {
      await skipBtn.click({ timeout: 3000 }).catch(() => {})
      await sleep(500)
    }
  } else if (
    await skipBtn
      .waitFor({ state: 'visible', timeout: 2500 })
      .then(() => true)
      .catch(() => false)
  ) {
    await skipBtn.click({ timeout: 3000 }).catch(() => {})
    await sleep(500)
  }
  // B4 软提示「安全提示」（初始密码提醒 confirm）可能盖在任何页面上——
  // 点「取消」留在当前页继续测试（确定会跳转改密页破坏用例上下文）
  // 必须同时给「取 消」：本仓 common.cancel 的字面值带空格（`src/i18n/locales/zh-CN/common.ts`），
  // 而 :has-text 不吃中间空格 ⇒ 只写无空格形式=这个提醒从来没被点掉过，遮罩一直盖在页面上。
  const mbCancel = page
    .locator(
      '.el-overlay-message-box button:has-text("取 消"), .el-overlay-message-box button:has-text("取消"), .el-message-box button:has-text("取 消"), .el-message-box button:has-text("取消")'
    )
    .first()
  if (
    await mbCancel
      .waitFor({ state: 'visible', timeout: 500 })
      .then(() => true)
      .catch(() => false)
  ) {
    await mbCancel.click({ timeout: 3000 }).catch(() => {})
    await sleep(300)
  }
  // 也尝试 ESC 关闭
  await page.keyboard.press('Escape', { timeout: 3000 }).catch(() => {})
  await sleep(300)
}

