// ==================== 功能 2：登录异常检测 ====================

async function testFeature2(page) {
  log('=== 功能 2：登录异常检测 ===')
  // 验证后端 scheduler 已注册（通过查看接口可用性间接验证）
  await page.goto(`${CONFIG.frontendUrl}/index`, { waitUntil: 'load' })
  await sleep(2000)
  await skipTour(page)
  await screenshot(page, 'feat2_dashboard')

  // 验证 dashboard 页面能正常加载
  const isDashboard = page.url().includes('index') || page.url().endsWith('/')
  record(2, 'Dashboard 页面加载', isDashboard)

  // ===== 全屏通道（b112）：浏览器拒绝时必须可见，图标不得假装已进入全屏 =====
  const fsStubbed = await stubFullscreenDenied(page)
  record(2, '全屏拒绝桩已装上', fsStubbed, fsStubbed ? '' : '无法覆盖 requestFullscreen（零捕获 ≠ PASS）')
  if (fsStubbed) {
    const fsIcon = page.locator('#screenfull').first()
    const fsVisible = await fsIcon
      .waitFor({ state: 'visible', timeout: 5000 })
      .then(() => true)
      .catch(() => false)
    // 复原期望值取"点击前实测值"：硬编码终态会把一次正常同步判成假红（前言 ③）
    const beforeLabel = fsVisible ? await fsIcon.getAttribute('aria-label').catch(() => '') : ''
    const fsClicked = fsVisible
      ? await fsIcon
          .click({ timeout: 4000 })
          .then(() => true)
          .catch(() => false)
      : false
    const fsWarned = fsClicked ? await waitToast(page, '无法切换全屏', 6000) : false
    const afterLabel = fsVisible ? await fsIcon.getAttribute('aria-label').catch(() => '') : ''
    record(
      2,
      '全屏被拒时给出可见提示（点击落地 + 文案）',
      fsVisible && fsClicked && fsWarned,
      `按钮可见=${fsVisible} 点击=${fsClicked} 提示=${fsWarned}`
    )
    record(
      2,
      '全屏被拒后图标状态不得变化',
      fsVisible && !!beforeLabel && beforeLabel === afterLabel,
      `前=${JSON.stringify(beforeLabel)} 后=${JSON.stringify(afterLabel)}`
    )
    record(2, '全屏桩还原（后续用例不得继承被改造的环境）', await restoreFullscreen(page))
    // 提示自消，避免把"当前可见 message 数"染进后续判据
    await waitToastsCleared(page)
  }

  // 后端 scheduler 已注册——原 record(...,true) 常量假通过改 recordSkip 口径：
  // scheduler 注册状态无 UI/API 探针可断言（启动日志在测试进程外），故走 SKIP 统计
  recordSkip(2, 'scheduler 已注册 login_anomaly_detector', '后端启动日志已确认，无运行时 API 可兜底', null)
}

// ==================== 功能 3：数据备份恢复管理 ====================

async function testFeature3(page) {
  log('=== 功能 3：数据备份恢复管理 ===')
  await page.goto(`${CONFIG.frontendUrl}/monitor/backup`, { waitUntil: 'load' })
  await sleep(2000)
  await skipTour(page)
  await screenshot(page, 'feat3_backup_list')

  // 验证页面加载
  const is404 = await is404Page(page)
  if (is404) {
    record(3, '页面加载', false, '返回 404')
    return
  }
  await assertPageLoaded(page, 3, '页面加载')

  // 验证"创建备份"按钮存在
  const createBtn = page
    .locator(
      'button:has-text("创建备份"), button:has-text("新建备份"), button:has-text("新增"), button:has-text("备份")'
    )
    .first()
  const hasCreateBtn = await createBtn
    .waitFor({ state: 'visible', timeout: 2000 })
    .then(() => true)
    .catch(() => false)
  record(3, '创建备份按钮存在', hasCreateBtn)

  if (hasCreateBtn) {
    // 点击创建备份
    await createBtn.click({ timeout: 3000 }).catch(() => {})
    await sleep(1000)
    // 处理 ElMessageBox.confirm 确认弹窗（前端 backup/index.vue:262 confirmCreate）——
    // 不点确认则请求根本不会发出（此前表格 0 行的根因）
    const confirmBtn = page.locator('.el-message-box__btns button.el-button--primary').first()
    if (
      await confirmBtn
        .waitFor({ state: 'visible', timeout: 2000 })
        .then(() => true)
        .catch(() => false)
    ) {
      await confirmBtn.click({ timeout: 3000 }).catch(() => {})
      log('  已确认创建备份弹窗')
    }
    await sleep(2000)
    await screenshot(page, 'feat3_backup_creating')

    // 等待备份完成（最多 30 秒）
    log('  等待备份完成...')
    for (let i = 0; i < 15; i++) {
      await sleep(2000)
      // 检查是否有成功提示
      const successMsg = page.locator('.el-message--success, text=成功').first()
      if (
        await successMsg
          .waitFor({ state: 'visible', timeout: 500 })
          .then(() => true)
          .catch(() => false)
      ) {
        break
      }
    }
    await screenshot(page, 'feat3_backup_created')

    // 重新加载列表以确保表格刷新
    await page.goto(`${CONFIG.frontendUrl}/monitor/backup`, { waitUntil: 'load' })
    await sleep(2500)
  }

  // 等待表格数据行渲染完成（最多 10 秒）
  log('  等待表格数据加载...')
  let rowCount = 0
  for (let i = 0; i < 10; i++) {
    rowCount = await page
      .locator('.el-table__body-wrapper tbody tr')
      .count()
      .catch(() => 0)
    if (rowCount > 0) break
    await sleep(1000)
  }
  record(3, '备份记录生成', rowCount > 0, `表格行数: ${rowCount}`)

  if (rowCount === 0) {
    // 表格无数据时跳过按钮检测
    record(3, '下载按钮存在', false, '表格无数据，无法检测下载按钮')
    record(3, '删除按钮存在', false, '表格无数据，无法检测删除按钮')
    return
  }

  // 验证下载按钮存在（link 类型按钮在表格行操作列）
  // 策略1: 检查 .el-table 内的按钮文本
  let hasDownloadBtn = await page
    .evaluate(() => {
      const table = document.querySelector('.el-table__body-wrapper') || document.querySelector('.el-table')
      if (!table) return false
      const buttons = Array.from(table.querySelectorAll('button, .el-button, a'))
      return buttons.some((b) => {
        const text = (b.textContent || '').replace(/\s+/g, '')
        return text.includes('下载') || text.includes('download')
      })
    })
    .catch(() => false)

  // 策略2: 如果策略1失败，检查整个页面（可能按钮在固定操作栏）
  if (!hasDownloadBtn) {
    hasDownloadBtn = await page
      .evaluate(() => {
        const buttons = Array.from(document.querySelectorAll('button, .el-button'))
        return buttons.some((b) => {
          const text = (b.textContent || '').replace(/\s+/g, '')
          return text === '下载' || text.includes('下载')
        })
      })
      .catch(() => false)
  }

  // 策略3: 直接查找带 Download 图标的按钮（el-icon 包含 Download 类名）
  if (!hasDownloadBtn) {
    const downloadIconBtn = page.locator('.el-table .el-icon:has(svg), [class*="Download"]').first()
    hasDownloadBtn = (await downloadIconBtn.count().catch(() => 0)) > 0
  }

  record(3, '下载按钮存在', hasDownloadBtn)

  // 同样策略检测删除按钮
  let hasDeleteBtn = await page
    .evaluate(() => {
      const table = document.querySelector('.el-table__body-wrapper') || document.querySelector('.el-table')
      if (!table) return false
      const buttons = Array.from(table.querySelectorAll('button, .el-button, a'))
      return buttons.some((b) => {
        const text = (b.textContent || '').replace(/\s+/g, '')
        return text.includes('删除') || text.includes('delete')
      })
    })
    .catch(() => false)
  if (!hasDeleteBtn) {
    const deleteBtn = page.locator('.el-table button:has-text("删除"), .el-table [class*="Delete"]').first()
    hasDeleteBtn = (await deleteBtn.count().catch(() => 0)) > 0
  }
  record(3, '删除按钮存在', hasDeleteBtn)

  // 端到端验证：点击下载按钮触发实际下载。判定收紧（轮1）：必须观察到 download 事件，
  // 或 /system/backup/download/ 的 200 响应且响应体非空；"按钮可点击即过"是假通过。
  try {
    const downloadPromise = page.waitForEvent('download', { timeout: 60000 }).catch(() => null)
    const responsePromise = page
      .waitForResponse((r) => r.url().includes('/system/backup/download/') && r.status() === 200, { timeout: 60000 })
      .catch(() => null)
    // 点击第一行的下载按钮（el-button link 类型，文本"下载"）
    const downloadBtn = page
      .locator('.el-table__body-wrapper tbody tr')
      .first()
      .locator('button:has-text("下载"), .el-button:has-text("下载")')
      .first()
    if ((await downloadBtn.count()) > 0) {
      // b81 N-8：不用 force；Tour 晚到遮罩由 skipTour 在点击前处理，失败即后续断言红。
      await downloadBtn.click({ timeout: 3000 }).catch(() => {})
      // 「安全提示」MessageBox 只可能来自登录/刷新期的口令态提示（强改密 / 初始口令 / 口令过期，
      // store/modules/user.ts:201-225）；下载链路本身没有确认步骤
      // （views/system/backup/index.vue:334 handleDownload 直接 downloadBackup）。
      // 旧写法把"首启会弹确认框"当成下载的前置条件，对 .el-button--primary 盲等 8s ⇒ 每轮必然超时，
      // 并在点击失败台账里留下一条无法归因的 unrecovered（判据前置从未发生）。
      // 改为按探测结果分支：真出现才点它并判"落地+关闭"，没出现就记下实测的"计数为 0"。
      const mbShown = await page
        .locator('.el-overlay-message-box')
        .first()
        .waitFor({ state: 'visible', timeout: 2000 })
        .then(() => true)
        .catch(() => false)
      if (mbShown) {
        const mbBtn = page
          .locator(
            '.el-overlay-message-box button:has-text("确 定"), .el-overlay-message-box button:has-text("确定"), .el-overlay-message-box .el-button--primary'
          )
          .first()
        const mbClicked = await mbBtn
          .click({ timeout: 3000 })
          .then(() => true)
          .catch(() => false)
        const mbClosed = await page
          .evaluate(() => document.querySelectorAll('.el-overlay-message-box').length === 0)
          .catch(() => false)
        record(
          3,
          '登录期安全提示框：确认点击落地且框已关闭',
          mbClicked && mbClosed,
          `点击落地=${mbClicked}, 关闭=${mbClosed}`
        )
      } else {
        record(
          3,
          '下载链路无确认框（提示框仅来自登录期口令态）',
          !mbShown,
          '点击后 2s 内 .el-overlay-message-box 可见数=0'
        )
      }
      const [download, resp] = await Promise.all([downloadPromise, responsePromise])
      if (download) {
        record(3, '下载功能端到端验证', !!download?.suggestedFilename?.(), `文件: ${download.suggestedFilename()}`)
      } else if (resp) {
        const body = await resp.body().catch(() => null)
        record(3, '下载功能端到端验证', !!body && body.length > 0, `blob 响应 ${body ? body.length : 0} 字节`)
      } else {
        record(3, '下载功能端到端验证', false, '既无 download 事件也无 200 下载响应')
      }
    } else {
      record(3, '下载功能端到端验证', false, '未找到可点击的下载按钮')
    }
  } catch (err) {
    record(3, '下载功能端到端验证', false, `异常: ${err.message.slice(0, 80)}`)
  }
}

