// ==================== 功能 7：邮件通知系统 ====================

async function testFeature7(page) {
  log('=== 功能 7：邮件通知系统 ===')
  await page.goto(`${CONFIG.frontendUrl}/system/notice`, { waitUntil: 'load' })
  await sleep(2000)
  await skipTour(page)
  await screenshot(page, 'feat7_notice_list')

  // 验证页面加载
  const is404 = await is404Page(page)
  if (is404) {
    record(7, '页面加载', false, '返回 404')
    return
  }
  await assertPageLoaded(page, 7, '页面加载')

  // 点击新增按钮
  const addBtn = page.locator('button:has-text("新增"), button:has-text("新建")').first()
  const hasAddBtn = await addBtn
    .waitFor({ state: 'visible', timeout: 2000 })
    .then(() => true)
    .catch(() => false)
  record(7, '新增按钮存在', hasAddBtn)

  if (hasAddBtn) {
    await addBtn.click()
    await sleep(1500)

    // 验证新增对话框弹出
    const dialog = page.locator('.el-dialog:visible').first()
    const dialogVisible = await dialog
      .waitFor({ state: 'visible', timeout: 2000 })
      .then(() => true)
      .catch(() => false)
    record(7, '新增对话框弹出', dialogVisible)

    if (dialogVisible) {
      await screenshot(page, 'feat7_notice_add')

      // 验证邮件通知选项存在（el-form-item label="邮件通知" + el-switch）
      const emailCheckbox = dialog.locator('text=邮件通知').first()
      const hasEmailCheckbox = await emailCheckbox
        .waitFor({ state: 'visible', timeout: 1500 })
        .then(() => true)
        .catch(() => false)
      record(7, '邮件通知选项存在', hasEmailCheckbox)

      // 关闭对话框。**不能用 button:has-text("取消")**：EP 的 autoInsertSpace 把中文双字
      // 按钮渲染成「取 消」，Playwright 的 has-text 不会把中间空格去掉 ⇒ 匹配不到、点击超时，
      // 弹窗连同 modal 遮罩留在页面上，后面所有"搜索区下拉"都被它挡住（实测 3 轮假红）。
      // 右上角关闭按钮与文案无关，且必须等 hidden——否则遮罩仍在 DOM 里拦截指针。
      await dialog
        .locator('.el-dialog__headerbtn')
        .first()
        .click({ timeout: 3000 })
        .catch(() => {})
      await dialog.waitFor({ state: 'hidden', timeout: 3000 }).catch(() => {})
      await sleep(300)
    }
  }

  // 状态筛选（b80）：改造前 DTO 没有 status 字段，serde 静默丢弃 ⇒ 下拉选了值、请求照发、
  // 列表一条不少，是个**假控件**。判据必须证明三件事：请求真的带 status=1、服务端按它过滤
  // （关闭夹具在、正常夹具不在）、且下拉选项确实可交互（不得靠直接改 queryParams 作弊）。
  const login = await apiLogin().catch(() => ({ token: null }))
  if (!login.token) {
    recordSkip(7, '公告状态筛选（关闭态）', 'API token 未取得，无法构造一关闭一正常对照夹具')
  } else {
    const ts = Date.now()
    const closedTitle = `测试关闭公告${ts}`
    const normalTitle = `测试正常公告${ts}`
    const hdr = { Authorization: `Bearer ${login.token}`, 'Content-Type': 'application/json' }
    const mk = (title, status) =>
      apiWithBackoff('/system/notice', {
        method: 'POST',
        headers: hdr,
        body: JSON.stringify({ noticeTitle: title, noticeType: '1', noticeContent: 'e2e status filter', status })
      })
    const mkClosed = await mk(closedTitle, '1')
    const mkNormal = await mk(normalTitle, '0')
    const fixtureOk = mkClosed.body?.code === 200 && mkNormal.body?.code === 200
    record(
      7,
      '状态筛选夹具创建（一条关闭 / 一条正常）',
      fixtureOk,
      `关闭=${mkClosed.body?.code} 正常=${mkNormal.body?.code}`
    )

    let ids = []
    if (fixtureOk) {
      const lookup = await apiWithBackoff(
        `/system/notice/list?pageSize=100&noticeTitle=${encodeURIComponent(ts)}&orderByColumn=createTime&isAsc=desc`,
        { headers: hdr }
      )
      ids = (lookup.body?.rows || []).map((r) => r.noticeId).filter((id) => Number.isFinite(id))
    }

    const requested = page
      .waitForResponse(
        (r) => {
          const u = r.url()
          if (!/\/system\/notice\/list\?/.test(u)) return false
          const qs = (u.split('?')[1] || '') + '&'
          if (/[?&]pageSize=1(&|$)/.test(qs)) return false
          return /(^|&)status=1(&|$)/.test(qs)
        },
        { timeout: 20000 }
      )
      .catch(() => null)
    // 交互必须走真实下拉。EP 2.x 的 placeholder 渲染在 `el-select__placeholder` 而非
    // `<input placeholder>`（用 getByPlaceholder 会 3s 超时、判据假红），改按表单项标签
    // 「状态」作用域定位——表头同名但不在 `.el-form-item__label` 里，不会误命中。
    const statusSelect = page
      .locator('.el-form-item')
      .filter({ has: page.locator('.el-form-item__label:text-is("状态")') })
      .locator('.el-select')
      .first()
    const selectVisible = await statusSelect
      .waitFor({ state: 'visible', timeout: 3000 })
      .then(() => true)
      .catch(() => false)
    let picked = false
    let optionTexts = []
    if (selectVisible) {
      // EP 2.x 的展开热区在 `.el-select__wrapper`；点根节点在部分版本不触发 popper
      await statusSelect
        .locator('.el-select__wrapper')
        .click()
        .catch(() => {})
      const options = page.locator('.el-select-dropdown__item:visible')
      await options
        .first()
        .waitFor({ state: 'visible', timeout: 3000 })
        .catch(() => {})
      optionTexts = await options.allInnerTexts().catch(() => [])
      const option = options.filter({ hasText: /^关闭$/ }).first()
      picked = await option
        .waitFor({ state: 'visible', timeout: 2000 })
        .then(() => true)
        .catch(() => false)
      if (picked) await option.click().catch(() => {})
    }
    const searchBtn = page.locator('.el-form button:has-text("搜索")').first()
    const searchVisible = await searchBtn
      .waitFor({ state: 'visible', timeout: 3000 })
      .then(() => true)
      .catch(() => false)
    if (searchVisible) await searchBtn.click().catch(() => {})
    const resp = await requested
    const body = resp ? await resp.json().catch(() => null) : null
    const rows = body?.rows || []
    const titles = rows.map((r) => String(r.noticeTitle))
    const allClosed = rows.length > 0 && rows.every((r) => String(r.status) === '1')
    record(
      7,
      '状态筛选：下拉可交互且请求真带 status=1，返回全为关闭态（关闭在、正常不在）',
      !!fixtureOk &&
        selectVisible &&
        picked &&
        !!resp &&
        resp.status() === 200 &&
        allClosed &&
        titles.includes(closedTitle) &&
        !titles.includes(normalTitle),
      `下拉可见=${selectVisible} 选中=${picked} 选项=${JSON.stringify(optionTexts).slice(0, 80)} HTTP=${resp ? resp.status() : 0} 行数=${rows.length} 全关闭=${allClosed} 关闭夹具=${titles.includes(closedTitle)} 正常夹具误现=${titles.includes(normalTitle)}`
    )

    // 复原：清掉两条夹具，并清空筛选（避免污染后续功能在同一页面上的断言）
    for (const id of ids) {
      await apiWithBackoff(`/system/notice/${id}`, { method: 'DELETE', headers: hdr })
    }
    record(7, '状态筛选夹具收尾删除', ids.length === 2, `删除 ${ids.length}/2 条`)
  }
}

// ==================== 功能 8：API 限流可视化 ====================

async function testFeature8(page) {
  log('=== 功能 8：API 限流可视化 ===')
  await page.goto(`${CONFIG.frontendUrl}/monitor/rateLimit`, { waitUntil: 'load' })
  await sleep(2000)
  await skipTour(page)

  // 等待表格数据加载完成：骨架屏消失 + 至少一行数据渲染（修复异步取数竞态）
  await page
    .locator('.el-table__row')
    .first()
    .waitFor({ state: 'visible', timeout: 10000 })
    .catch(() => {})

  await screenshot(page, 'feat8_rate_limit_list')

  // 验证页面加载（不是 404）
  const is404 = await is404Page(page)
  if (is404) {
    record(8, '页面加载', false, '返回 404')
    return
  }
  await assertPageLoaded(page, 8, '页面加载')

  // 验证表格存在且含数据行（骨架态不算通过）
  const table = page.locator('.el-table, table').first()
  const hasTable = await table.isVisible().catch(() => false)
  const rowCount = await page
    .locator('.el-table__row')
    .count()
    .catch(() => 0)
  record(8, '限流配置表格', hasTable && rowCount > 0, `行数=${rowCount}`)

  // 验证表格中存在默认全局配置（routePattern='*'，显示为"全局默认" tag）
  // b72 起改为**先按 routePattern=* 过滤再断言**：敏感操作独立限流档位（AGENTS C.10）让
  // sys_rate_limit 从 6 行涨到 25 行，`*` 行被分页翻到后面的页 ⇒ 原"首页可见"断言与
  // 数据量强耦合（b71 同类教训：F118 的环境耦合假失败）。过滤后的断言只依赖真实契约
  // ——「routePattern=* 的行存在，且被渲染成全局默认 tag」，与行数无关。
  const patternInput = page.locator('input[placeholder="请输入路由前缀"]').first()
  const filteredToGlobal = await patternInput
    .fill('*')
    .then(() => page.locator('button:has-text("搜索")').first().click())
    .then(async () => {
      await sleep(900)
      const rows = await page
        .locator('.el-table__row')
        .count()
        .catch(() => 0)
      const tag = await page
        .locator('.el-tag:has-text("全局默认")')
        .first()
        .waitFor({ state: 'visible', timeout: 3000 })
        .then(() => true)
        .catch(() => false)
      return { rows, tag }
    })
    .catch(() => ({ rows: -1, tag: false }))
  record(
    8,
    '默认全局配置存在',
    filteredToGlobal.tag && filteredToGlobal.rows === 1,
    `过滤后行数=${filteredToGlobal.rows}，全局默认 tag=${filteredToGlobal.tag}`
  )

  // 恢复无过滤态（后续 switch/新增按钮断言不依赖过滤结果）
  await page
    .locator('button:has-text("重置")')
    .first()
    .click()
    .catch(() => {})
  await sleep(700)

  // 验证启用状态 switch 开关存在
  const switchBtn = page.locator('.el-table .el-switch').first()
  const hasSwitch = await switchBtn
    .waitFor({ state: 'visible', timeout: 2000 })
    .then(() => true)
    .catch(() => false)
  record(8, '启用状态 switch 开关', hasSwitch)

  // 验证新增按钮存在
  const addBtn = page.locator('button:has-text("新增")').first()
  const hasAddBtn = await addBtn
    .waitFor({ state: 'visible', timeout: 2000 })
    .then(() => true)
    .catch(() => false)
  record(8, '新增按钮存在', hasAddBtn)

  if (hasAddBtn) {
    await addBtn.click()
    await sleep(1500)

    // 验证新增对话框弹出
    const dialog = page.locator('.el-dialog:visible').first()
    const dialogVisible = await dialog
      .waitFor({ state: 'visible', timeout: 2000 })
      .then(() => true)
      .catch(() => false)
    record(8, '新增对话框弹出', dialogVisible)

    if (dialogVisible) {
      await screenshot(page, 'feat8_rate_limit_add')

      // 验证表单字段：路由前缀、桶容量、补充速率、启用状态、描述
      const routePatternInput = dialog.locator('label:has-text("路由前缀")').first()
      const capacityInput = dialog.locator('label:has-text("桶容量")').first()
      const refillInput = dialog.locator('label:has-text("补充速率")').first()
      const descInput = dialog.locator('label:has-text("描述")').first()

      const hasRoutePattern = await routePatternInput
        .waitFor({ state: 'visible', timeout: 1000 })
        .then(() => true)
        .catch(() => false)
      const hasCapacity = await capacityInput
        .waitFor({ state: 'visible', timeout: 1000 })
        .then(() => true)
        .catch(() => false)
      const hasRefill = await refillInput
        .waitFor({ state: 'visible', timeout: 1000 })
        .then(() => true)
        .catch(() => false)
      const hasDesc = await descInput
        .waitFor({ state: 'visible', timeout: 1000 })
        .then(() => true)
        .catch(() => false)
      record(
        8,
        '表单字段完整',
        hasRoutePattern && hasCapacity && hasRefill && hasDesc,
        `路由前缀=${hasRoutePattern}, 桶容量=${hasCapacity}, 补充速率=${hasRefill}, 描述=${hasDesc}`
      )

      // 取消对话框
      const cancelBtn = dialog.locator('button:has-text("取 消"), button:has-text("取消")').first()
      if (
        await cancelBtn
          .waitFor({ state: 'visible', timeout: 1000 })
          .then(() => true)
          .catch(() => false)
      ) {
        await cancelBtn.click({ timeout: 3000 }).catch(() => {})
        await sleep(500)
      }
    }
  }

  // 验证搜索表单
  const searchInput = page.locator('input[placeholder*="路由前缀"], input[placeholder*="route"]').first()
  const hasSearch = await searchInput
    .waitFor({ state: 'visible', timeout: 1500 })
    .then(() => true)
    .catch(() => false)
  record(8, '搜索表单（路由前缀过滤）', hasSearch)
}

