    const roles = infoResp?.roles || []
    // 兼容字符串数组（["common"]）和对象数组（[{roleKey:"common"}]）两种格式
    const roleKeys = roles.map((r) => (typeof r === 'string' ? r : r?.roleKey)).filter(Boolean)
    const hasCommonRole = roleKeys.includes('common')
