// ==================== 功能 93：e2e 孤儿数据巡检（防测试污染，批次五新增）====================
/**
 * 深度提升：历史缺陷复盘——F23 某轮删除失败遗留孤儿菜单（占位 menu_id=4103，
 * 导致 G-11 ensure_upload_config_menu 的 INSERT OR IGNORE 静默失效、OSS 菜单
 * 从未落库）。本功能对 e2e 特征数据做巡检+清理，防同类污染复发。
 */
async function testFeature93(page) {
  log('=== 功能 93：e2e 孤儿数据巡检 ===')
  const { token } = await apiLogin()
  if (!token) {
    record(93, '巡检前置登录', false, 'token 获取失败')
    return
  }
  const authHeaders = { Authorization: `Bearer ${token}` }

  // 1. 孤儿菜单巡检（双特征：path 前缀 + menuName 前缀——批次十三强化）
  // 历史漏检实证：F23 改名行（测试菜单改*）path 特征丢失 ⇒ 4148 被 e2e 孤儿占用、
  // m20261007_000005 的 INSERT OR IGNORE 静默失效，大屏管理菜单从未落库。
  let menuOk = false
  let menuDetail = '无残留'
  try {
    const list = await fetch(`${CONFIG.backendUrl}/system/menu/list?menuName=test-menu-`, { headers: authHeaders })
      .then((r) => r.json())
      .catch(() => null)
    const rows = list?.data || list?.rows || []
    const nameList = await fetch(`${CONFIG.backendUrl}/system/menu/list?menuName=${encodeURIComponent('测试菜单')}`, {
      headers: authHeaders
    })
      .then((r) => r.json())
      .catch(() => null)
    const rowsByName = nameList?.data || nameList?.rows || []
    const seen = new Map()
    for (const r of [...rows, ...rowsByName]) seen.set(r.menuId, r)
    const orphans = [...seen.values()].filter(
      (r) => (r.path || '').startsWith('test-menu-') || (r.menuName || '').startsWith('测试菜单')
    )
    if (orphans.length === 0) {
      menuOk = true
    } else {
      let cleaned = 0
      for (const o of orphans) {
        const del = await fetch(`${CONFIG.backendUrl}/system/menu/${o.menuId}`, {
          method: 'DELETE',
          headers: authHeaders
        })
          .then((r) => r.json())
          .catch(() => null)
        if (del?.code === 200) cleaned++
      }
      menuOk = cleaned === orphans.length
      menuDetail = `发现 ${orphans.length} 个孤儿菜单，清理 ${cleaned} 个`
    }
  } catch (err) {
    menuDetail = `异常: ${err.message.slice(0, 300)}`
  }
  record(93, '孤儿菜单巡检（test-menu-*）', menuOk, menuDetail)

  // 2. e2e 用户残留巡检（userName 含 e2e；admin(1) 永不触碰）
  // 批次十八：修正恒真语义——异常/清理不全必须 FAIL（原 userOk 恒 true，catch 也 PASS）
  let userOk = true
  let userDetail = '无残留'
  try {
    const resp = await fetch(`${CONFIG.backendUrl}/system/user/list?pageNum=1&pageSize=100&userName=e2e`, {
      headers: authHeaders
    })
      .then((r) => r.json())
      .catch(() => null)
    const rows = resp?.rows || []
    const deletable = rows.filter((r) => r.userId !== 1 && /e2e/i.test(r.userName || ''))
    if (deletable.length > 0) {
      let cleaned = 0
      for (const u of deletable) {
        const del = await fetch(`${CONFIG.backendUrl}/system/user/${u.userId}`, {
          method: 'DELETE',
          headers: authHeaders
        })
          .then((r) => r.json())
          .catch(() => null)
        if (del?.code === 200) cleaned++
      }
      userOk = cleaned === deletable.length
      userDetail = `发现 ${deletable.length} 个 e2e 用户残留，清理 ${cleaned} 个`
    }
  } catch (err) {
    userOk = false
    userDetail = `异常: ${err.message.slice(0, 300)}`
  }
  record(93, 'e2e 用户残留巡检', userOk, userDetail)

  // 3. WebHook e2e 残留巡检（hookName e2e_ 前缀；批次三十六新增，覆盖 F78/F83/F103 残留）
  let hookOk = true
  let hookDetail = '无残留'
  try {
    const resp = await fetch(`${CONFIG.backendUrl}/monitor/webHook/list?pageNum=1&pageSize=100`, {
      headers: authHeaders
    })
      .then((r) => r.json())
      .catch(() => null)
    const rows = (resp?.rows || []).filter((r) => (r.hookName || '').startsWith('e2e'))
    if (rows.length > 0) {
      let cleaned = 0
      for (const h of rows) {
        const del = await fetch(`${CONFIG.backendUrl}/monitor/webHook/${h.id}`, {
          method: 'DELETE',
          headers: authHeaders
        })
          .then((r) => r.json())
          .catch(() => null)
        if (del?.code === 200) cleaned++
      }
      hookOk = cleaned === rows.length
      hookDetail = `发现 ${rows.length} 个 e2e hook 残留，清理 ${cleaned} 个`
    }
  } catch (err) {
    hookOk = false
    hookDetail = `异常: ${err.message.slice(0, 300)}`
  }
  record(93, 'e2e WebHook 残留巡检', hookOk, hookDetail)

  // 4. OAuth Provider e2e 残留巡检（providerName e2e_oauth_ 前缀；批次三十六新增）
  let provOk = true
  let provDetail = '无残留'
  try {
    const resp = await fetch(`${CONFIG.backendUrl}/system/oauth/provider/list?pageNum=1&pageSize=100`, {
      headers: authHeaders
    })
      .then((r) => r.json())
      .catch(() => null)
    const rows = (resp?.rows || []).filter((r) => (r.providerName || '').startsWith('e2e_oauth_'))
    if (rows.length > 0) {
      const ids = rows.map((r) => r.providerId).join(',')
      const del = await fetch(`${CONFIG.backendUrl}/system/oauth/provider/${ids}`, {
        method: 'DELETE',
        headers: authHeaders
      })
        .then((r) => r.json())
        .catch(() => null)
      provOk = del?.code === 200
      provDetail = `发现 ${rows.length} 个 e2e provider 残留，清理 del=${del?.code}`
    }
  } catch (err) {
    provOk = false
    provDetail = `异常: ${err.message.slice(0, 300)}`
  }
  record(93, 'e2e OAuth Provider 残留巡检', provOk, provDetail)

  // 5. 报表 e2e 残留巡检（reportCode e2e_rpt_ 前缀；批次三十六新增）
  let rptOk = true
  let rptDetail = '无残留'
  try {
    const resp = await fetch(`${CONFIG.backendUrl}/system/report/list?pageNum=1&pageSize=100`, { headers: authHeaders })
      .then((r) => r.json())
      .catch(() => null)
    const rows = (resp?.rows || []).filter((r) => (r.reportCode || '').startsWith('e2e_rpt_'))
    if (rows.length > 0) {
      let cleaned = 0
      for (const r of rows) {
        const del = await fetch(`${CONFIG.backendUrl}/system/report/${r.reportId}`, {
          method: 'DELETE',
          headers: authHeaders
        })
          .then((x) => x.json())
          .catch(() => null)
        if (del?.code === 200) cleaned++
      }
      rptOk = cleaned === rows.length
      rptDetail = `发现 ${rows.length} 个 e2e 报表残留，清理 ${cleaned} 个`
    }
  } catch (err) {
    rptOk = false
    rptDetail = `异常: ${err.message.slice(0, 300)}`
  }
  record(93, 'e2e 报表残留巡检', rptOk, rptDetail)
}

// ==================== 功能 94：报表数据集页全链（批次十八：G-01 e2e 盲区补齐）====================
async function testFeature94(page) {
  log('=== 功能 94：报表数据集页全链 ===')
  // 批次十八：主流程已 UI 登录（重复登录会互踢会话导致 goto 被踢回首页），直接复用会话
  const token = await page.evaluate(() => {
    const m = document.cookie.match(/Admin-Token=([^;]+)/)
    return (m && m[1]) || localStorage.getItem('Admin-Token') || ''
  })
  if (!token) {
    record(94, '前置登录', false, 'token 获取失败')
    return
  }
  const authHeaders = { Authorization: `Bearer ${token}` }
  const code = `it_ds_e2e_${Date.now()}`

  // 批次十八：tour 遮罩 z-[9998] 会拦截点击——addInitScript 必须在 goto 前预置才于下次导航生效
  await presetTourDisabled(page)
  // 1. 页面可达（菜单 4146）——主流程登录后动态路由 addRoute 异步，立即 goto 会 404 回首页，重试至 URL 命中
  const dsUrl = `${CONFIG.frontendUrl}/system/reportDataset`
  await gotoDynamicRoute(page, dsUrl, 'reportDataset')
  const not404 = !(await is404Page(page))
  record(94, '页面可达（/reportDataset）', not404)
  // 加固：not404 只能证明没落 404 页，补工具栏真实渲染断言
  // （搜索框 aria-label/placeholder=rp.searchByName「按名称搜索」+ rp.preview 前的新增按钮）
  const dsToolbarOk =
    not404 &&
    (await page
      .locator('input[aria-label="按名称搜索"], input[placeholder="按名称搜索"]')
      .first()
      .waitFor({ state: 'visible', timeout: 5000 })
      .then(() => true)
      .catch(() => false)) &&
    (await page
      .getByRole('button', { name: /新增/ })
      .first()
      .isVisible()
      .catch(() => false))
  record(94, 'dataset 工具栏渲染（按名称搜索框+新增按钮）', dsToolbarOk)

  // 2. 新增数据集（无参 SELECT 模板）
  await page.getByRole('button', { name: '新增' }).first().click()
  await page.waitForTimeout(400)
  await page.locator('.el-dialog input').nth(0).fill(code)
  await page.locator('.el-dialog input').nth(1).fill('e2e 数据集')
  const sqlArea = page.locator('.el-dialog textarea')
  if ((await sqlArea.count()) > 0) {
    await sqlArea.first().fill('SELECT user_id, user_name FROM sys_user')
  } else {
    await page.locator('.el-dialog .cm-content').first().click()
    await page.keyboard.type('SELECT user_id, user_name FROM sys_user')
  }
  await page.locator('.el-dialog').getByRole('button', { name: '确 定' }).click()
  await page.waitForTimeout(800)
  const listHit = await fetch(`${CONFIG.backendUrl}/report/dataset/list?pageNum=1&pageSize=50`, {
    headers: authHeaders
  })
    .then((r) => r.json())
    .then((j) => (j.rows || []).some((r) => r.datasetCode === code))
  record(94, '新增数据集落库', listHit)

  // 3. SQL 明文专用端点（admin 持 edit 键 → 200 且含明文）
  const list = await fetch(`${CONFIG.backendUrl}/report/dataset/list?pageNum=1&pageSize=50`, {
    headers: authHeaders
  }).then((r) => r.json())
  const row = (list.rows || []).find((r) => r.datasetCode === code)
  let sqlOk = false
  if (row) {
    const sqlResp = await fetch(`${CONFIG.backendUrl}/report/dataset/${row.datasetId}/sql`, {
      method: 'POST',
      headers: { ...authHeaders, 'Content-Type': 'application/json' },
      body: '{}'
    }).then((r) => r.json())
    sqlOk = sqlResp?.code === 200 && String(sqlResp?.data || '').includes('SELECT user_id')
  }
  record(94, 'SQL 明文端点回填', sqlOk)

  // 3b. 编辑对话框的 SQL 明文回填（批七十六修复点）：后端 DatasetVo 恒不含明文，
  //     修复前打开编辑必是空 textarea——连改名称都被迫重敲整段 SQL（或被必填校验拦死）。
  if (row) {
    // 该页编辑按钮文案取 i18n common.edit = 「修改」（不是「编辑」），两种都容错
    const editBtn = page
      .locator('.el-table__row', { hasText: code })
      .locator('button:has-text("修改"), button:has-text("编辑")')
      .first()
    const editOpened = await editBtn
      .click({ timeout: 4000 })
      .then(() => true)
      .catch(() => false)
    await page.waitForTimeout(1600)
    let prefilled = ''
    const area = page.locator('.el-dialog:visible textarea').first()
    if ((await area.count()) > 0) prefilled = await area.inputValue().catch(() => '')
    record(
      94,
      '编辑对话框 SQL 明文回填（打开即为原 SELECT，不必重敲）',
      editOpened && prefilled.includes('SELECT user_id'),
      `opened=${editOpened} len=${prefilled.length}`
    )
    // 只看不存：关闭对话框，避免把回填内容再写一遍（数据集本身在步骤 5 统一清理）
    const closeBtn2 = page.locator('.el-dialog:visible .el-dialog__headerbtn').first()
    if (await closeBtn2.isVisible().catch(() => false)) {
      await closeBtn2.click()
    } else {
      await page.keyboard.press('Escape')
    }
    await page.waitForTimeout(500)
  } else {
    record(94, '编辑对话框 SQL 明文回填（打开即为原 SELECT，不必重敲）', false, '前置未定位到数据集行')
  }

  // 4. 试跑（UI：rp.preview 按钮 → 预览对话框打开）
  if (row) {
    const previewBtn = page.locator('.el-table__row', { hasText: code }).getByRole('button', { name: '试跑' })
    await previewBtn.click()
    await page.waitForTimeout(1500)
    const dialogVisible =
      (await page.locator('.el-dialog:visible').count()) + (await page.locator('.el-drawer:visible').count())
    record(94, '试跑对话框打开', dialogVisible > 0)
    // 批次十八：Escape 依赖焦点在对话框内（force 点击后不可靠），优先点关闭按钮
    const closeBtn = page.locator('.el-dialog:visible .el-dialog__headerbtn').first()
    if (await closeBtn.isVisible().catch(() => false)) {
      await closeBtn.click()
    } else {
      await page.keyboard.press('Escape')
    }
    await page.waitForTimeout(400)
    const dialogLeft =
      (await page.locator('.el-dialog:visible').count()) + (await page.locator('.el-drawer:visible').count())
    record(94, '试跑对话框已关闭', dialogLeft === 0)
  }

  // 5. 删除 + 列表不再命中（确认框等可见再点；删除落库轮询复查）
  if (row) {
    await page.locator('.el-table__row', { hasText: code }).getByRole('button', { name: '删除' }).click()
    // 批次十八：ElMessageBox 未显式传 confirmButtonText 时按钮文案为 EP locale 默认「确定」
    // （无空格），hasText '确 定' 匹配失败（截图实证）——改结构化定位：主按钮即确认键
    const confirmBtn = page.locator('.el-message-box:visible .el-message-box__btns .el-button--primary').first()
    await confirmBtn.waitFor({ state: 'visible', timeout: 4000 }).catch(() => {})
    if (await confirmBtn.isVisible().catch(() => false)) await confirmBtn.click()
    let gone = false
    for (let i = 0; i < 10; i++) {
      await page.waitForTimeout(600)
      const still = await fetch(`${CONFIG.backendUrl}/report/dataset/list?pageNum=1&pageSize=50`, {
        headers: authHeaders
      })
        .then((r) => r.json())
        .then((j) => (j.rows || []).some((r) => r.datasetCode === code))
      if (!still) {
        gone = true
        break
      }
    }
    record(94, '删除后列表不再命中', gone)
  }
}

// ==================== 功能 95：图驱动审批全链（批次十六/十七核心闭环：按图推进）====================
async function testFeature95(page) {
  log('=== 功能 95：图驱动审批全链（设计器→发布→提交测试单据→审批办结）===')
  // 批次十八：主流程已 UI 登录（重复登录会互踢会话导致 goto 被踢回首页），直接复用会话
  const token = await page.evaluate(() => {
    const m = document.cookie.match(/Admin-Token=([^;]+)/)
    return (m && m[1]) || localStorage.getItem('Admin-Token') || ''
  })
  if (!token) {
    record(95, '前置登录', false, 'token 获取失败')
    return
  }
  const authHeaders = { Authorization: `Bearer ${token}` }
  const code = `it_graph_e2e_${Date.now()}`

  // 1. API 建图 + 发布（两节点：role:common 单审 → role:common 加权 t1；条件 days>3）
  // 批次十八：审批人必须是 role:common（stepby 用户），不能 role:admin——admin 既是提交人
  // （UI 对话框）又是审批人会触发「禁止全链自审」400（探针 v12 实证），与集成测试同范式
  const graph = {
    nodes: [
      { id: 's', type: 'start', name: '开始' },
      {
        id: 'a1',
        type: 'approve',
        name: '主管审批',
        assignees: ['role:common'],
        multi: 'single',
        threshold: 1,
        actions: ['delegate', 'countersign_add', 'countersign_del']
      },
      {
        id: 'a2',
        type: 'approve',
        name: '总监加权',
        assignees: ['role:common'],
        multi: 'weighted',
        threshold: 1,
        actions: ['delegate', 'countersign_add', 'countersign_del']
      },
      { id: 'e', type: 'end', name: '结束' }
    ],
    edges: [
      { from: 's', to: 'a1' },
      { from: 'a1', to: 'a2', condition: { field: 'days', op: '>', value: 3 } },
      { from: 'a1', to: 'e' },
      { from: 'a2', to: 'e' }
    ]
  }
  const addResp = await fetch(`${CONFIG.backendUrl}/system/flow/definition`, {
    method: 'POST',
    headers: { ...authHeaders, 'Content-Type': 'application/json' },
    body: JSON.stringify({ flowCode: code, flowName: 'e2e 图驱动', graphJson: JSON.stringify(graph) })
  }).then((r) => r.json())
  if (addResp?.code !== 200) {
    record(95, 'API 建图', false, JSON.stringify(addResp).slice(0, 200))
    return
  }
  const flowId = addResp.data.flowId
  const pubResp = await fetch(`${CONFIG.backendUrl}/system/flow/definition/publish/${flowId}`, {
    method: 'POST',
    headers: authHeaders
  }).then((r) => r.json())
  record(95, 'API 发布（version+1）', pubResp?.code === 200 && pubResp?.data?.version === 2)

  // 2. UI：设计器列表 → 提交测试单据按钮（批次十七新交互）
  // 主流程登录后动态路由 addRoute 异步——立即 goto 会 404 回首页，重试至 URL 命中
  // 批次十八：tour 遮罩 z-[9998] 会拦截点击——addInitScript 必须在首次 goto 前预置
  await presetTourDisabled(page)
  const flowDefUrl = `${CONFIG.frontendUrl}/system/flowDefinition`
  await gotoDynamicRoute(page, flowDefUrl, 'flowDefinition')
  const submitBtn = page.locator('.el-table__row', { hasText: code }).getByRole('button', { name: '提交测试单据' })
  let btnVisible = (await submitBtn.count()) > 0
  for (let i = 0; i < 5 && !btnVisible; i++) {
    await page.waitForTimeout(1200)
    btnVisible = (await submitBtn.count()) > 0
  }
  record(95, '「提交测试单据」按钮可见（已发布最新版）', btnVisible)
  if (!btnVisible) return
  await submitBtn.click()
  await page.waitForTimeout(500)
  await page.locator('.el-dialog input').first().fill('e2e 图驱动单据（长链）')
  await page.locator('.el-dialog textarea').fill('{\n  "days": 5\n}')
  await page.locator('.el-dialog').getByRole('button', { name: '确 定' }).click()
  await page.waitForTimeout(1000)
  const toastOk = (await page.locator('.el-message', { hasText: '提交成功，审批人待办已生成' }).count()) > 0
  record(95, '提交成功 Toast', toastOk)

  // 3. 审批链：stepby（role:common 成员）推进 → approve a1 → 推进 a2 → approve → 办结
  // 批次十八：待办/动作端点仅登录即可（归属校验在 service 层），用 stepby 独立会话推进
  const sbLogin = await fetch(`${CONFIG.backendUrl}/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username: 'stepby', password: 'admin123' })
  }).then((r) => r.json())
  const sbToken = sbLogin?.data?.token || sbLogin?.token || ''
  if (!sbToken) {
    record(95, 'stepby 前置登录', false, JSON.stringify(sbLogin).slice(0, 120))
    return
  }
  const sbHeaders = { Authorization: `Bearer ${sbToken}` }
  // ⚠️ pageSize 用 100（后端 clamp 上限）：待办可能被前序用例残留数据占据首页，
  //    取 50 会漏掉本次刚提交的单据（实证：积压 50 条 e2e 动作收窄单 → t1 找不到 → 链失败）。
  const todo = await fetch(`${CONFIG.backendUrl}/system/flow/todo?pageNum=1&pageSize=100`, { headers: sbHeaders }).then(
    (r) => r.json()
  )
  const t1 = (todo.rows || []).find((r) => r.bizType === 'flow_graph_doc' && r.title === 'e2e 图驱动单据（长链）')
  let chainOk = false
  if (t1) {
    const act1 = await fetch(`${CONFIG.backendUrl}/system/flow/task/${t1.taskId}/action`, {
      method: 'POST',
      headers: { ...sbHeaders, 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'approve', comment: 'e2e a1' })
    }).then((r) => r.json())
    const todo2 = await fetch(`${CONFIG.backendUrl}/system/flow/todo?pageNum=1&pageSize=50`, {
      headers: sbHeaders
    }).then((r) => r.json())
    const t2 = (todo2.rows || []).find((r) => r.bizType === 'flow_graph_doc' && r.nodeSeq === 2 && r.bizId === t1.bizId)
    if (act1?.code === 200 && t2) {
      const act2 = await fetch(`${CONFIG.backendUrl}/system/flow/task/${t2.taskId}/action`, {
        method: 'POST',
        headers: { ...sbHeaders, 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'approve' })
      }).then((r) => r.json())
      chainOk = act2?.code === 200
    }
  }
  record(95, '按图推进两级审批办结（条件真走长链）', chainOk)

  // 批次十八：自清理测试流程（best-effort——已产生单据的流程可能被引用校验拒绝，静默即可）
  try {
    const listAll = await fetch(`${CONFIG.backendUrl}/system/flow/definition/list?pageNum=1&pageSize=100`, {
      headers: authHeaders
    }).then((r) => r.json())
    const mine = (listAll.rows || []).filter((r) => String(r.flowCode).startsWith('it_graph_e2e_'))
    for (const f of mine) {
      await fetch(`${CONFIG.backendUrl}/system/flow/definition/${f.flowId}`, { method: 'DELETE', headers: authHeaders })
    }
  } catch {
    /* best-effort 清理 */
  }
}

// ==================== 功能 96：actions 白名单收窄（批次十七：未勾 delegate → 403）====================
async function testFeature96(page) {
  log('=== 功能 96：actions 白名单收窄 ===')
  // 批次十八：apiLogin 重复登录会互踢 UI 会话（污染后续功能），复用 page cookie token
  const token = await page.evaluate(() => {
    const m = document.cookie.match(/Admin-Token=([^;]+)/)
    return (m && m[1]) || localStorage.getItem('Admin-Token') || ''
  })
  if (!token) {
    record(96, '前置登录', false, 'token 获取失败')
    return
  }
  const authHeaders = { Authorization: `Bearer ${token}` }
  const code = `it_graph_act_${Date.now()}`

  // 建图（a1 仅勾 countersign_add——不含 delegate；审批人 role:common 避免 admin 自审 400）+ 发布
  const graph = {
    nodes: [
      { id: 's', type: 'start', name: '开始' },
      {
        id: 'a1',
        type: 'approve',
        name: '主管',
        assignees: ['role:common'],
        multi: 'single',
        threshold: 1,
        actions: ['countersign_add']
      },
      { id: 'e', type: 'end', name: '结束' }
    ],
    edges: [
      { from: 's', to: 'a1' },
      { from: 'a1', to: 'e' }
    ]
  }
  const addResp = await fetch(`${CONFIG.backendUrl}/system/flow/definition`, {
    method: 'POST',
    headers: { ...authHeaders, 'Content-Type': 'application/json' },
    body: JSON.stringify({ flowCode: code, flowName: 'e2e 动作收窄', graphJson: JSON.stringify(graph) })
  }).then((r) => r.json())
  const flowId = addResp?.data?.flowId
  if (addResp?.code !== 200 || !flowId) {
    record(96, 'API 建图', false, JSON.stringify(addResp).slice(0, 200))
    return
  }
  await fetch(`${CONFIG.backendUrl}/system/flow/definition/publish/${flowId}`, { method: 'POST', headers: authHeaders })

  // API 提交图驱动单据（days=1 默认边单节点）
  const subResp = await fetch(`${CONFIG.backendUrl}/system/flow/graph/submit`, {
    method: 'POST',
    headers: { ...authHeaders, 'Content-Type': 'application/json' },
    body: JSON.stringify({ flowCode: code, title: 'e2e 动作收窄单', fields: { days: 1 } })
  }).then((r) => r.json())
  const docId = subResp?.data?.docId
  if (subResp?.code !== 200 || !docId) {
    record(96, 'API 提交', false, JSON.stringify(subResp).slice(0, 200))
    return
  }
  // 待办属主 = role:common 成员（stepby）——动作用属主会话调，白名单 403 与属主 403 不混淆
  const sbLogin = await fetch(`${CONFIG.backendUrl}/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username: 'stepby', password: 'admin123' })
  }).then((r) => r.json())
  const sbToken = sbLogin?.data?.token || sbLogin?.token || ''
  if (!sbToken) {
    record(96, 'stepby 前置登录', false, JSON.stringify(sbLogin).slice(0, 120))
    return
  }
  const sbHeaders = { Authorization: `Bearer ${sbToken}` }
  const todo = await fetch(`${CONFIG.backendUrl}/system/flow/todo?pageNum=1&pageSize=50`, { headers: sbHeaders }).then(
    (r) => r.json()
  )
  const t1 = (todo.rows || []).find((r) => r.bizType === 'flow_graph_doc' && r.bizId === docId)
  if (!t1) {
    record(96, '待办出现', false)
    return
  }
  // delegate 未勾 → 403
  const del = await fetch(`${CONFIG.backendUrl}/system/flow/task/${t1.taskId}/action`, {
    method: 'POST',
    headers: { ...sbHeaders, 'Content-Type': 'application/json' },
    body: JSON.stringify({ action: 'delegate', toUserId: 2, comment: '不在白名单' })
  })
  record(96, '未勾 delegate → 403', del.status === 403)
  // countersign_add 在白名单 → 非 403（自委派等业务校验可能 400，但不是白名单 403）
  const csAdd = await fetch(`${CONFIG.backendUrl}/system/flow/task/${t1.taskId}/action`, {
    method: 'POST',
    headers: { ...sbHeaders, 'Content-Type': 'application/json' },
    body: JSON.stringify({ action: 'countersign_add', toUserId: 2 })
  })
  record(96, '勾选 countersign_add 非 403（白名单放行到业务校验）', csAdd.status !== 403)

  // 批次二十五：办结本单据（days=1 默认边为单节点，approve 一次即办结），
  // 防止待办长期积压淹没后续「我的待办」查询（实测积压 50 条致功能 95 链失败）。
  try {
    // 加签可能已改变节点形态——重新取该单据当前待办再办结（best-effort）
    const todoNow = await fetch(`${CONFIG.backendUrl}/system/flow/todo?pageNum=1&pageSize=100`, {
      headers: sbHeaders
    }).then((r) => r.json())
    const tn = (todoNow.rows || []).find((r) => r.bizType === 'flow_graph_doc' && r.bizId === docId)
    if (tn) {
      await fetch(`${CONFIG.backendUrl}/system/flow/task/${tn.taskId}/action`, {
        method: 'POST',
        headers: { ...sbHeaders, 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'approve', comment: 'e2e 清理办结' })
      }).catch(() => {})
    }
  } catch {
    /* best-effort 办结 */
  }

  // 批次十八：自清理测试流程（best-effort）
  try {
    const listAll = await fetch(`${CONFIG.backendUrl}/system/flow/definition/list?pageNum=1&pageSize=100`, {
      headers: authHeaders
    }).then((r) => r.json())
    const mine = (listAll.rows || []).filter((r) => String(r.flowCode).startsWith('it_graph_act_'))
    for (const f of mine) {
      await fetch(`${CONFIG.backendUrl}/system/flow/definition/${f.flowId}`, { method: 'DELETE', headers: authHeaders })
    }
  } catch {
    /* best-effort 清理 */
  }
}

