// ==================== 批次三十六新增 feature 102-109 ====================
// 目标：OAuth Provider 管理 UI / WebHook UI 链 / 用户详情与角色分配 UI / SSO 同意页 UI /
//       个人中心安全 Tab 深交互 / 报表管理 UI / 表单构建器冒烟 / 详情页渲染扫描
// 约定：waitFor/waitForResponse 替代固定 sleep；Escape 关 EP dialog；
//       ElMessageBox 主按钮 .el-message-box__btns .el-button--primary；有状态用例尾部恢复初态。

/** 批次三十六公共：复用主流程 UI 会话 token（对齐 F94 范式，避免 apiLogin 互踢） */
async function sessionTokenOf(page) {
  return page.evaluate(() => {
    const m = document.cookie.match(/Admin-Token=([^;]+)/)
    return (m && m[1]) || localStorage.getItem('Admin-Token') || ''
  })
}

// ==================== 功能 102：OAuth Provider 管理 UI 全链 ====================
async function testFeature102(page) {
  log('=== 功能 102：OAuth Provider 管理 UI 全链 ===')
  const token = await sessionTokenOf(page)
  if (!token) {
    record(102, '前置登录', false, 'token 获取失败')
    return
  }
  const authHeaders = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }
  const ts = Date.now().toString(36)
  const pname = `e2e_oauth_${ts}`
  const pcode = `e2eoa${ts}`

  // 1. 页面可达（动态路由重试）+ 表格渲染（有行或空态标记均算渲染成功）
  await presetTourDisabled(page)
  await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/oauth/provider`, 'oauth/provider')
  await skipTour(page)
  const not404 = !(await is404Page(page))
  await page
    .locator('.el-table')
    .first()
    .waitFor({ state: 'visible', timeout: 8000 })
    .catch(() => {})
  const tableOk =
    (await page.locator('.el-table__row').count()) > 0 ||
    (await page.locator('.el-table .el-empty, .el-table__empty-block').count()) > 0
  record(102, '① 列表页可达且表格渲染', not404 && tableOk, `not404=${not404}, table=${tableOk}`)

  // 2. 新增对话框：空提交触发必填校验错误（负路径）
  let negOk = false
  try {
    await page
      .getByRole('button', { name: /新增提供商|新增/ })
      .first()
      .click()
    const dialog = page.locator('.el-dialog:visible').last()
    await dialog.waitFor({ state: 'visible', timeout: 4000 })
    await dialog
      .getByRole('button', { name: /确\s*定|确定/ })
      .first()
      .click()
    await page.waitForTimeout(600)
    negOk = (await dialog.locator('.el-form-item.is-error').count()) > 0
    await page.keyboard.press('Escape')
    await page.waitForTimeout(400)
  } catch (err) {
    log(`  F102 负路径异常: ${err.message.slice(0, 120)}`)
  }
  record(102, '② 空提交触发表单校验错误（负路径）', negOk)

  // 3. 合法创建（IP 字面量+封闭端口授权地址，禁外网）
  let createdOk = false
  try {
    await page
      .getByRole('button', { name: /新增提供商|新增/ })
      .first()
      .click()
    const dialog = page.locator('.el-dialog:visible').last()
    await dialog.waitFor({ state: 'visible', timeout: 4000 })
    const item = (label) =>
      dialog.locator('.el-form-item').filter({ has: page.locator(`.el-form-item__label:text-is("${label}")`) })
    await item('提供商名称').locator('input').first().fill(pname)
    await item('提供商编码').locator('input').first().fill(pcode)
    // providerType 默认 github（defaultForm），无需切换
    await item('Client ID').locator('input').first().fill(`e2e_client_${ts}`)
    await item('Client Secret').locator('input').first().fill(`e2e_secret_${ts}`)
    await item('授权端点').locator('input').first().fill('http://1.1.1.1:81/authorize')
    await item('令牌端点').locator('input').first().fill('http://1.1.1.1:81/token')
    await item('用户信息端点').locator('input').first().fill('http://1.1.1.1:81/userinfo')
    const respPromise = page.waitForResponse(
      (r) => r.url().includes('/system/oauth/provider') && r.request().method() === 'POST' && r.status() === 200,
      { timeout: 10000 }
    )
    await dialog
      .getByRole('button', { name: /确\s*定|确定/ })
      .first()
      .click()
    const resp = await respPromise.catch(() => null)
    createdOk = !!resp
    record(102, '③ 合法创建 provider（POST 200）', createdOk, createdOk ? `name=${pname}` : '未捕获创建响应')
  } catch (err) {
    record(102, '③ 合法创建 provider（POST 200）', false, `异常: ${err.message.slice(0, 120)}`)
  }

  // 搜索定位新建行（等 URL 带查询参数的响应，避免旧快照）
  let row = null
  let rowVisible = false
  let settleMs = -1
  if (createdOk) {
    try {
      const searchPromise = page.waitForResponse(
        (r) =>
          r.url().includes('/system/oauth/provider/list') &&
          r.url().includes(`providerName=${pname}`) &&
          r.status() === 200,
        { timeout: 10000 }
      )
      await page.locator('input[placeholder*="提供商名称"]').first().fill(pname)
      await page.getByRole('button', { name: /搜索/ }).first().click()
      await searchPromise
      row = page.locator('.el-table__row').filter({ hasText: pname }).first()
      // 该页走 `useCrudTable`：搜索会 `syncUrlQuery → router.replace`，表格存在**卸载→重挂的空白窗口**
      // （b82 的 F52 那条竞态是同一机制）。旧写法"响应到后再看一眼"必然踩在这个窗口上——
      // 六段全量里它失败、单跑恒绿（b83 实测两种结局都出现过），而且这一眼还是**后续四步的门**，
      // 于是一次竞态能吞掉 6 条判据。改成轮询到落定，并把落定耗时写进凭证。
      const t0 = Date.now()
      for (let i = 0; i < 24; i++) {
        rowVisible = await row.isVisible().catch(() => false)
        if (rowVisible) break
        await sleep(250)
      }
      settleMs = Date.now() - t0
    } catch (err) {
      log(`  F102 搜索定位异常: ${err.message.slice(0, 120)}`)
    }
    record(102, '③b 列表搜索命中新建行', rowVisible, `轮询到落定 ${settleMs}ms`)
  }

  // 4. 编辑对话框：clientSecret 不明文回显（后端脱敏，仅创建时明文一次）
  if (rowVisible) {
    try {
      await row.getByRole('button', { name: /编辑/ }).first().click()
      const dialog = page.locator('.el-dialog:visible').last()
      await dialog.waitFor({ state: 'visible', timeout: 4000 })
      const secretInput = dialog
        .locator('.el-form-item')
        .filter({ has: page.locator('.el-form-item__label:text-is("Client Secret")') })
        .locator('input')
        .first()
      const secretVal = await secretInput.inputValue().catch(() => '<missing>')
      const noPlaintext = secretVal === '' || !secretVal.includes(`e2e_secret_${ts}`)
      record(102, '③c 编辑对话框 secret 不明文回显', noPlaintext, `len=${secretVal.length}`)
      await page.keyboard.press('Escape')
      await page.waitForTimeout(400)
    } catch (err) {
      record(102, '③c 编辑对话框 secret 不明文回显', false, `异常: ${err.message.slice(0, 120)}`)
    }

    // 5. 停用→启用开关（PUT /status 200 且状态往返）
    try {
      const sw = row.locator('.el-switch').first()
      const offPromise = page.waitForResponse(
        (r) => r.url().includes('/status') && r.request().method() === 'PUT' && r.status() === 200,
        { timeout: 8000 }
      )
      await sw.click()
      const offResp = await offPromise.catch(() => null)
      await page.waitForTimeout(600)
      const offOk = !!offResp
      const onPromise = page.waitForResponse(
        (r) => r.url().includes('/status') && r.request().method() === 'PUT' && r.status() === 200,
        { timeout: 8000 }
      )
      await sw.click()
      const onResp = await onPromise.catch(() => null)
      await page.waitForTimeout(600)
      record(102, '④ 停用/启用开关往返（PUT /status 200）', offOk && !!onResp, `off=${!!offResp}, on=${!!onResp}`)
    } catch (err) {
      record(102, '④ 停用/启用开关往返（PUT /status 200）', false, `异常: ${err.message.slice(0, 120)}`)
    }

    // 6. 删除确认「取消」→ 记录仍在 → 确认删除 → 行消失 + API 复核
    try {
      await row.getByRole('button', { name: /删除/ }).first().click()
      const box = page.locator('.el-message-box:visible').first()
      await box.waitFor({ state: 'visible', timeout: 4000 })
      await box.locator('.el-message-box__btns button:not(.el-button--primary)').first().click()
      await page.waitForTimeout(600)
      const stillThere = await row.isVisible().catch(() => false)
      record(102, '⑤ 删除确认弹「取消」→ 记录仍在', stillThere)
      const apiBefore = await fetch(
        `${CONFIG.backendUrl}/system/oauth/provider/list?pageNum=1&pageSize=10&providerName=${pname}`,
        { headers: authHeaders }
      )
        .then((r) => r.json())
        .catch(() => null)
      record(
        102,
        '⑤b 取消后 API 复核记录仍在',
        (apiBefore?.rows || []).some((r) => r.providerName === pname)
      )

      await row.getByRole('button', { name: /删除/ }).first().click()
      const box2 = page.locator('.el-message-box:visible').first()
      await box2.waitFor({ state: 'visible', timeout: 4000 })
      const delPromise = page.waitForResponse(
        (r) => r.url().includes('/system/oauth/provider/') && r.request().method() === 'DELETE' && r.status() === 200,
        { timeout: 8000 }
      )
      await box2.locator('.el-message-box__btns .el-button--primary').first().click()
      const delResp = await delPromise.catch(() => null)
      await page.waitForTimeout(800)
      const gone = !(await row.isVisible().catch(() => false))
      record(102, '⑥ 确认删除 → 行消失（DELETE 200）', !!delResp && gone, `del=${!!delResp}, gone=${gone}`)
      const apiAfter = await fetch(
        `${CONFIG.backendUrl}/system/oauth/provider/list?pageNum=1&pageSize=10&providerName=${pname}`,
        { headers: authHeaders }
      )
        .then((r) => r.json())
        .catch(() => null)
      record(102, '⑥b API 复核已删除（自清完成）', (apiAfter?.rows || []).length === 0)
    } catch (err) {
      record(102, '⑥ 删除链', false, `异常: ${err.message.slice(0, 120)}`)
    }
  }

  // 兜底自清（防中途失败残留）
  try {
    const list = await fetch(
      `${CONFIG.backendUrl}/system/oauth/provider/list?pageNum=1&pageSize=50&providerName=e2e_oauth_`,
      { headers: authHeaders }
    )
      .then((r) => r.json())
      .catch(() => null)
    const ids = (list?.rows || []).map((r) => r.providerId)
    if (ids.length > 0)
      await fetch(`${CONFIG.backendUrl}/system/oauth/provider/${ids.join(',')}`, {
        method: 'DELETE',
        headers: authHeaders
      })
  } catch {
    /* best-effort */
  }
  await dismissAllOverlays(page)
}

// ==================== 功能 103：WebHook UI 链 ====================
async function testFeature103(page) {
  log('=== 功能 103：WebHook UI 链 ===')
  const token = await sessionTokenOf(page)
  if (!token) {
    record(103, '前置登录', false, 'token 获取失败')
    return
  }
  const authHeaders = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }
  const hookName = `e2e_hookui_${Date.now().toString(36)}`
  // IP 字面量 + 封闭端口（e2e 禁外网 URL，同 F78 口径）
  const target = 'http://1.1.1.1:81/hook'

  // 0. API 建 hook（复用 F81 建数口径）
  const created = await fetch(`${CONFIG.backendUrl}/monitor/webHook`, {
    method: 'POST',
    headers: authHeaders,
    body: JSON.stringify({
      hookName,
      targetUrl: target,
      subscribedEvents: ['login.success'],
      contentType: 'json',
      timeoutSecs: 2,
      status: '0'
    })
  })
    .then((r) => r.json())
    .catch(() => null)
  record(103, '⓪ API 建 hook', created?.code === 200, `code=${created?.code}`)
  if (created?.code !== 200) return
  const hlist = await fetch(
    `${CONFIG.backendUrl}/monitor/webHook/list?pageNum=1&pageSize=10&hookName=${encodeURIComponent(hookName)}`,
    { headers: authHeaders }
  )
    .then((r) => r.json())
    .catch(() => null)
  const hookId = hlist?.rows?.[0]?.id

  try {
    // 1. 打开 /system/webHook，搜索后断言列表含该 hook
    await presetTourDisabled(page)
    await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/webHook/index`, 'webHook/index')
    await skipTour(page)
    const searchPromise = page.waitForResponse(
      (r) =>
        r.url().includes('/monitor/webHook/list') &&
        r.url().includes(`hookName=${encodeURIComponent(hookName)}`) &&
        r.status() === 200,
      { timeout: 10000 }
    )
    await page.locator('input[placeholder*="回调名称"], input[aria-label*="回调名称"]').first().fill(hookName)
    await page.getByRole('button', { name: /搜索/ }).first().click()
    await searchPromise
    // 高负载下（如 backup 慢查询挤压）行渲染可能滞后：行未现时重试搜索（条件轮询，最多 3 轮）
    let rowOk = false
    for (let attempt = 0; attempt < 3 && !rowOk; attempt++) {
      const retrySearch = page.waitForResponse(
        (r) =>
          r.url().includes('/monitor/webHook/list') &&
          r.url().includes(`hookName=${encodeURIComponent(hookName)}`) &&
          r.status() === 200,
        { timeout: 10000 }
      )
      await page.getByRole('button', { name: /搜索/ }).first().click()
      await retrySearch
      const row = page.locator('.el-table__row').filter({ hasText: hookName }).first()
      rowOk = await row
        .waitFor({ state: 'visible', timeout: 5000 })
        .then(() => true)
        .catch(() => false)
      if (!rowOk) await sleep(1200)
    }
    record(103, '① 列表含 API 预建 hook', rowOk)

    // 2. 事件目录（EventCatalogSection）：打开对话框，目录项 > 0
    let catalogOk = false
    try {
      let dlg = page.locator('.el-dialog:visible').last()
      // tour 可能晚到拦截点击：重试（每次先 skipTour 清理覆盖层/软提示）
      for (let i = 0; i < 3 && !catalogOk; i++) {
        await skipTour(page)
        await page
          .getByRole('button', { name: /事件目录/ })
          .first()
          .click()
        dlg = page.locator('.el-dialog:visible').last()
        catalogOk = await dlg
          .waitFor({ state: 'visible', timeout: 3000 })
          .then(() => true)
          .catch(() => false)
        if (!catalogOk) {
          log(
            `  [diag-103②] try ${i}: btnCount=${await page.getByRole('button', { name: /事件目录/ }).count()}, dlgTotal=${await page.locator('.el-dialog').count()}, tour=${(await skipTour) && ''}${await page.locator('[class*="tour"]').count()}`
          )
        }
      }
      // 目录行（表格行或列表项）> 0
      let items = 0
      for (let i = 0; i < 8; i++) {
        items = await dlg.locator('.el-table__row, .el-dropdown-menu__item, .event-item, li').count()
        if (items > 0) break
        await page.waitForTimeout(500)
      }
      catalogOk = items > 0
      await page.keyboard.press('Escape')
      await page.waitForTimeout(400)
    } catch (err) {
      log(`  F103 事件目录异常: ${err.message.slice(0, 120)}`)
    }
    record(103, '② 事件目录对话框打开且目录项 > 0', catalogOk)
  } catch (err) {
    record(103, '① 列表含 API 预建 hook', false, `异常: ${err.message.slice(0, 120)}`)
    record(103, '② 事件目录对话框打开且目录项 > 0', false, '前置失败')
  }

  // 3. /system/webHook/log 日志页：筛选控件可达、表格或空态渲染
  try {
    await presetTourDisabled(page)
    await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/webHook/log`, 'webHook/log')
    await skipTour(page)
    const not404 = !(await is404Page(page))
    const filterOk =
      (await page
        .locator('form.el-form--inline')
        .first()
        .waitFor({ state: 'visible', timeout: 4000 })
        .then(() => true)
        .catch(() => false)) ||
      (await page
        .locator('.el-form-item')
        .first()
        .waitFor({ state: 'visible', timeout: 2000 })
        .then(() => true)
        .catch(() => false))
    const tableOk =
      (await page.locator('.el-table__row').count()) > 0 ||
      (await page.locator('.el-table .el-empty, .el-table__empty-block').count()) > 0
    record(
      103,
      '③ 日志页筛选可达且表格/空态渲染',
      not404 && filterOk && tableOk,
      `404=${!not404}, filter=${filterOk}, table=${tableOk}`
    )
  } catch (err) {
    record(103, '③ 日志页筛选可达且表格/空态渲染', false, `异常: ${err.message.slice(0, 120)}`)
  }

  // 4. 删除确认取消路径（回到列表页）
  try {
    await presetTourDisabled(page)
    await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/webHook/index`, 'webHook/index')
    await skipTour(page)
    const searchPromise = page.waitForResponse(
      (r) =>
        r.url().includes('/monitor/webHook/list') &&
        r.url().includes(`hookName=${encodeURIComponent(hookName)}`) &&
        r.status() === 200,
      { timeout: 10000 }
    )
    await page.locator('input[placeholder*="回调名称"], input[aria-label*="回调名称"]').first().fill(hookName)
    await page.getByRole('button', { name: /搜索/ }).first().click()
    await searchPromise
    const row = page.locator('.el-table__row').filter({ hasText: hookName }).first()
    if (
      await row
        .waitFor({ state: 'visible', timeout: 5000 })
        .then(() => true)
        .catch(() => false)
    ) {
      await row.getByRole('button', { name: /删除/ }).first().click()
      const box = page.locator('.el-message-box:visible').first()
      await box.waitFor({ state: 'visible', timeout: 4000 })
      await box.locator('.el-message-box__btns button:not(.el-button--primary)').first().click()
      await page.waitForTimeout(600)
      const stillThere = await row.isVisible().catch(() => false)
      record(103, '④ 删除确认「取消」→ 记录仍在', stillThere)
    } else {
      record(103, '④ 删除确认「取消」→ 记录仍在', false, '未找到 hook 行')
    }
  } catch (err) {
    record(103, '④ 删除确认「取消」→ 记录仍在', false, `异常: ${err.message.slice(0, 120)}`)
  }

  // 清理：API 删除 hook（自清）
  if (hookId) {
    const del = await fetch(`${CONFIG.backendUrl}/monitor/webHook/${hookId}`, {
      method: 'DELETE',
      headers: authHeaders
    })
      .then((r) => r.json())
      .catch(() => null)
    record(103, '⑤ 清理：API 删除 hook', del?.code === 200, `code=${del?.code}`)
  }
  await dismissAllOverlays(page)
}

// ==================== 功能 104：用户详情与角色/用户分配 UI 链 ====================
async function testFeature104(page) {
  log('=== 功能 104：用户详情与角色/用户分配 UI 链 ===')
  const token = await sessionTokenOf(page)
  if (!token) {
    record(104, '前置登录', false, 'token 获取失败')
    return
  }
  const authHeaders = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }
  const uname = `e2e_view_${Date.now().toString(36)}`
  let uid = null

  // 0. API 建临时用户（F62 口径；roleIds 留空——留出未持有角色供 ②b 勾选）
  try {
    const created = await fetch(`${CONFIG.backendUrl}/system/user`, {
      method: 'POST',
      headers: authHeaders,
      body: JSON.stringify({
        deptId: 100,
        userName: uname,
        nickName: `详情测试${uname.slice(-6)}`,
        password: 'Test@12345',
        phonenumber: e2ePhone(),
        email: 'e2e_view@example.com',
        sex: '0',
        status: '0',
        roleIds: [],
        postIds: []
      })
    }).then((r) => r.json())
    const list = await fetch(
      `${CONFIG.backendUrl}/system/user/list?userName=${encodeURIComponent(uname)}&pageSize=10`,
      { headers: authHeaders }
    ).then((r) => r.json())
    uid = (list?.rows || []).find((r) => r.userName === uname)?.userId ?? null
    record(104, '⓪ API 建临时用户', created?.code === 200 && uid != null, `code=${created?.code}, uid=${uid}`)
  } catch (err) {
    record(104, '⓪ API 建临时用户', false, `异常: ${err.message.slice(0, 120)}`)
  }
  if (!uid) return

  try {
    // 1. 列表行点击账号名 → /system/user/view 详情抽屉
    await presetTourDisabled(page)
    await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/user`, '/system/user')
    await skipTour(page)
    const searchPromise = page.waitForResponse(
      (r) => r.url().includes('/system/user/list') && r.url().includes(`userName=${uname}`) && r.status() === 200,
      { timeout: 10000 }
    )
    await page.locator('input[placeholder="请输入用户名称"]').first().fill(uname)
    await page.getByRole('button', { name: /搜索/ }).first().click()
    await searchPromise
    // 全量跑时后端偏慢：行渲染最多等 8s，未命中再搜一次
    const row = page.locator('.el-table__row').filter({ hasText: uname }).first()
    let rowOk = await row
      .waitFor({ state: 'visible', timeout: 8000 })
      .then(() => true)
      .catch(() => false)
    if (!rowOk) {
      await page
        .getByRole('button', { name: /搜索/ })
        .first()
        .click()
        .catch(() => {})
      await page.waitForTimeout(2000)
      rowOk = await row
        .waitFor({ state: 'visible', timeout: 5000 })
        .then(() => true)
        .catch(() => false)
    }
    record(104, '① 搜索定位临时用户行', rowOk)
    if (rowOk) {
      await row.locator('a.el-link, .el-link').first().click()
      const drawer = page.locator('.el-drawer:visible').first()
      const drawerOk = await drawer
        .waitFor({ state: 'visible', timeout: 5000 })
        .then(() => true)
        .catch(() => false)
      // 详情字段非空渲染：账号名出现
      let fieldOk = false
      if (drawerOk) {
        for (let i = 0; i < 6; i++) {
          const txt = await drawer.innerText().catch(() => '')
          if (txt.includes(uname)) {
            fieldOk = true
            break
          }
          await page.waitForTimeout(500)
        }
      }
      record(104, '①b 详情抽屉打开且账号字段非空渲染', drawerOk && fieldOk, `drawer=${drawerOk}, field=${fieldOk}`)
      await page.keyboard.press('Escape')
      await page.waitForTimeout(500)
    }

    // 2. authRole 页：勾选一个未持有角色 → 保存 → API 回读含该角色 → 取消勾选恢复
    await presetTourDisabled(page)
    await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/user-auth/role/${uid}`, 'user-auth/role')
    await skipTour(page)
    const roleTableOk = await page
      .locator('.el-table')
      .first()
      .waitFor({ state: 'visible', timeout: 5000 })
      .then(() => true)
      .catch(() => false)
    record(104, '② authRole 页表格渲染', roleTableOk)
    if (roleTableOk) {
      // 取当前角色集合：后端 GET /system/user/authRole/{uid} 的 roles 不含 flag（产品缺陷，见报告），
      // 因此用 GET /system/user/{uid} 顶层 roleIds 作为已持有角色真值
      const userBefore = await fetch(`${CONFIG.backendUrl}/system/user/${uid}`, { headers: authHeaders })
        .then((r) => r.json())
        .catch(() => null)
      const rolesList = await fetch(`${CONFIG.backendUrl}/system/role/list?pageNum=1&pageSize=50`, {
        headers: authHeaders
      })
        .then((r) => r.json())
        .catch(() => null)
      const rolesAll = rolesList?.rows || []
      const currentRoleIds = (userBefore?.roleIds || []).map(Number)
      const candidate = rolesAll.find(
        (r) => r.status === '0' && !currentRoleIds.includes(Number(r.roleId)) && r.roleKey !== 'admin'
      )
      if (candidate) {
        const targetRoleId = Number(candidate.roleId)
        const rows = page.locator('.el-table__row')
        let clicked = false
        const n = await rows.count()
        for (let i = 0; i < n; i++) {
          const txt = await rows
            .nth(i)
            .innerText()
            .catch(() => '')
          if (new RegExp(`\\b${targetRoleId}\\b`).test(txt)) {
            await rows.nth(i).locator('.el-checkbox').first().click()
            clicked = true
            break
          }
        }
        if (clicked) {
          const savePromise = page.waitForResponse(
            (r) => r.url().includes('/system/user/authRole') && r.request().method() === 'PUT' && r.status() === 200,
            { timeout: 8000 }
          )
          await page
            .getByRole('button', { name: /提交|保存/ })
            .first()
            .click()
          const saveResp = await savePromise.catch(() => null)
          await page.waitForTimeout(1000)
          const userAfter = await fetch(`${CONFIG.backendUrl}/system/user/${uid}`, { headers: authHeaders })
            .then((r) => r.json())
            .catch(() => null)
          const afterIds = (userAfter?.roleIds || []).map(Number)
          const granted = afterIds.includes(targetRoleId)
          record(
            104,
            '②b 勾选角色保存 → API 回读含该角色',
            !!saveResp && granted,
            `role=${targetRoleId}, save=${!!saveResp}, ids=[${afterIds.join(',')}]`
          )
          // 取消勾选恢复初态（重新进入 authRole 页操作）
          await presetTourDisabled(page)
          await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/user-auth/role/${uid}`, 'user-auth/role')
          const rows2 = page.locator('.el-table__row')
          const n2 = await rows2.count()
          for (let i = 0; i < n2; i++) {
            const txt = await rows2
              .nth(i)
              .innerText()
              .catch(() => '')
            if (new RegExp(`\\b${targetRoleId}\\b`).test(txt)) {
              const cb = rows2.nth(i).locator('.el-checkbox').first()
              // 仅在确实处于勾选态时点击取消（authRole 预检查依赖后端 flag，产品缺陷可能致复选框未勾选）
              const checked = await cb.evaluate((el) => el.classList.contains('is-checked')).catch(() => false)
              if (checked) await cb.click()
              break
            }
          }
          const restorePromise = page.waitForResponse(
            (r) => r.url().includes('/system/user/authRole') && r.request().method() === 'PUT' && r.status() === 200,
            { timeout: 8000 }
          )
          await page
            .getByRole('button', { name: /提交|保存/ })
            .first()
            .click()
          await restorePromise.catch(() => null)
          await page.waitForTimeout(1000)
          const userRestored = await fetch(`${CONFIG.backendUrl}/system/user/${uid}`, { headers: authHeaders })
            .then((r) => r.json())
            .catch(() => null)
          const restoredIds = (userRestored?.roleIds || []).map(Number)
          record(
            104,
            '②c 取消勾选恢复初态（不含该角色）',
            !restoredIds.includes(targetRoleId),
            `ids=[${restoredIds.join(',')}]`
          )
        } else {
          record(104, '②b 勾选角色保存 → API 回读含该角色', false, `未在表格中定位角色 ${targetRoleId}`)
        }
      } else {
        // 测试债轮：SKIP 补 API 200 兜底（角色列表可读即环境健康），不再空记 PASS
        const fb = await apiWithBackoff('/system/role/list?pageNum=1&pageSize=1', { headers: authHeaders })
        recordSkip(104, '②b 勾选角色保存 → API 回读含该角色', '无未持有的非 admin 启用角色可勾选', fb.status === 200)
      }
    }

    // 3. authUser 页（/system/role-auth/user/2，common 角色）：表格渲染 + 取消授权该用户
    //    注：用角色 2（common）而非超管角色 1——向超管角色挂业务用户受后端保护，以可用等价角色执行
    await presetTourDisabled(page)
    await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/role-auth/user/2`, 'role-auth/user')
    await skipTour(page)
    const authTableOk = await page
      .locator('.el-table')
      .first()
      .waitFor({ state: 'visible', timeout: 5000 })
      .then(() => true)
      .catch(() => false)
    record(104, '③ authUser 页表格渲染（role 2）', authTableOk)
    if (authTableOk) {
      // 先经 API 把临时用户挂到角色 2，制造可取消授权的真实前提（PUT + query params，对齐前端 api/system/role.ts）
      const bind = await fetch(`${CONFIG.backendUrl}/system/role/authUser/selectAll?roleId=2&userIds=${uid}`, {
        method: 'PUT',
        headers: authHeaders
      })
        .then((r) => r.json())
        .catch(() => null)
      if (bind?.code === 200) {
        // 刷新 authUser 页并搜索
        await presetTourDisabled(page)
        await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/role-auth/user/2`, 'role-auth/user')
        const searchPromise2 = page.waitForResponse(
          (r) =>
            r.url().includes('/system/role/authUser/allocatedList') &&
            r.url().includes('userName=') &&
            r.status() === 200,
          { timeout: 10000 }
        )
        const searchInput2 = page.locator('input[placeholder*="用户名称"], input[placeholder*="账号"]').first()
        if (
          await searchInput2
            .waitFor({ state: 'visible', timeout: 3000 })
            .then(() => true)
            .catch(() => false)
        ) {
          await searchInput2.fill(uname)
          await page.getByRole('button', { name: /搜索/ }).first().click()
          await searchPromise2.catch(() => null)
        }
        const uRow = page.locator('.el-table__row').filter({ hasText: uname }).first()
        if (
          await uRow
            .waitFor({ state: 'visible', timeout: 5000 })
            .then(() => true)
            .catch(() => false)
        ) {
          const cancelPromise = page.waitForResponse(
            (r) =>
              r.url().includes('/system/role/authUser/cancel') && r.request().method() === 'PUT' && r.status() === 200,
            { timeout: 8000 }
          )
          await uRow
            .getByRole('button', { name: /取消授权/ })
            .first()
            .click()
          const box = page.locator('.el-message-box:visible').first()
          await box.waitFor({ state: 'visible', timeout: 4000 })
          await box.locator('.el-message-box__btns .el-button--primary').first().click()
          const cancelResp = await cancelPromise.catch(() => null)
          await page.waitForTimeout(1000)
          const alloc = await fetch(
            `${CONFIG.backendUrl}/system/role/authUser/allocatedList?pageNum=1&pageSize=50&roleId=2&userName=${encodeURIComponent(uname)}`,
            { headers: authHeaders }
          )
            .then((r) => r.json())
            .catch(() => null)
          const stillAllocated = (alloc?.rows || []).some((r) => r.userName === uname)
          record(
            104,
            '③b 取消授权生效（allocatedList 不再含该用户）',
            !!cancelResp && !stillAllocated,
            `cancel=${!!cancelResp}, still=${stillAllocated}`
          )
        } else {
          // 测试债轮：SKIP 补 allocatedList 接口 200 兜底，不再空记 PASS
          const fb = await apiWithBackoff('/system/role/authUser/allocatedList?pageNum=1&pageSize=1&roleId=2', {
            headers: authHeaders
          })
          recordSkip(104, '③b 取消授权生效', 'allocatedList 中未定位到该用户行', fb.status === 200)
        }
      } else {
        // 测试债轮：SKIP 补 allocatedList 接口 200 兜底，不再空记 PASS
        const fb = await apiWithBackoff('/system/role/authUser/allocatedList?pageNum=1&pageSize=1&roleId=2', {
          headers: authHeaders
        })
        recordSkip(
          104,
          '③b 取消授权生效',
          `API 挂载角色 2 未成功（code=${bind?.code}），仅断言表格渲染`,
          fb.status === 200
        )
      }
    }
  } catch (err) {
    record(104, '用例链异常', false, `异常: ${err.message.slice(0, 160)}`)
  }

  // 4. 清理临时用户
  if (uid) {
    const del = await fetch(`${CONFIG.backendUrl}/system/user/${uid}`, { method: 'DELETE', headers: authHeaders })
      .then((r) => r.json())
      .catch(() => null)
    record(104, '④ 清理临时用户', del?.code === 200, `code=${del?.code}`)
  }
  await dismissAllOverlays(page)
}

// ==================== 功能 105：SSO 同意页 UI（拒绝路径 + 同意路径） ====================
async function testFeature105(page) {
  log('=== 功能 105：SSO 同意页 UI ===')
  const B = CONFIG.backendUrl
  const token = await sessionTokenOf(page)
  if (!token) {
    record(105, '前置登录', false, 'token 获取失败')
    return
  }
  const auth = { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }
  const redirectUri = `${B}/sso/e2e-callback` // 已登记回调（仅解析回跳 URL，不实际访问）
  const b64url = (buf) => Buffer.from(buf).toString('base64url')
  const randB64url = (n) => b64url(crypto.randomBytes(n))
  const challengeOf = (v) => crypto.createHash('sha256').update(v, 'ascii').digest('base64url')

  // 0. API 建同意制客户端（F51 口径）
  let created = null
  try {
    const res = await fetch(`${B}/system/oauth/client`, {
      method: 'POST',
      headers: auth,
      body: JSON.stringify({
        ssoClientId: 0,
        clientName: `E2E-CONSENT-${Date.now()}`,
        logoUri: '',
        redirectUris: [redirectUri],
        scopes: ['openid', 'profile'],
        grantTypes: ['authorization_code'],
        consentRequired: '1',
        enabled: '1',
        remark: 'e2e consent 临时客户端'
      })
    }).then((r) => r.json())
    created = res?.data?.clientId
      ? { ssoClientId: res.data.client.ssoClientId, clientId: res.data.clientId, clientSecret: res.data.clientSecret }
      : null
    record(105, '⓪ API 建 consent 客户端', !!created, `code=${res?.code}`)
  } catch (err) {
    record(105, '⓪ API 建 consent 客户端', false, `异常: ${err.message.slice(0, 120)}`)
  }

  const authorizeUrlOf = (clientId) => {
    const qs = new URLSearchParams({
      client_id: clientId,
      redirect_uri: redirectUri,
      response_type: 'code',
      scope: 'openid profile',
      state: randB64url(8),
      nonce: randB64url(8),
      code_challenge: challengeOf(randB64url(32)),
      code_challenge_method: 'S256'
    })
    return `${B}/sso/authorize?${qs.toString()}`
  }

  // 1. 登录态发起 authorize → 302 到 /sso-consent → 真实渲染同意页（scope 列表 + 同意/拒绝按钮）
  let ctx2 = null
  if (created) {
    try {
      ctx2 = await page.context().browser().newContext()
      await ctx2.addCookies([{ name: 'Admin-Token', value: token, url: B }])
      const p2 = await ctx2.newPage()
      await p2.goto(authorizeUrlOf(created.clientId), { waitUntil: 'load' })
      await p2.waitForURL((u) => u.toString().includes('/sso-consent'), { timeout: 15000 }).catch(() => {})
      await p2.waitForTimeout(1500)
      const onConsent = p2.url().includes('/sso-consent')
      // 批四十三：等 scope 列表项就绪再计数——长跑负载下渲染滞后（r54 实证 scopes=0 瞬时
      // 窗口假失败，单跑 5/5 全绿），固定 waitForTimeout(1500) 不足。
      const scopeFirst = p2.locator('ul.scope-list li, .scope-list li').first()
      await scopeFirst.waitFor({ state: 'visible', timeout: 10000 }).catch(() => {})
      const scopeItems = await p2.locator('ul.scope-list li, .scope-list li').count()
      const denyBtn = await p2
        .getByRole('button', { name: /拒绝|Deny/ })
        .first()
        .waitFor({ state: 'visible', timeout: 3000 })
        .then(() => true)
        .catch(() => false)
      const allowBtn = await p2
        .getByRole('button', { name: /允许|同意|授权|Allow|Approve/ })
        .first()
        .waitFor({ state: 'visible', timeout: 2000 })
        .then(() => true)
        .catch(() => false)
      record(
        105,
        '① 同意页渲染：scope 列表 + 同意/拒绝按钮',
        onConsent && scopeItems > 0 && denyBtn && allowBtn,
        `consent=${onConsent}, scopes=${scopeItems}, deny=${denyBtn}, allow=${allowBtn}`
      )
    } catch (err) {
      record(105, '① 同意页渲染：scope 列表 + 同意/拒绝按钮', false, `异常: ${err.message.slice(0, 120)}`)
    }

    // 2. 点击拒绝 → 回跳带 error=access_denied
    try {
      const p2 = ctx2.pages()[0]
      // 重新发起一次 authorize（同意页一次性，避免上一步状态残留）
      await p2.goto(authorizeUrlOf(created.clientId), { waitUntil: 'load' })
      await p2.waitForURL((u) => u.toString().includes('/sso-consent'), { timeout: 15000 }).catch(() => {})
      await p2.waitForTimeout(1000)
      await p2
        .getByRole('button', { name: /拒绝|Deny/ })
        .first()
        .click()
      const denied = await p2
        .waitForURL((u) => u.toString().includes('error=access_denied'), { timeout: 15000 })
        .then(() => true)
        .catch(() => false)
      record(105, '② 拒绝 → 回跳带 error=access_denied', denied, `url=${p2.url().slice(0, 120)}`)
    } catch (err) {
      record(105, '② 拒绝 → 回跳带 error=access_denied', false, `异常: ${err.message.slice(0, 120)}`)
    }

    // 3. 同意 → code 参数下发（低成本分支）
    try {
      const p3ctx = await page.context().browser().newContext()
      await p3ctx.addCookies([{ name: 'Admin-Token', value: token, url: B }])
      const p3 = await p3ctx.newPage()
      await p3.goto(authorizeUrlOf(created.clientId), { waitUntil: 'load' })
      await p3.waitForURL((u) => u.toString().includes('/sso-consent'), { timeout: 15000 }).catch(() => {})
      await p3.waitForTimeout(1000)
      await p3
        .getByRole('button', { name: /允许|同意|授权|Allow|Approve/ })
        .first()
        .click()
      const coded = await p3
        .waitForURL((u) => u.toString().includes('code='), { timeout: 15000 })
        .then(() => true)
        .catch(() => false)
      record(105, '③ 同意 → 回跳带 code 参数', coded, `url=${p3.url().slice(0, 120)}`)
      await p3ctx.close()
    } catch (err) {
      record(105, '③ 同意 → 回跳带 code 参数', false, `异常: ${err.message.slice(0, 120)}`)
    }

    if (ctx2) await ctx2.close().catch(() => {})
  }

  // 清理：删除 consent 客户端（自清）
  if (created) {
    const del = await fetch(`${B}/system/oauth/client/${created.ssoClientId}`, { method: 'DELETE', headers: auth })
      .then((r) => r.json())
      .catch(() => null)
    record(105, '④ 清理：删除 consent 客户端', del?.code === 200 || del?.code === 0, `code=${del?.code}`)
  }
}

// ==================== 功能 106：个人中心安全 Tab 深交互 ====================
async function testFeature106(page) {
  log('=== 功能 106：个人中心安全 Tab 深交互 ===')
  const token = await sessionTokenOf(page)
  const authHeaders = token ? { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' } : null

  // ① passkeys：注册交互 → 错误提示（无平台认证器环境走警告横幅/SKIP 语义）
  try {
    await presetTourDisabled(page)
    await page.goto(`${CONFIG.frontendUrl}/user/profile/passkeys`, { waitUntil: 'load', timeout: 20000 })
    await sleep(1500)
    await skipTour(page)
    const card = page.locator('.el-card').first()
    const cardOk = await card
      .waitFor({ state: 'visible', timeout: 5000 })
      .then(() => true)
      .catch(() => false)
    const unsupported = await page
      .locator('.el-alert--warning')
      .first()
      .waitFor({ state: 'visible', timeout: 1500 })
      .then(() => true)
      .catch(() => false)
    if (unsupported) {
      record(
        106,
        '① passkeys：无认证器环境显示警告横幅（SKIP 语义）',
        cardOk,
        'unsupported 横幅可见，注册入口按能力位收敛'
      )
    } else {
      const addBtn = page.getByRole('button', { name: /添加|新增|注册/ }).first()
      if (
        await addBtn
          .waitFor({ state: 'visible', timeout: 3000 })
          .then(() => true)
          .catch(() => false)
      ) {
        // 批六十四质量工程：headless 无认证器会让 navigator.credentials.create 直接
        // reject（旧断言"注册失败出现错误提示"）——改用 **CDP 虚拟认证器** 走真实
        // 注册成功链（credentials.create → registerFinish → 列表新增），覆盖升级
        const cdp = await page.context().newCDPSession(page)
        await cdp.send('WebAuthn.enable').catch(() => {})
        await cdp
          .send('WebAuthn.addVirtualAuthenticator', {
            options: {
              protocol: 'ctap2',
              transport: 'internal',
              hasResidentKey: true,
              hasUserVerification: true,
              isUserVerified: true,
              automaticPresenceSimulation: true
            }
          })
          .catch(() => {})
        const passkeyName = `e2e-pk-${Date.now().toString(36)}`
        const beforeCount = await page
          .evaluate(() => document.querySelectorAll('.passkey-item, [class*="passkey"] .el-card').length)
          .catch(() => 0)
        await addBtn.click()
        const dlg = page.locator('.el-dialog:visible').last()
        await dlg.waitFor({ state: 'visible', timeout: 4000 })
        await dlg.locator('input').first().fill(passkeyName)
        const regPromise = page
          // 批六十四循环轮 13 补：真实端点为 /system/user/webauthn/register/*（不含
          // "passkey" 字样）——旧 includes('passkey') 永不匹配（reg=n/a 实证）
          .waitForResponse(
            (r) =>
              r.url().includes('/system/user/webauthn/') &&
              (r.request().method() === 'POST' || r.request().method() === 'PUT'),
            { timeout: 20000 }
          )
          .then((r) => ({ status: r.status() }))
          .catch(() => null)
        await dlg
          .getByRole('button', { name: /确\s*定|确定/ })
          .first()
          .click()
        const regResp = await regPromise
        // 成功/失败 Toast 用 waitFor 捕捉（ElMessage 3s 存活——即时 isVisible 会错过）
        const okToast = await page
          .locator('.el-message--success')
          .first()
          .waitFor({ state: 'visible', timeout: 3000 })
          .then(() => true)
          .catch(() => false)
        const errToast = okToast
          ? false
          : await page
              .locator('.el-message--error, .el-message--warning')
              .first()
              .waitFor({ state: 'visible', timeout: 3000 })
              .then(() => true)
              .catch(() => false)
        await page.waitForTimeout(1200)
        const afterCount = await page
          .evaluate(() => document.querySelectorAll('.passkey-item, [class*="passkey"] .el-card').length)
          .catch(() => 0)
        // 批六十四质量工程：成功链（registerFinish 200/列表新增/成功 Toast）或
        // 失败反馈链（错误 Toast——.catch 语义）均为有效覆盖。
        // ⚠️ 当前实测：虚拟认证器下 finish 400「WebAuthn 响应无效」= 后端缺陷
        //（pubKeyCredParams 仅 ES256 缺 RS256，Chrome 警告实证）——已登记台账，
        // 后端修复后本断言自动走成功分支。
        // 批六十四循环轮 13 补：网络层 finish 响应（200 成功 / 4xx 错误反馈）均为有效覆盖——
        // 失败反馈的 UI 呈现由 errorHub 体系承担（非 ElMessage Toast），finish 400 实证
        // 批六十五：断言**强化为成功链**——此前接受 `>= 400` 使"链路真断"也能通过
        // （历史把 origin 失配的 400 误判为"算法缺陷"并被弱断言掩盖，真实缺陷被放过）。
        // 根因修复后（[webauthn].origin 对齐页面服务源，或 WEBAUTHN_ORIGIN 环境覆盖）
        // 必须走通 registerFinish 200 + 成功 Toast 或列表增长。
        const regOk = regResp?.status === 200 && (okToast || afterCount > beforeCount)
        record(
          106,
          '① passkeys：注册成功链（registerFinish 200 + 列表新增）',
          regOk,
          `reg=${regResp?.status || 'n/a'}, list ${beforeCount}→${afterCount}, ok=${okToast}, err=${errToast}`
        )
        await page.keyboard.press('Escape')
        await page.waitForTimeout(400)
      } else {
        // 测试债轮：SKIP 补 profile 接口 200 兜底（token 缺失时无 API 可兜底 → null）
        const fb = authHeaders ? await apiWithBackoff('/system/user/profile', { headers: authHeaders }) : null
        recordSkip(
          106,
          '① passkeys：注册失败出现错误提示（.catch 语义）',
          '能力位未开放（无注册按钮），仅断言卡片渲染',
          fb ? fb.status === 200 : null
        )
      }
    }
  } catch (err) {
    record(106, '① passkeys：注册失败出现错误提示（.catch 语义）', false, `异常: ${err.message.slice(0, 120)}`)
  }

  // ② ssoGrants：列表/空态渲染 + 撤销确认取消路径
  // 批六十四循环轮 13 激活：撤销链夹具（sys_oauth_client + sys_oauth_consent 直插，
  // sso-grants API 预验证返回该行）——测后 finally 物理清理，不影响在册数据
  let consentFixture = false
  try {
    const mod = await importSyncDatabase()
    const DatabaseSync = mod.DatabaseSync
    const db = new DatabaseSync(e2eDbPath())
    db.exec('PRAGMA busy_timeout = 5000')
    const admin = db.prepare("SELECT user_id FROM sys_user WHERE user_name='admin' AND del_flag='0'").get()
    if (admin?.user_id != null) {
      db.prepare(
        `INSERT INTO sys_oauth_client (client_id, client_secret_hash, id_token_secret, client_name, logo_uri, redirect_uris, scopes, tenant_id, create_by, create_time)
         VALUES ('e2e_consent_client', 'x', '', 'E2E授权应用（测后清理）', '', '["https://e2e.local/cb"]', '["openid"]', 0, 'e2e', datetime('now'))`
      ).run()
      db.prepare(
        `INSERT INTO sys_oauth_consent (user_id, client_id, scopes, client_name_snapshot, tenant_id, create_time)
         VALUES (?, 'e2e_consent_client', '["openid"]', 'E2E授权应用（测后清理）', 0, datetime('now'))`
      ).run(admin.user_id)
      consentFixture = true
    }
    db.close()
  } catch (err) {
    log(`  F106②b 撤销链夹具异常: ${err.message.slice(0, 80)}`)
  }
  try {
    await presetTourDisabled(page)
    // 批五十六：F4 确定性等待——先挂 sso-grants 200 响应探针再 goto。
    // r61 实证：套件上下文该请求耗时 >15s（退避重试族），固定时间等待双跑双败；
    // 响应到达即 loading=false、el-empty/grant-item 必然就绪（探针+富快照取证）。
    page.on('framenavigated', (f) => {
      if (f === page.mainFrame()) log(`  ⚠ [F106 ②] 导航发生: ${f.url().slice(0, 80)} @${Date.now() - gotoT0}ms`)
    })
    // 批六十四循环修复：gotoT0 此前未定义——framenavigated 触发时 ReferenceError 被
    // uncaughtException 兜底吞掉（×3 实证），诊断日志从未真正输出
    const gotoT0 = Date.now()
    const grantsRespReady = page
      .waitForResponse((r) => r.url().includes('/system/user/profile/sso-grants') && r.status() === 200, {
        timeout: 60000
      })
      .then(() => true)
      .catch(() => false)
    await page.goto(`${CONFIG.frontendUrl}/user/profile/ssoGrants`, { waitUntil: 'load', timeout: 20000 })
    await skipTour(page)
    const grantsReady = await grantsRespReady
    // 个人中心 ssoGrants 卡断言（批五十六：DOM 真值轮询）
    //
    // 弃用 Playwright locator.waitFor(visible)：r61 取证实证该页在套件上下文存在
    // 「DOM 已渲染（grantHTML=el-empty、Tab 激活、CSS 链全 visible）而 Playwright
    // visible=false 长达 30s+」的语义分歧（el-card:has(.grant-list) 双匹配 +
    // EP tab-pane 渲染时序叠加），时间线快照与截图均证实 DOM 真值可靠。
    // 断言语义不变：ssoGrants 卡渲染且（授权列表非空 或 空态组件可见）。
    let rendered = false
    let hasList = false
    let hasEmpty = false
    for (let i = 0; i < 30 && !(rendered && (hasList || hasEmpty)); i++) {
      const s = await page
        .evaluate(() => {
          const cards = [...document.querySelectorAll('.el-card:has(.grant-list)')]
          const card = cards.find((c) => c.closest('.el-tab-pane')) || cards[0]
          if (!card) return null
          const empty = card.querySelector('.el-empty')
          return {
            rendered: card.offsetParent !== null,
            hasList: card.querySelectorAll('.grant-item').length > 0,
            hasEmpty: !!empty && empty.offsetParent !== null
          }
        })
        .catch(() => null)
      if (s) {
        rendered = s.rendered
        hasList = s.hasList
        hasEmpty = s.hasEmpty
      }
      if (rendered && (hasList || hasEmpty)) break
      await page.waitForTimeout(1000)
    }
    record(
      106,
      '② ssoGrants：列表或空态渲染',
      rendered && (hasList || hasEmpty),
      `list=${hasList}, empty=${hasEmpty}, api200=${grantsReady}`
    )

    const revokeBtn = page
      .locator('#pane-ssoGrants')
      .getByRole('button', { name: /撤销|revoke/i })
      .first()
    if (
      hasList &&
      (await revokeBtn
        .waitFor({ state: 'visible', timeout: 2000 })
        .then(() => true)
        .catch(() => false))
    ) {
      await revokeBtn.click()
      const box = page.locator('.el-message-box:visible').first()
      await box.waitFor({ state: 'visible', timeout: 4000 })
      await box.locator('.el-message-box__btns button:not(.el-button--primary)').first().click()
      await page.waitForTimeout(600)
      const stillList = await page
        .evaluate(() => {
          const pane = document.querySelector('#pane-ssoGrants')
          return !!pane && pane.querySelectorAll('.grant-item').length > 0
        })
        .catch(() => false)
      record(106, '②b 撤销确认「取消」→ 授权仍在', stillList)
    } else {
      // 测试债轮：SKIP 补 profile 接口 200 兜底（token 缺失时无 API 可兜底 → null）
      const fb = authHeaders ? await apiWithBackoff('/system/user/profile', { headers: authHeaders }) : null
      recordSkip(106, '②b 撤销确认「取消」→ 授权仍在', '无已授权应用，撤销链不可达', fb ? fb.status === 200 : null)
    }
  } catch (err) {
    record(106, '② ssoGrants', false, `异常: ${err.message.slice(0, 120)}`)
  } finally {
    // 批六十四循环轮 13：撤销链夹具物理清理（client + consent 同删，在册数据不受影响）
    if (consentFixture) {
      try {
        const mod = await importSyncDatabase()
        const DatabaseSync = mod.DatabaseSync
        const db = new DatabaseSync(e2eDbPath())
        db.exec('PRAGMA busy_timeout = 5000')
        db.prepare("DELETE FROM sys_oauth_consent WHERE client_id='e2e_consent_client'").run()
        db.prepare("DELETE FROM sys_oauth_client WHERE client_id='e2e_consent_client'").run()
        db.close()
        log('  F106②b 撤销链夹具已清理')
      } catch (err) {
        log(`  F106②b 夹具清理异常: ${err.message.slice(0, 80)}`)
      }
    }
  }

  // ③ msgPref：切换开关 → 保存 → 刷新持久化 → 恢复原值
  try {
    await presetTourDisabled(page)
    await page.goto(`${CONFIG.frontendUrl}/user/profile/pref`, { waitUntil: 'load', timeout: 20000 })
    await sleep(1500)
    await skipTour(page)
    const emailSwitch = page.locator('.el-switch').first()
    const swOk = await emailSwitch
      .waitFor({ state: 'visible', timeout: 6000 })
      .then(() => true)
      .catch(() => false)
    if (swOk && authHeaders) {
      // 记录原值（API 回读，避免依赖 DOM 初态）——批六十四循环轮 13：真实路径为
      // /system/profile/pref（旧 /system/user/profile/messagePref 为 404，③b 曾假 PASS）
      const before = await fetch(`${CONFIG.backendUrl}/system/profile/pref`, { headers: authHeaders })
        .then((r) => r.json())
        .catch(() => null)
      const origEmail = before?.data?.emailNotify
      // 预置为翻转值保证 UI 点击后 flip 恒发生（消除「原值未知或已一致」SKIP），
      // 且 UI 点回原值 = 恢复语义内建、自清理。emailNotify 为字符串 "0"/"1"。
      let presetOk = false
      if (before?.data && (origEmail === '0' || origEmail === '1')) {
        const flippedVal = origEmail === '1' ? '0' : '1'
        const preset = await fetch(`${CONFIG.backendUrl}/system/profile/pref`, {
          method: 'PUT',
          headers: authHeaders,
          body: JSON.stringify({ ...before.data, emailNotify: flippedVal })
        })
          .then((r) => r.json())
          .catch(() => null)
        presetOk = preset?.code === 200
        if (presetOk) {
          await page.reload({ waitUntil: 'load' })
          await sleep(1500)
          await skipTour(page)
        }
      }
      // UI 切换（写回 orig——flip 断言）
      const sw2 = presetOk ? page.locator('.el-switch').first() : emailSwitch
      await sw2.click()
      const savePromise = page.waitForResponse(
        (r) => (r.url().includes('/system/profile/pref') || r.url().includes('pref')) && r.request().method() === 'PUT',
        { timeout: 8000 }
      )
      await page.getByRole('button', { name: /保存/ }).first().click()
      const saveResp = await savePromise.catch(() => null)
      record(106, '③ msgPref：保存请求发出', !!saveResp)
      // 刷新持久化
      await page.reload({ waitUntil: 'load' })
      await sleep(1500)
      await skipTour(page)
      const after = await fetch(`${CONFIG.backendUrl}/system/profile/pref`, { headers: authHeaders })
        .then((r) => r.json())
        .catch(() => null)
      const newVal = after?.data?.emailNotify
      // 断言严格化（undefined 即 FAIL）+ 预置路径语义：预置后 UI 初值=!orig，
      // 点击应写回 orig（now===orig）；非预置路径点击应翻转（now===!orig）
      const expectedNow = presetOk ? origEmail : origEmail === '1' ? '0' : '1'
      const flipped = newVal !== undefined && origEmail !== undefined ? newVal === expectedNow : false
      record(106, '③b msgPref：切换持久化', flipped, `orig=${origEmail}, now=${newVal}, expected=${expectedNow}`)
      // 恢复原值（API 直写，幂等）——预置翻转路径下 UI 已写回 orig，此处幂等兜底
      if (origEmail !== undefined && newVal !== undefined && newVal !== origEmail) {
        const restore = await fetch(`${CONFIG.backendUrl}/system/profile/pref`, {
          method: 'PUT',
          headers: authHeaders,
          body: JSON.stringify({ ...after.data, emailNotify: origEmail })
        })
          .then((r) => r.json())
          .catch(() => null)
        record(106, '③c msgPref：恢复原值', restore?.code === 200, `code=${restore?.code}`)
      } else {
        // 预置翻转路径：UI 写回 orig 即恢复完成（newVal===origEmail）
        const fb = await apiWithBackoff('/system/profile/pref', { headers: authHeaders })
        record(
          106,
          '③c msgPref：恢复原值',
          presetOk && newVal === origEmail && fb.status === 200,
          `preset=${presetOk}, restored=${newVal === origEmail}, fb=${fb.status}`
        )
      }
    } else {
      record(106, '③ msgPref：保存请求发出', swOk, swOk ? 'token 缺失，跳过 API 比对' : '开关不可见')
    }
  } catch (err) {
    record(106, '③ msgPref', false, `异常: ${err.message.slice(0, 120)}`)
  }

  // ④ totp：解绑对话框打开 → 取消（未启用则断言引导流程渲染）
  try {
    await presetTourDisabled(page)
    await page.goto(`${CONFIG.frontendUrl}/user/profile/totp`, { waitUntil: 'load', timeout: 20000 })
    await sleep(1500)
    await skipTour(page)
    const card = page.locator('.totp-card, .el-card').first()
    const cardOk = await card
      .waitFor({ state: 'visible', timeout: 5000 })
      .then(() => true)
      .catch(() => false)
    const enabledTag = await card
      .locator('.el-tag--success')
      .first()
      .waitFor({ state: 'visible', timeout: 2000 })
      .then(() => true)
      .catch(() => false)
    if (cardOk && enabledTag) {
      const disableBtn = card.getByRole('button', { name: /禁用|解绑|关闭|未启用/ }).first()
      await disableBtn.click()
      const pwdInput = page.locator('input[type="password"]').first()
      const formShown = await pwdInput
        .waitFor({ state: 'visible', timeout: 4000 })
        .then(() => true)
        .catch(() => false)
      record(106, '④ totp：解绑表单打开', formShown)
      // 取消 → 回到已启用态
      // 可访问名是 `t('common.cancel')`＝字面「取 消」（带空格），`/取消/` 永远匹配不到 ⇒
      // 旧写法下面这一步"点了取消"其实一次都没发生，而 `④b` 只看"禁用按钮还在"就记 ✅
      // ——**因为没取消所以状态没变**，正是空判据。正则容空格后把落地与复原分成两条。
      const cancelBtn = page.getByRole('button', { name: /取\s*消/ }).first()
      const cancelFound = await cancelBtn.isVisible().catch(() => false)
      const cancelClicked =
        formShown && cancelFound
          ? await cancelBtn
              .click()
              .then(() => true)
              .catch(() => false)
          : false
      if (cancelClicked) await page.waitForTimeout(500)
      const backToEnabled = await card
        .getByRole('button', { name: /禁用|解绑|关闭|未启用/ })
        .first()
        .waitFor({ state: 'visible', timeout: 3000 })
        .then(() => true)
        .catch(() => false)
      record(106, '④b totp：取消按钮确实点到（文案「取 消」容空格）', cancelClicked, `可见=${cancelFound}`)
      record(106, '④b totp：取消后回到已启用态', cancelClicked && backToEnabled, `回到已启用=${backToEnabled}`)
    } else {
      const setupBtn = card.getByRole('button', { name: /生成密钥|绑定|开启/ }).first()
      const setupRendered = await setupBtn
        .waitFor({ state: 'visible', timeout: 2000 })
        .then(() => true)
        .catch(() => false)
      // 批六十四循环轮 13 激活：TOTP 未启用时走真实启用链（复用 F20 的 setup+verify+
      // generateTotp 算码）→ 解绑表单断言 → disable 恢复未绑定态（F20 同款参数）
      let activated = false
      let activationSecret = null
      if (cardOk && authHeaders) {
        try {
          const setup = await fetch(`${CONFIG.backendUrl}/system/user/totp/setup`, {
            method: 'POST',
            headers: authHeaders
          })
            .then((r) => r.json())
            .catch(() => null)
          if (setup?.data?.secret) {
            activationSecret = setup.data.secret
            for (let attempt = 0; attempt < 3 && !activated; attempt++) {
              const code = generateTotp(activationSecret)
              const verify = await fetch(`${CONFIG.backendUrl}/system/user/totp/verify`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', ...authHeaders },
                body: JSON.stringify({ code, secret: activationSecret })
              })
                .then((r) => r.json())
                .catch(() => null)
              activated = verify?.code === 200
              if (!activated) {
                log(`  F106④ verify attempt${attempt}: ${JSON.stringify(verify).slice(0, 120)}`)
                await sleep(2000)
              }
            }
          }
        } catch (err) {
          log(`  F106④ 启用链异常: ${err.message.slice(0, 80)}`)
        }
      }
      if (activated) {
        await page.reload({ waitUntil: 'load' })
        await sleep(1500)
        await skipTour(page)
        // 批六十四循环轮 13 修正：card2 用 .totp-card, .el-card 的 first() 会命中页面前部的
        // 通知卡（tag 定位错位，enabledTag2 恒 false 实证）——改 page 级可见 success tag
        const enabledTag2 = await page
          .locator('.el-tag--success:visible')
          .first()
          .waitFor({ state: 'visible', timeout: 4000 })
          .then(() => true)
          .catch(() => false)
        let formShown2 = false
        if (enabledTag2) {
          // 批六十四循环轮 13：按钮文本为 t('profile.totp.disabled')="未启用"（关闭动作），
          // 旧正则 /禁用|解绑|关闭/ 匹配不到——已扩正则；定位限定 totp-card 容器
          const disableBtn2 = page
            .locator('.totp-card')
            .getByRole('button', { name: /禁用|解绑|关闭|未启用/ })
            .first()
          const btnVisible = await disableBtn2.isVisible().catch(() => false)
          await disableBtn2.click()
          // showDisable=true → v-else-if 切到 disable-form（密码+验证码表单）
          formShown2 = await page
            .locator('.disable-form input[type="password"]:visible')
            .first()
            .waitFor({ state: 'visible', timeout: 4000 })
            .then(() => true)
            .catch(() => false)
          record(
            106,
            '④-pre totp：按钮点击与表单切换',
            btnVisible && formShown2,
            `btn=${btnVisible}, form=${formShown2}`
          )
          // 取消 → 回到已启用态（断言后不真正解绑）
          // 同上：可访问名是「取 消」，`/取消/` 匹配不到 ⇒ 旧写法这步是空操作
          const cancelBtn2 = page.getByRole('button', { name: /取\s*消/ }).first()
          if (formShown2 && (await cancelBtn2.isVisible().catch(() => false))) {
            await cancelBtn2.click()
            await page.waitForTimeout(500)
          }
        }
        record(106, '④ totp：解绑表单打开', formShown2, `真实启用链激活 enabled=${enabledTag2}`)
        // 恢复未绑定态（F20 同款 disable——不污染 F129/TOTP 相关后续状态）
        if (activationSecret) {
          const code = generateTotp(activationSecret)
          const disable = await fetch(`${CONFIG.backendUrl}/system/user/totp/disable`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...authHeaders },
            body: JSON.stringify({ password: CONFIG.password, code })
          })
            .then((r) => r.json())
            .catch(() => null)
          record(106, '④b totp：恢复未绑定态', disable?.code === 200, `disable code=${disable?.code}`)
        }
      } else {
        record(
          106,
          '④ totp：解绑表单打开',
          cardOk,
          `SKIP：TOTP 未启用（enabledTag=${enabledTag}），引导流程渲染=${setupRendered}，启用链失败`
        )
      }
    }
  } catch (err) {
    record(106, '④ totp', false, `异常: ${err.message.slice(0, 120)}`)
  }
  await dismissAllOverlays(page)
}

// ==================== 功能 107：报表管理 UI ====================
async function testFeature107(page) {
  log('=== 功能 107：报表管理 UI ===')
  const token = await sessionTokenOf(page)
  if (!token) {
    record(107, '前置登录', false, 'token 获取失败')
    return
  }
  const authHeaders = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }
  const ts = Date.now().toString(36)
  const rcode = `e2e_rpt_${ts}`
  const rname = `e2e 报表_${ts}`
  let reportId = null

  // ① 列表页可达渲染
  await presetTourDisabled(page)
  await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/report/index`, 'report/index')
  await skipTour(page)
  const not404 = !(await is404Page(page))
  await page
    .locator('.el-table')
    .first()
    .waitFor({ state: 'visible', timeout: 8000 })
    .catch(() => {})
  const tableOk =
    (await page.locator('.el-table__row').count()) > 0 ||
    (await page.locator('.el-table .el-empty, .el-table__empty-block').count()) > 0
  record(107, '① 列表页可达渲染', not404 && tableOk, `not404=${not404}, table=${tableOk}`)

  // ② 新增报表（名称随机）→ 保存 → 列表出现
  try {
    await page.getByRole('button', { name: /新增/ }).first().click()
    const dlg = page.locator('.el-dialog:visible').last()
    await dlg.waitFor({ state: 'visible', timeout: 4000 })
    await dlg
      .locator('.el-form-item')
      .filter({ has: page.locator('.el-form-item__label:text-is("报表编码")') })
      .locator('input')
      .first()
      .fill(rcode)
    await dlg
      .locator('.el-form-item')
      .filter({ has: page.locator('.el-form-item__label:text-is("报表名称")') })
      .locator('input')
      .first()
      .fill(rname)
    // reportType 与 config 均为必填：选「自定义」类型 + 填最小 config
    const typeItem = dlg
      .locator('.el-form-item')
      .filter({ has: page.locator('.el-form-item__label:text-is("报表类型")') })
    await typeItem.locator('.el-select').first().click()
    await page
      .locator('.el-select-dropdown__item:visible')
      .filter({ hasText: /自定义|custom/ })
      .first()
      .click()
    const cfgItem = dlg
      .locator('.el-form-item')
      .filter({ has: page.locator('.el-form-item__label:text-is("报表配置")') })
    if (
      await cfgItem
        .waitFor({ state: 'visible', timeout: 1500 })
        .then(() => true)
        .catch(() => false)
    ) {
      const cfgVal = await cfgItem
        .locator('textarea')
        .first()
        .inputValue()
        .catch(() => '')
      if (!cfgVal || !cfgVal.trim()) await cfgItem.locator('textarea').first().fill('{}')
    }
    const savePromise = page.waitForResponse(
      (r) => r.url().includes('/system/report') && r.request().method() === 'POST' && r.status() === 200,
      { timeout: 10000 }
    )
    await dlg
      .getByRole('button', { name: /确\s*定|确定/ })
      .first()
      .click()
    const saveResp = await savePromise.catch(() => null)
    await page.waitForTimeout(800)
    record(107, '② 新增报表保存（POST 200）', !!saveResp)
    const list = await fetch(
      `${CONFIG.backendUrl}/system/report/list?pageNum=1&pageSize=50&reportName=${encodeURIComponent(rname)}`,
      { headers: authHeaders }
    )
      .then((r) => r.json())
      .catch(() => null)
    const row = (list?.rows || []).find((r) => r.reportCode === rcode)
    reportId = row?.reportId ?? null
    record(107, '②b API 复核报表落库', !!row, `reportId=${reportId}`)
  } catch (err) {
    record(107, '② 新增报表保存（POST 200）', false, `异常: ${err.message.slice(0, 120)}`)
  }

  // ③ 子报表订阅页渲染
  try {
    await presetTourDisabled(page)
    await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/report/sub`, 'report/sub')
    await skipTour(page)
    const sub404 = !(await is404Page(page))
    const subTable =
      (await page.locator('.el-table__row').count()) > 0 ||
      (await page.locator('.el-table .el-empty, .el-table__empty-block').count()) > 0
    record(107, '③ 子报表订阅页渲染', sub404 && subTable, `not404=${sub404}, table=${subTable}`)
  } catch (err) {
    record(107, '③ 子报表订阅页渲染', false, `异常: ${err.message.slice(0, 120)}`)
  }

  // ④ 删除 → 确认 → 消失（API 复核自清）
  if (reportId) {
    try {
      await presetTourDisabled(page)
      await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/system/report/index`, 'report/index')
      await skipTour(page)
      const searchPromise = page.waitForResponse(
        (r) =>
          r.url().includes('/system/report/list') &&
          r.url().includes(`reportName=${encodeURIComponent(rname)}`) &&
          r.status() === 200,
        { timeout: 10000 }
      )
      await page.locator('input[placeholder*="报表名称"]').first().fill(rname)
      await page.getByRole('button', { name: /搜索/ }).first().click()
      await searchPromise
      const row = page.locator('.el-table__row').filter({ hasText: rcode }).first()
      if (
        await row
          .waitFor({ state: 'visible', timeout: 5000 })
          .then(() => true)
          .catch(() => false)
      ) {
        await row.getByRole('button', { name: /删除/ }).first().click()
        const box = page.locator('.el-message-box:visible').first()
        await box.waitFor({ state: 'visible', timeout: 4000 })
        const delPromise = page.waitForResponse(
          (r) => r.url().includes('/system/report/') && r.request().method() === 'DELETE' && r.status() === 200,
          { timeout: 8000 }
        )
        await box.locator('.el-message-box__btns .el-button--primary').first().click()
        const delResp = await delPromise.catch(() => null)
        await page.waitForTimeout(800)
        record(107, '④ 删除 → 确认 → 消失（DELETE 200）', !!delResp, `del=${!!delResp}`)
        const apiAfter = await fetch(
          `${CONFIG.backendUrl}/system/report/list?pageNum=1&pageSize=50&reportName=${encodeURIComponent(rname)}`,
          { headers: authHeaders }
        )
          .then((r) => r.json())
          .catch(() => null)
        record(107, '④b API 复核已删除（自清完成）', (apiAfter?.rows || []).length === 0)
      } else {
        record(107, '④ 删除 → 确认 → 消失（DELETE 200）', false, '未定位到报表行')
      }
    } catch (err) {
      record(107, '④ 删除链', false, `异常: ${err.message.slice(0, 120)}`)
    }
  }

  // 兜底自清
  if (reportId) {
    await fetch(`${CONFIG.backendUrl}/system/report/${reportId}`, { method: 'DELETE', headers: authHeaders }).catch(
      () => {}
    )
  }
  await dismissAllOverlays(page)
}

// ==================== 功能 108：表单构建器冒烟 ====================
async function testFeature108(page) {
  log('=== 功能 108：表单构建器冒烟 ===')
  try {
    await presetTourDisabled(page)
    await gotoDynamicRoute(page, `${CONFIG.frontendUrl}/tool/build`, '/tool/build')
    await skipTour(page)
    const not404 = !(await is404Page(page))

    // ① 组件面板与画布渲染
    const panelOk = (await page.locator('.left-board .components-item').count()) > 0
    const boardOk =
      (await page
        .locator('.center-board')
        .first()
        .waitFor({ state: 'visible', timeout: 4000 })
        .then(() => true)
        .catch(() => false)) ||
      (await page
        .locator('.drawing-board')
        .first()
        .waitFor({ state: 'visible', timeout: 2000 })
        .then(() => true)
        .catch(() => false))
    record(
      108,
      '① 页面可达：组件面板+画布渲染',
      not404 && panelOk && boardOk,
      `not404=${not404}, panel=${panelOk}, board=${boardOk}`
    )

    // ② 点击添加一个输入类组件 → 画布出现该项（click 添加路径，绕开拖拽不稳）
    let addOk = false
    try {
      const before = await page.locator('.drawing-board > *').count()
      await page.locator('.left-board .components-item').first().click()
      await page.waitForTimeout(800)
      const after = await page.locator('.drawing-board > *').count()
      addOk = after > before
    } catch (err) {
      log(`  F108 添加组件异常: ${err.message.slice(0, 120)}`)
    }
    record(108, '② 点击组件添加到画布', addOk)

    // ③ 生成代码按钮 → 代码/预览弹窗出现 → Escape 关闭（弹窗链卸净）
    let dlgOk = false
    let dlgClosed = false
    try {
      await page
        .getByRole('button', { name: /复制代码|生成代码|导出/ })
        .first()
        .click()
      const dlg = page.locator('.el-dialog:visible').last()
      dlgOk = await dlg
        .waitFor({ state: 'visible', timeout: 4000 })
        .then(() => true)
        .catch(() => false)
      if (dlgOk) {
        await page.keyboard.press('Escape')
        await page.waitForTimeout(500)
        dlgClosed = (await page.locator('.el-dialog:visible').count()) === 0
      }
    } catch (err) {
      log(`  F108 代码弹窗异常: ${err.message.slice(0, 120)}`)
    }
    record(108, '③ 生成代码弹窗出现并 Escape 卸净', dlgOk && dlgClosed, `dlg=${dlgOk}, closed=${dlgClosed}`)
  } catch (err) {
    record(108, '表单构建器冒烟', false, `异常: ${err.message.slice(0, 160)}`)
  }
  await dismissAllOverlays(page)
}

