// ==================== 功能 128：dataset 编辑器 UI（新增→试跑渲染→UPDATE 负例→删除闭环） ====================
async function testFeature128(page) {
  log('=== 功能 128：报表数据集编辑器 UI ===')
  const ok = await openPage(page, '/system/reportDataset', 'reportDataset')
  record(128, '① dataset 页可达（/system/reportDataset）', ok)
  if (!ok) return
  await dismissAllOverlays(page)

  const token = await sessionTokenOf(page)
  const jsonHeaders = { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }
  const uniq = Date.now().toString(36)
  const code = `e2e-128-ds-${uniq}`
  const badCode = `e2e-128-bad-${uniq}`

  /** 编辑对话框三件套填写（编码/名称输入框 + 首个 textarea=SQL 模板，结构对齐 F94） */
  const fillDlg = async (scope, dsCode, dsName, sql) => {
    await scope.locator('input').nth(0).fill(dsCode)
    await scope.locator('input').nth(1).fill(dsName)
    await scope.locator('textarea').first().fill(sql)
  }
  const findRowByCode = async (dsCode) => {
    const r = await apiWithBackoff('/report/dataset/list?pageNum=1&pageSize=50', { headers: jsonHeaders })
    return (r.body?.rows || []).find((x) => x.datasetCode === dsCode) || null
  }

  // ② 新增对话框 + 合法白名单 SQL 保存
  await page.getByRole('button', { name: /新增/ }).first().click()
  const dlg = page.locator('.el-dialog:visible').last()
  const dlgOk = await dlg
    .waitFor({ state: 'visible', timeout: 5000 })
    .then(() => true)
    .catch(() => false)
  if (!dlgOk) {
    record(128, '② 新增对话框打开', false, '对话框未打开')
    await dismissAllOverlays(page)
    return
  }
  await fillDlg(dlg, code, 'e2e-128 数据集', 'SELECT 1 AS v')
  const saveP = page
    .waitForResponse(
      (r) => r.url().endsWith('/report/dataset') && r.request().method() === 'POST' && r.status() === 200,
      { timeout: 10000 }
    )
    .catch(() => null)
  await dlg
    .getByRole('button', { name: /确\s*定/ })
    .first()
    .click()
  const saveResp = await saveP
  const dlgClosed = await dlg
    .waitFor({ state: 'hidden', timeout: 5000 })
    .then(() => true)
    .catch(() => false)
  record(
    128,
    '② 合法 SQL 保存（POST 200 且对话框关闭）',
    !!saveResp && dlgClosed,
    `resp=${saveResp ? saveResp.status() : 'none'}, closed=${dlgClosed}`
  )

  // ③ 列表出现 e2e-128- 行
  const row = page.locator('.el-table__row').filter({ hasText: code }).first()
  await row.waitFor({ state: 'visible', timeout: 10000 }).catch(() => {})
  const rowOk = await row.isVisible().catch(() => false)
  record(128, '③ 列表出现 e2e-128- 行', rowOk)

  // ④ 试跑按钮 → 预览对话框打开 → 返回结构渲染（列头 v + 数据行；openPreview 打开即自动 runPreview）
  // 批三十六：行内 link 按钮用 JS click——force click 会被 fixed 列阴影/动画期遮罩吞掉
  // （探针实证 elementFromPoint 命中遮罩、el.click() 直达，§3.30-2 同型）。
  if (rowOk) {
    await row
      .getByRole('button', { name: /试跑/ })
      .first()
      .evaluate((el) => el.click())
    const pdlg = page.locator('.el-dialog:visible').filter({ hasText: '数据集试跑' }).first()
    const pOpen = await pdlg
      .waitFor({ state: 'visible', timeout: 6000 })
      .then(() => true)
      .catch(() => false)
    const colOk = pOpen
      ? await pdlg
          .locator('.el-table__header')
          .filter({ hasText: 'v' })
          .first()
          .waitFor({ state: 'visible', timeout: 8000 })
          .then(() => true)
          .catch(() => false)
      : false
    const dataRows = pOpen ? await pdlg.locator('.el-table__row').count() : 0
    record(
      128,
      '④ 试跑预览返回结构渲染（列头 v + 数据行）',
      pOpen && colOk && dataRows > 0,
      `open=${pOpen}, col=${colOk}, rows=${dataRows}`
    )
    // 关闭预览对话框（优先 header 关闭钮，Escape 兜底）
    const closeBtn = pdlg.locator('.el-dialog__headerbtn').first()
    if (await closeBtn.isVisible().catch(() => false)) await closeBtn.click()
    else await page.keyboard.press('Escape')
    await page.waitForTimeout(400)
  } else {
    record(128, '④ 试跑预览返回结构渲染（列头 v + 数据行）', false, '前置：列表无自建行')
  }

  // ⑤ 负例：UPDATE 被 SQL 白名单拒绝（错误提示 + 对话框不关闭 + API 不落库）
  await page.getByRole('button', { name: /新增/ }).first().click()
  const bdlg = page.locator('.el-dialog:visible').last()
  const bOpen = await bdlg
    .waitFor({ state: 'visible', timeout: 5000 })
    .then(() => true)
    .catch(() => false)
  let negOk = false
  if (bOpen) {
    await fillDlg(bdlg, badCode, 'e2e-128 负例', "UPDATE sys_user SET user_name = 'e2e'")
    // 批三十六：先挂 POST 响应监听再点击——拒绝语义以服务端响应为准（toast 时序不稳），
    // 响应到达后再测 toast/对话框/落库三态。
    const negP = page
      .waitForResponse((r) => r.url().endsWith('/report/dataset') && r.request().method() === 'POST', {
        timeout: 10000
      })
      .catch(() => null)
    await bdlg
      .getByRole('button', { name: /确\s*定/ })
      .first()
      .click()
    const negResp = await negP
    const negRejected = !negResp || negResp.status() !== 200
    const errToast = await page
      .locator('.el-message--error, .el-message--warning')
      .first()
      .waitFor({ state: 'visible', timeout: 5000 })
      .then(() => true)
      .catch(() => false)
    const stillOpen = await bdlg.isVisible().catch(() => false)
    const notPersisted = !(await findRowByCode(badCode))
    negOk = negRejected && errToast && stillOpen && notPersisted
    record(
      128,
      '⑤ 负例 UPDATE 被拒（错误提示+不落库）',
      negOk,
      `resp=${negResp ? negResp.status() : 'none'}, toast=${errToast}, open=${stillOpen}, absent=${notPersisted}`
    )
    await dismissAllOverlays(page)
  } else {
    record(128, '⑤ 负例 UPDATE 被拒（错误提示+不落库）', false, '负例对话框未打开')
  }

  // ⑥ UI 删除恢复初态（MessageBox 确认 → API 复核已删）
  const cur = await findRowByCode(code)
  let delOk = false
  if (rowOk && cur) {
    await dismissAllOverlays(page)
    // 重新定位行（⑤ 负例后列表可能已重渲染，旧 row 引用 detach——r44 实证 click 30s 超时）
    const delRow = page.locator('.el-table__row').filter({ hasText: code }).first()
    const delRowOk = await delRow
      .waitFor({ state: 'visible', timeout: 6000 })
      .then(() => true)
      .catch(() => false)
    if (delRowOk) {
      await delRow
        .getByRole('button', { name: /删除/ })
        .first()
        .evaluate((el) => el.click())
      const cbox = page.locator('.el-message-box:visible').first()
      const cboxOk = await cbox
        .waitFor({ state: 'visible', timeout: 4000 })
        .then(() => true)
        .catch(() => false)
      if (cboxOk) {
        await cbox
          .locator('.el-message-box__btns .el-button--primary')
          .first()
          .evaluate((el) => el.click())
          .catch(() => {})
      }
    }
    let gone = false
    for (let i = 0; i < 8; i++) {
      await page.waitForTimeout(600)
      if (!(await findRowByCode(code))) {
        gone = true
        break
      }
    }
    delOk = gone
  }
  record(128, '⑥ 删除恢复初态（API 复核已删）', delOk)
  // 兜底清理（UI 删除失败时防残留）
  const leftover = await findRowByCode(code)
  if (leftover)
    await apiWithBackoff(`/report/dataset/${leftover.datasetId}`, { method: 'DELETE', headers: jsonHeaders })
  await dismissAllOverlays(page)
}

// ==================== 功能 129：profile 三 Tab UI（头像上传/第三方绑定/通行密钥） ====================

/** 程序生成真实 PNG 文件字节（64x64 纯色 RGB），非 mock：完整 PNG 签名 + IHDR + IDAT + IEND */
function crc32Of(buf) {
  let table = crc32Of._table
  if (!table) {
    table = crc32Of._table = new Int32Array(256)
    for (let n = 0; n < 256; n++) {
      let c = n
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1
      table[n] = c
    }
  }
  let c = -1
  for (let i = 0; i < buf.length; i++) c = table[(c ^ buf[i]) & 0xff] ^ (c >>> 8)
  return (c ^ -1) >>> 0
}

function makePngBytes(width, height) {
  const chunk = (type, data) => {
    const len = Buffer.alloc(4)
    len.writeUInt32BE(data.length)
    const body = Buffer.concat([Buffer.from(type, 'ascii'), data])
    const crc = Buffer.alloc(4)
    crc.writeUInt32BE(crc32Of(body))
    return Buffer.concat([len, body, crc])
  }
  const sig = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])
  const ihdr = Buffer.alloc(13)
  ihdr.writeUInt32BE(width, 0)
  ihdr.writeUInt32BE(height, 4)
  ihdr[8] = 8 // bit depth
  ihdr[9] = 2 // color type: truecolor RGB
  // raw scanlines：每行前置 filter byte 0，后接 RGB 像素
  const raw = Buffer.alloc(height * (1 + width * 3))
  for (let y = 0; y < height; y++) {
    const rowStart = y * (1 + width * 3)
    raw[rowStart] = 0
    for (let x = 0; x < width; x++) {
      const p = rowStart + 1 + x * 3
      raw[p] = 228
      raw[p + 1] = 87
      raw[p + 2] = 86
    }
  }
  const idat = zlib.deflateSync(raw)
  const iend = Buffer.alloc(0)
  return Buffer.concat([sig, chunk('IHDR', ihdr), chunk('IDAT', idat), chunk('IEND', iend)])
}

async function testFeature129(page) {
  log('=== 功能 129：profile 三 Tab UI（userAvatar/oauth/passkeys） ===')

  // ---------- ① userAvatar：页面可达 + 头像组件渲染 + 真实上传 ----------
  const ok = await openPage(page, '/user/profile', '/user/profile')
  record(129, '① profile 页可达（/user/profile）', ok)
  if (!ok) return
  await dismissAllOverlays(page)

  // 左卡头像组件（userAvatar.vue：div.user-info-head[aria-label=点击上传头像] > img）
  const avatarHead = page.locator('.user-info-head').first()
  const avatarOk = await avatarHead
    .waitFor({ state: 'visible', timeout: 6000 })
    .then(() => true)
    .catch(() => false)
  record(129, '① 头像上传组件渲染（.user-info-head）', avatarOk)

  // 批三十七：CSP img-src 必须含 blob:——vue-cropper 1.1.4 工作图/预览用 URL.createObjectURL，
  // 缺失时裁剪器被 CSP 拦截、头像裁剪/上传 UI 结构性不可用（本批修复的回归锁）
  const csp = await page.request
    .get(`${CONFIG.frontendUrl}/`)
    .then((r) => r.headers()['content-security-policy'] || '')
    .catch(() => '')
  record(
    129,
    '① CSP img-src 含 blob:（vue-cropper 裁剪链路回归锁）',
    csp.includes('img-src') && csp.includes('blob:'),
    `csp=${csp.slice(0, 90)}`
  )

  const token = await sessionTokenOf(page)
  const jsonHeaders = { Authorization: `Bearer ${token}` }

  // 原头像快照：DB 指针 + 文件字节（上传会删除旧文件 ⇒ 必须先取字节才能恢复）
  const prof = await apiWithBackoff('/system/user/profile', { headers: jsonHeaders })
  const origAvatarPath = prof.body?.data?.avatar || ''
  let origBytes = null
  let origExt = ''
  if (origAvatarPath) {
    origExt = (origAvatarPath.split('.').pop() || '').toLowerCase()
    if (['jpg', 'jpeg', 'png', 'gif'].includes(origExt)) {
      try {
        const r = await fetch(`${CONFIG.backendUrl}${origAvatarPath}`, { headers: jsonHeaders })
        if (r.ok) origBytes = Buffer.from(await r.arrayBuffer())
      } catch {}
    }
  }

  if (avatarOk) {
    if (!origBytes) {
      recordSkip(
        129,
        '① 真实头像上传 + 恢复原头像',
        `原头像不可取（avatar=${origAvatarPath || '空'}），跳过以免无法恢复`,
        prof.status === 200
      )
    } else {
      // 打开「修改头像」对话框（userAvatar.vue：点击 .user-info-head → el-dialog append-to-body）
      await avatarHead.evaluate((el) => el.click())
      const dlg = page.locator('.el-dialog:visible').filter({ hasText: '修改头像' }).first()
      const dlgOk = await dlg
        .waitFor({ state: 'visible', timeout: 5000 })
        .then(() => true)
        .catch(() => false)
      record(129, '① 「修改头像」对话框打开', dlgOk)
      if (dlgOk) {
        // 真实文件：程序生成 64x64 PNG buffer（非 mock），setInputFile 触发 el-upload
        const pngBuf = makePngBytes(64, 64)
        const fileInput = dlg.locator('input[type="file"]').first()
        await fileInput.setInputFiles({ name: 'e2e-129-avatar.png', mimeType: 'image/png', buffer: pngBuf })
        // beforeUpload(magic bytes) + FileReader 异步链 → 裁剪器挂载
        const cropper = dlg.locator('[class*="cropper"]').first()
        const cropOk = await cropper
          .waitFor({ state: 'visible', timeout: 8000 })
          .then(() => true)
          .catch(() => false)
        record(129, '① 选文件后裁剪组件渲染', cropOk)
        // 上传：本部署 CSP img-src 'self' data: 拦截 blob: 图（冒烟实证：vue-cropper 裁剪图被 CSP
        // 拦截 ⇒ getCropBlob 永不回调，UI 提交路径在该 CSP 下不可能完成）。按预案降级：
        // 「选文件后触发上传接口 200」——用程序生成的真实 PNG 字节真实 POST 上传接口（非 mock）。
        const up = await fetch(`${CONFIG.backendUrl}/system/user/profile/avatar`, {
          method: 'POST',
          headers: { Authorization: `Bearer ${token}` },
          body: (() => {
            const fd = new FormData()
            fd.append('avatarfile', new Blob([pngBuf], { type: 'image/png' }), 'e2e-129-avatar.png')
            return fd
          })()
        }).catch(() => null)
        const upBody = up ? await up.json().catch(() => null) : null
        const upOk = !!up && up.status === 200 && typeof upBody?.imgUrl === 'string' && upBody.imgUrl.length > 0
        // 上传后头像指针必须更新（profile.avatar 指向新上传文件）
        const profAfter = upOk ? await apiWithBackoff('/system/user/profile', { headers: jsonHeaders }) : null
        const ptrChanged =
          !!profAfter &&
          profAfter.status === 200 &&
          profAfter.body?.data?.avatar === upBody?.imgUrl &&
          profAfter.body.data.avatar !== origAvatarPath
        record(
          129,
          '① 头像上传成功（真实 PNG POST 200 + imgUrl + avatar 指针更新）',
          upOk && ptrChanged,
          `resp=${up ? up.status : 'none'}, imgUrl=${(upBody?.imgUrl || '').slice(-30)}, ptr=${ptrChanged}`
        )
        await dismissAllOverlays(page)
      } else {
        record(129, '① 选文件后裁剪组件渲染', false, '前置：对话框未打开')
        record(129, '① 头像上传成功（真实 PNG POST 200 + imgUrl + avatar 指针更新）', false, '前置：对话框未打开')
      }

      // 恢复原头像：字节级回传原文件（DB 指向新 uuid 路径、内容与原图一致）
      const mimeMap = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', gif: 'image/gif' }
      const fd = new FormData()
      fd.append('avatarfile', new Blob([origBytes], { type: mimeMap[origExt] }), `restore.${origExt}`)
      const rs = await fetch(`${CONFIG.backendUrl}/system/user/profile/avatar`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
        body: fd
      }).catch(() => null)
      const rsOk = !!rs && rs.status === 200
      // 复核：profile 返回 avatar 指向原扩展名文件（恢复成功）
      const prof2 = rsOk ? await apiWithBackoff('/system/user/profile', { headers: jsonHeaders }) : null
      const restored = !!prof2 && prof2.status === 200 && (prof2.body?.data?.avatar || '').endsWith(`.${origExt}`)
      record(
        129,
        '① 恢复原头像（API 回传原文件 + 复核 avatar 指针）',
        rsOk && restored,
        `restore=${rs ? rs.status : 'none'}, avatar=${(prof2?.body?.data?.avatar || '').slice(-40)}`
      )
    }
  }

  // ---------- ② oauth Tab：URL 直达 + 绑定列表渲染（i18n 真值：绑定管理/管理当前账号已绑定的第三方身份/暂无第三方绑定） ----------
  const oauthOk = await openPage(page, '/user/profile/oauth', '/user/profile/oauth')
  record(129, '② oauth Tab 可达（/user/profile/oauth 直达）', oauthOk)
  if (oauthOk) {
    await dismissAllOverlays(page)
    const bindCard = page.locator('.el-card').filter({ hasText: '绑定管理' }).first()
    const cardOk = await bindCard
      .waitFor({ state: 'visible', timeout: 6000 })
      .then(() => true)
      .catch(() => false)
    const alertOk = await bindCard
      .locator('.el-alert')
      .filter({ hasText: '管理当前账号已绑定的第三方身份' })
      .first()
      .waitFor({ state: 'visible', timeout: 4000 })
      .then(() => true)
      .catch(() => false)
    const hasContent =
      (await bindCard.locator('.binding-item').count()) > 0 ||
      (await bindCard.locator('.el-divider').filter({ hasText: '登录提供商管理' }).count()) > 0 ||
      (await bindCard.locator('.el-empty').filter({ hasText: '暂无第三方绑定' }).count()) > 0
    record(
      129,
      '② 绑定列表渲染（提示条 + 绑定行/提供商/空态三态其一）',
      cardOk && alertOk && hasContent,
      `card=${cardOk}, alert=${alertOk}, content=${hasContent}`
    )
  }

  // ---------- ③ passkeys Tab：能力位判定 + 组件渲染（关闭态 recordSkip 而非硬断言） ----------
  const info = await apiWithBackoff('/getInfo', { headers: jsonHeaders })
  const capOk = info.status === 200
  await openPage(page, '/user/profile/passkeys', '/user/profile/passkeys')
  await dismissAllOverlays(page)
  const pkTab = page.getByRole('tab', { name: /通行密钥/ }).first()
  const pkTabOk = await pkTab
    .waitFor({ state: 'visible', timeout: 5000 })
    .then(() => true)
    .catch(() => false)
  if (!pkTabOk) {
    recordSkip(129, '③ passkeys Tab 渲染', '能力位 auth.webauthn 关闭（showPasskey=false）→ 页签按 v-if 不渲染', capOk)
  } else {
    await pkTab.evaluate((el) => el.click()).catch(() => {})
    const pkCard = page.locator('.el-card').filter({ hasText: '通行密钥 / Passkeys' }).first()
    const cardOk = await pkCard
      .waitFor({ state: 'visible', timeout: 6000 })
      .then(() => true)
      .catch(() => false)
    // 三态其一：凭据表格 / 空态「暂无已添加的通行密钥」/ 浏览器不支持警告
    const triState =
      (await pkCard.locator('.el-table').count()) > 0 ||
      (await pkCard.locator('.el-empty').filter({ hasText: '暂无已添加的通行密钥' }).count()) > 0 ||
      (await pkCard.locator('.el-alert--warning').filter({ hasText: '当前浏览器不支持通行密钥' }).count()) > 0
    record(
      129,
      '③ passkeys Tab 组件渲染（表格/空态/不支持提示三态其一）',
      cardOk && triState,
      `card=${cardOk}, triState=${triState}`
    )
  }
  await dismissAllOverlays(page)
}

// ==================== 功能 130：sso-consent 与 oauth-login 页面级 ====================

async function testFeature130(page) {
  log('=== 功能 130：sso-consent 无 clientId 守卫 + oauth-login 页面级 ===')

  // ---------- ① /sso-consent 登录态直达（无 clientId）→ 非法入口兜底（consent.vue valid=false → el-result） ----------
  const ok = await openPage(page, '/sso-consent', '/sso-consent')
  record(130, '① /sso-consent 登录态直达可达', ok)
  if (ok) {
    await dismissAllOverlays(page)
    const result = page.locator('.el-result').first()
    const resultOk = await result
      .waitFor({ state: 'visible', timeout: 6000 })
      .then(() => true)
      .catch(() => false)
    const titleOk =
      resultOk &&
      (
        await result
          .locator('.el-result__title')
          .innerText()
          .catch(() => '')
      ).includes('授权请求无效')
    const backBtn = result.getByRole('button', { name: '返回首页' }).first()
    const btnOk = await backBtn
      .waitFor({ state: 'visible', timeout: 4000 })
      .then(() => true)
      .catch(() => false)
    record(
      130,
      '① 无 clientId → 非法入口提示（授权请求无效 + 返回首页按钮）',
      resultOk && titleOk && btnOk,
      `result=${resultOk}, title=${titleOk}, btn=${btnOk}`
    )
    // 授权面板本体不应渲染（valid=false ⇒ 无 同意/拒绝 按钮）
    const approveVisible = await page.getByRole('button', { name: /同意|允许|拒绝/ }).count()
    record(130, '① 同意/拒绝按钮未渲染（无授权上下文）', approveVisible === 0, `count=${approveVisible}`)
  }

  // ---------- ② /oauth-login 登录态直达（白名单路由，无参数 → loadFailed 提示 + 前往登录入口） ----------
  const ok2 = await openPage(page, '/oauth-login', '/oauth-login')
  record(130, '② /oauth-login 页面可达（登录态直达）', ok2)
  if (ok2) {
    await dismissAllOverlays(page)
    const panel = page.locator('.panel').first()
    const titleOk = await panel
      .locator('h3')
      .filter({ hasText: '第三方登录' })
      .first()
      .waitFor({ state: 'visible', timeout: 5000 })
      .then(() => true)
      .catch(() => false)
    const goLogin = page.getByRole('button', { name: '前往登录' }).first()
    const btnOk = await goLogin
      .waitFor({ state: 'visible', timeout: 4000 })
      .then(() => true)
      .catch(() => false)
    record(
      130,
      '② 无参数落地态：标题「第三方登录」+「前往登录」按钮',
      titleOk && btnOk,
      `title=${titleOk}, btn=${btnOk}`
    )
  }

  // ---------- ③ 未登录白名单行为：/oauth-login 直达不跳转；/sso-consent 非白名单 → 跳登录页 ----------
  let octx = null
  try {
    octx = await page.context().browser().newContext()
    const p2 = await octx.newPage()
    await p2.goto(`${CONFIG.frontendUrl}/oauth-login`, { waitUntil: 'load' })
    await p2.waitForTimeout(1500)
    const staysOAuth = p2.url().includes('/oauth-login')
    const goLoginVisible = await p2
      .getByRole('button', { name: '前往登录' })
      .first()
      .waitFor({ state: 'visible', timeout: 5000 })
      .then(() => true)
      .catch(() => false)
    record(
      130,
      '③ 未登录访问 /oauth-login：白名单直达不重定向（渲染前往登录）',
      staysOAuth && goLoginVisible,
      `url=${p2.url().slice(0, 80)}, btn=${goLoginVisible}`
    )

    await p2.goto(`${CONFIG.frontendUrl}/sso-consent`, { waitUntil: 'load' })
    const toLogin = await p2
      .waitForURL((u) => /\/login(\?|$)/.test(u.toString()), { timeout: 8000 })
      .then(() => true)
      .catch(() => false)
    record(130, '③ 未登录访问 /sso-consent：守卫重定向到登录页', toLogin, `url=${p2.url().slice(0, 80)}`)
  } catch (err) {
    record(
      130,
      '③ 未登录访问 /oauth-login：白名单直达不重定向（渲染前往登录）',
      false,
      `异常: ${err.message.slice(0, 120)}`
    )
    record(130, '③ 未登录访问 /sso-consent：守卫重定向到登录页', false, `异常: ${err.message.slice(0, 120)}`)
  } finally {
    if (octx) await octx.close().catch(() => {})
  }
}

// ==================== 功能 131：rateLimit UI CRUD（/monitor/rateLimit） ====================

async function testFeature131(page) {
  log('=== 功能 131：rateLimit UI CRUD（新增/保存/复核/删除恢复） ===')
  const ok = await openPage(page, '/monitor/rateLimit', 'rateLimit')
  record(131, '① rateLimit 页可达（/monitor/rateLimit）', ok)
  if (!ok) return
  await dismissAllOverlays(page)

  const token = await sessionTokenOf(page)
  const jsonHeaders = { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }
  const uniq = Date.now().toString(36)
  // 合法值：routePattern 无白名单约束（后端仅唯一性校验），用不命中任何真实路由的前缀，避免误伤真实限流
  const pattern = `/e2e-131-${uniq}`
  const findRowByPattern = async (p) => {
    const r = await apiWithBackoff(
      `/system/rateLimit/list?pageNum=1&pageSize=50&routePattern=${encodeURIComponent(p)}`,
      { headers: jsonHeaders }
    )
    return (r.body?.rows || []).find((x) => x.routePattern === p) || null
  }

  // ② 新增对话框打开 + 字段断言（zh-CN 真值：路由前缀/桶容量/补充速率(/秒)/启用状态/描述）
  await page
    .getByRole('button', { name: /新增/ })
    .first()
    .evaluate((el) => el.click())
    .catch(() => {})
  const dlg = page.locator('.el-dialog:visible').last()
  const dlgOk = await dlg
    .waitFor({ state: 'visible', timeout: 5000 })
    .then(() => true)
    .catch(() => false)
  if (!dlgOk) {
    record(131, '② 新增对话框打开 + 字段断言', false, '对话框未打开')
    await dismissAllOverlays(page)
    return
  }
  const itemByLabel = (label) =>
    dlg.locator('.el-form-item').filter({ has: page.locator(`.el-form-item__label:text-is("${label}")`) })
  const fieldsOk =
    (await itemByLabel('路由前缀').locator('input').count()) > 0 &&
    (await itemByLabel('桶容量').locator('.el-input-number').count()) > 0 &&
    (await itemByLabel('补充速率').locator('.el-input-number').count()) > 0 &&
    (await itemByLabel('启用状态').locator('.el-switch').count()) > 0 &&
    (await itemByLabel('描述').locator('textarea').count()) > 0
  record(131, '② 新增对话框字段渲染（路由前缀/桶容量/补充速率/启用状态/描述）', fieldsOk)
  // ③ 真实保存（先挂 POST 响应监听再点确定 → 200 + 对话框关闭）
  await itemByLabel('路由前缀').locator('input').first().fill(pattern)
  await itemByLabel('描述').locator('textarea').first().fill(`e2e-131 限流配置 ${uniq}`)
  const saveP = page
    .waitForResponse(
      (r) => r.url().endsWith('/system/rateLimit') && r.request().method() === 'POST' && r.status() === 200,
      { timeout: 10000 }
    )
    .catch(() => null)
  await dlg
    .getByRole('button', { name: /确\s*定/ })
    .first()
    .evaluate((el) => el.click())
    .catch(() => {})
  const saveResp = await saveP
  const dlgClosed = await dlg
    .waitFor({ state: 'hidden', timeout: 5000 })
    .then(() => true)
    .catch(() => false)
  record(
    131,
    '③ 合法配置保存（POST 200 且对话框关闭）',
    !!saveResp && dlgClosed,
    `resp=${saveResp ? saveResp.status() : 'none'}, closed=${dlgClosed}`
  )

  // ④ 列表出现 e2e-131- 行 + API 复核
  const row = page.locator('.el-table__row').filter({ hasText: pattern }).first()
  await row.waitFor({ state: 'visible', timeout: 10000 }).catch(() => {})
  const rowOk = await row.isVisible().catch(() => false)
  const apiRow = await findRowByPattern(pattern)
  record(
    131,
    '④ 列表出现 e2e-131- 行且 API 复核命中',
    rowOk && !!apiRow,
    `ui=${rowOk}, api=${apiRow ? `id=${apiRow.id}, capacity=${apiRow.capacity}` : 'miss'}`
  )

  // ⑤ UI 删除恢复初态（MessageBox 确认 → API 复核已删）
  let delOk = false
  if (rowOk) {
    // 重新定位行（保存后列表重渲染，旧 row 引用可能 detach——F128 同型坑）
    const delRow = page.locator('.el-table__row').filter({ hasText: pattern }).first()
    const delRowOk = await delRow
      .waitFor({ state: 'visible', timeout: 6000 })
      .then(() => true)
      .catch(() => false)
    if (delRowOk) {
      await delRow
        .getByRole('button', { name: /删除/ })
        .first()
        .evaluate((el) => el.click())
      const cbox = page.locator('.el-message-box:visible').first()
      const cboxOk = await cbox
        .waitFor({ state: 'visible', timeout: 4000 })
        .then(() => true)
        .catch(() => false)
      if (cboxOk) {
        await cbox
          .locator('.el-message-box__btns .el-button--primary')
          .first()
          .evaluate((el) => el.click())
          .catch(() => {})
      }
    }
    let gone = false
    for (let i = 0; i < 8; i++) {
      await page.waitForTimeout(600)
      if (!(await findRowByPattern(pattern))) {
        gone = true
        break
      }
    }
    delOk = gone
  }
  record(131, '⑤ 删除恢复初态（MessageBox 确认 + API 复核已删）', delOk)

  // 兜底清理（UI 删除失败时防残留）
  const leftover = await findRowByPattern(pattern)
  if (leftover) {
    await apiWithBackoff(`/system/rateLimit/${leftover.id}`, { method: 'DELETE', headers: jsonHeaders })
  }
  await dismissAllOverlays(page)
}

// ==================== 功能 132：dataRule UI 表单（/system/dataRule） ====================

async function testFeature132(page) {
  log('=== 功能 132：dataRule UI 表单（新增/保存/roleIds 复核/删除恢复） ===')
  const ok = await openPage(page, '/system/dataRule', '/system/dataRule')
  record(132, '① dataRule 页可达（/system/dataRule）', ok)
  if (!ok) return
  await dismissAllOverlays(page)

  const token = await sessionTokenOf(page)
  const jsonHeaders = { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }
  const uniq = Date.now().toString(36)
  const ruleName = `e2e-132-dr-${uniq}`
  const findRowByName = async (name) => {
    const r = await apiWithBackoff('/system/dataRule/list?page=1&size=100', { headers: jsonHeaders })
    return (r.body?.rows || []).find((x) => x.ruleName === name) || null
  }

  // ② 新增对话框打开 + 字段断言（zh-CN 真值：规则名/目标表/目标列/操作符/值类型/规则值/生效角色/状态）
  await page
    .getByRole('button', { name: /新增/ })
    .first()
    .evaluate((el) => el.click())
    .catch(() => {})
  const dlg = page.locator('.el-dialog:visible').last()
  const dlgOk = await dlg
    .waitFor({ state: 'visible', timeout: 5000 })
    .then(() => true)
    .catch(() => false)
  if (!dlgOk) {
    record(132, '② 新增对话框打开 + 字段断言', false, '对话框未打开')
    await dismissAllOverlays(page)
    return
  }
  const itemByLabel = (label) =>
    dlg.locator('.el-form-item').filter({ has: page.locator(`.el-form-item__label:text-is("${label}")`) })
  const fieldsOk =
    (await itemByLabel('规则名').locator('input').count()) > 0 &&
    (await itemByLabel('目标表').locator('input').count()) > 0 &&
    (await itemByLabel('目标列').locator('input').count()) > 0 &&
    (await itemByLabel('操作符').locator('.el-select').count()) > 0 &&
    (await itemByLabel('值类型').locator('.el-select').count()) > 0 &&
    (await itemByLabel('规则值').locator('input').count()) > 0 &&
    (await itemByLabel('生效角色').locator('.el-select').count()) > 0
  record(132, '② 新增对话框字段渲染（规则名/目标表/目标列/操作符/值类型/规则值/生效角色）', fieldsOk)

  // ③ 真实保存合法规则（fixed 值类型为默认，规则值输入框随 valueType=fixed 渲染）
  await itemByLabel('规则名').locator('input').first().fill(ruleName)
  await itemByLabel('目标表').locator('input').first().fill('sys_user')
  await itemByLabel('目标列').locator('input').first().fill('create_by')
  await itemByLabel('规则值').locator('input').first().fill(`e2e-132-${uniq}`)

  // 生效角色：选第一个非超管角色（避免数据规则在保存窗口内过滤 admin 自身查询）
  let roleIdSelected = null
  try {
    const roles = await apiWithBackoff('/system/role/optionselect', { headers: jsonHeaders })
    const roleList = (roles.body?.data || []).filter((r) => r.roleId !== 1)
    const target = roleList[0] || (roles.body?.data || [])[0] || null
    if (target) {
      await dlg
        .locator('input[aria-label="选择生效角色"]')
        .first()
        .evaluate((el) => el.click())
        .catch(() => {})
      const opt = page
        .locator('.el-select-dropdown:visible .el-select-dropdown__item')
        .filter({ hasText: target.roleName })
        .first()
      const optOk = await opt
        .waitFor({ state: 'visible', timeout: 4000 })
        .then(() => true)
        .catch(() => false)
      if (optOk) {
        await opt.evaluate((el) => el.click())
        roleIdSelected = target.roleId
        await page.keyboard.press('Escape') // 收起下拉，避免遮挡确定按钮
        await page.waitForTimeout(400)
      }
    }
  } catch {}
  const tagOk = roleIdSelected ? (await dlg.locator('.el-select').last().locator('.el-tag').count()) > 0 : null
  record(
    132,
    '③ 生效角色多选回显（选中角色 tag 渲染）',
    tagOk === null ? true : tagOk,
    tagOk === null ? '无可用角色，跳过选择' : `roleId=${roleIdSelected}, tag=${tagOk}`
  )

  // 保存：先挂 POST 响应监听再点确定 → 200 + 对话框关闭
  const saveP = page
    .waitForResponse(
      (r) => r.url().endsWith('/system/dataRule') && r.request().method() === 'POST' && r.status() === 200,
      { timeout: 10000 }
    )
    .catch(() => null)
  await dlg
    .getByRole('button', { name: /确\s*定/ })
    .first()
    .evaluate((el) => el.click())
    .catch(() => {})
  const saveResp = await saveP
  const dlgClosed = await dlg
    .waitFor({ state: 'hidden', timeout: 5000 })
    .then(() => true)
    .catch(() => false)
  record(
    132,
    '③ 合法规则保存（POST 200 且对话框关闭）',
    !!saveResp && dlgClosed,
    `resp=${saveResp ? saveResp.status() : 'none'}, closed=${dlgClosed}`
  )

  // ④ 列表出现 + API 复核 roleIds 字段（F101 回归锁：列表必须回显 roleIds）
  const row = page.locator('.el-table__row').filter({ hasText: ruleName }).first()
  await row.waitFor({ state: 'visible', timeout: 10000 }).catch(() => {})
  const rowOk = await row.isVisible().catch(() => false)
  const apiRow = await findRowByName(ruleName)
  const roleIdsOk = apiRow
    ? roleIdSelected
      ? Array.isArray(apiRow.roleIds) && apiRow.roleIds.includes(roleIdSelected)
      : Array.isArray(apiRow.roleIds)
    : false
  record(
    132,
    '④ 列表出现 e2e-132- 行且 API 复核 roleIds 字段',
    rowOk && !!apiRow && roleIdsOk,
    `ui=${rowOk}, api=${apiRow ? 'hit' : 'miss'}, roleIds=${JSON.stringify(apiRow?.roleIds)}, expect=${roleIdSelected}`
  )

  // ⑤ UI 删除恢复初态（MessageBox 确认 → API 复核已删）
  let delOk = false
  if (rowOk) {
    const delRow = page.locator('.el-table__row').filter({ hasText: ruleName }).first()
    const delRowOk = await delRow
      .waitFor({ state: 'visible', timeout: 6000 })
      .then(() => true)
      .catch(() => false)
    if (delRowOk) {
      await delRow
        .getByRole('button', { name: /删除/ })
        .first()
        .evaluate((el) => el.click())
      const cbox = page.locator('.el-message-box:visible').first()
      const cboxOk = await cbox
        .waitFor({ state: 'visible', timeout: 4000 })
        .then(() => true)
        .catch(() => false)
      if (cboxOk) {
        await cbox
          .locator('.el-message-box__btns .el-button--primary')
          .first()
          .evaluate((el) => el.click())
          .catch(() => {})
      }
    }
    let gone = false
    for (let i = 0; i < 8; i++) {
      await page.waitForTimeout(600)
      if (!(await findRowByName(ruleName))) {
        gone = true
        break
      }
    }
    delOk = gone
  }
  record(132, '⑤ 删除恢复初态（MessageBox 确认 + API 复核已删）', delOk)

  // 兜底清理（UI 删除失败时防残留；数据规则绑定角色期间会过滤该角色查询，必须清干净）
  const leftover = await findRowByName(ruleName)
  if (leftover) {
    await apiWithBackoff(`/system/dataRule/${leftover.ruleId}`, { method: 'DELETE', headers: jsonHeaders })
  }
  await dismissAllOverlays(page)
}

// ==================== 功能 133：flow/designer 表单式设计器真实闭环 ====================
/**
 * 设计器是表单式（非画布）：src/views/flow/designer/index.vue——编辑态=节点 el-card
 * 列表 + 边 el-card 列表，mode 'list'|'edit' 两态。本用例做**保存闭环**（F110 只做进入断言）：
 * - happy path：新增 → 添加审批节点（填 id/name + 审批人多选）→ 添加连线×2（保证图连通）→
 *   保存（先挂 POST /system/flow/definition 监听）→ 200 + 操作成功 toast + 回列表态 →
 *   列表新 flow_code 行 + API 复核 → 尾部 API 删除自建 definition。
 *   注意：新建时 flowCode 前端自动生成 flow_<ts>（编辑态**无**编码/名称输入框，
 *   flowDef.codeNameRequired「编码与名称必填」告警在新模式下实际不可触达），故
 *   用 e2e 语义节点 id（ap_e2e133）避撞 demo_v2 种子，flowCode 由响应体回读。
 * - 连线补充断言：「添加连线」弹窗双 el-select 选 from/to → 边卡片数 +1（编辑态内 DOM）。
 * - 负路径：删除中间审批节点使图断裂 → 保存被前端 validateGraph 先行拦截：
 *   el-alert 错误清单 + flowDef.graphInvalid toast + 无 POST 发出（无落库）。
 */
async function testFeature133(page) {
  log('=== 功能 133：流程设计器表单式编辑真实闭环（加节点+连线+保存落库+负路径+清理） ===')
  const ok = await openPage(page, '/system/flowDefinition', 'flowDefinition')
  record(133, '① 页面可达（/system/flowDefinition）', ok)
  if (!ok) return
  await dismissAllOverlays(page)

  const ADD_NODE = '添加审批节点' // flowDef.addNode zh-CN 真值
  const token = await sessionTokenOf(page)
  const jsonHeaders = { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }

  const enterEditMode = async () => {
    await page
      .getByRole('button', { name: /新增/ })
      .first()
      .evaluate((el) => el.click())
      .catch(() => {})
    return page
      .getByRole('button', { name: ADD_NODE })
      .first()
      .waitFor({ state: 'visible', timeout: 5000 })
      .then(() => true)
      .catch(() => false)
  }
  const backToList = async () => {
    await page
      .getByRole('button', { name: /返回/ })
      .first()
      .evaluate((el) => el.click())
      .catch(() => {})
    await page
      .locator('.el-table')
      .first()
      .waitFor({ state: 'visible', timeout: 6000 })
      .catch(() => {})
  }
  /** 「添加连线」弹窗：双 el-select 选 from/to → 确定 → 断言边卡片 +1 */
  const addEdgeViaDialog = async (fromId, toId) => {
    const before = await page.locator('.el-card').count()
    await page
      .getByRole('button', { name: '添加连线' })
      .first()
      .evaluate((el) => el.click())
      .catch(() => {})
    const dlg = page.locator('.el-dialog:visible').last()
    const dlgOk = await dlg
      .waitFor({ state: 'visible', timeout: 4000 })
      .then(() => true)
      .catch(() => false)
    if (!dlgOk) return false
    for (const [idx, id] of [
      [0, fromId],
      [1, toId]
    ]) {
      await dlg
        .locator('.el-select')
        .nth(idx)
        .locator('input')
        .first()
        .evaluate((el) => el.click())
        .catch(() => {})
      const opt = page.locator('.el-select-dropdown:visible .el-select-dropdown__item').filter({ hasText: id }).first()
      const optOk = await opt
        .waitFor({ state: 'visible', timeout: 4000 })
        .then(() => true)
        .catch(() => false)
      if (!optOk) {
        await page.keyboard.press('Escape')
        return false
      }
      await opt.evaluate((el) => el.click())
      await sleep(300)
    }
    await dlg
      .getByRole('button', { name: /确\s*定/ })
      .first()
      .evaluate((el) => el.click())
      .catch(() => {})
    await dlg.waitFor({ state: 'hidden', timeout: 4000 }).catch(() => {})
    const after = await page.locator('.el-card').count()
    return after === before + 1
  }

  // ② 列表「新增」进入编辑态（表单式设计器：缺省骨架 start→a1→end + 两条边）
  const editOk = await enterEditMode()
  record(133, '② 列表「新增」进入编辑态（添加审批节点按钮渲染）', editOk)
  if (!editOk) {
    await dismissAllOverlays(page)
    return
  }

  // ③ 添加审批节点：卡片 +1（3 节点卡 + 2 边卡 → 新节点卡插在节点区末尾 = nth(3)），
  //    填 id/name（aria-label 在内部 input 上：节点 ID / 节点名称），审批人多选追加 role:admin
  const cardsBefore = await page.locator('.el-card').count()
  await page
    .getByRole('button', { name: ADD_NODE })
    .first()
    .evaluate((el) => el.click())
  await sleep(300)
  const cardsAfterAdd = await page.locator('.el-card').count()
  const newCard = page.locator('.el-card').nth(3)
  await newCard.locator('input[aria-label="节点 ID"]').first().fill('ap_e2e133')
  await newCard.locator('input[aria-label="节点名称"]').first().fill('E2E审批节点')
  let assigneeOk = false
  try {
    await newCard
      .locator('input[aria-label="审批人"]')
      .first()
      .evaluate((el) => el.click())
    const opt = page
      .locator('.el-select-dropdown:visible .el-select-dropdown__item')
      .filter({ hasText: 'role:admin' })
      .first()
    await opt.waitFor({ state: 'visible', timeout: 4000 })
    await opt.evaluate((el) => el.click())
    await page.keyboard.press('Escape') // 收起下拉，避免遮挡后续按钮
    await sleep(300)
    assigneeOk = (await newCard.locator('.el-select').first().locator('.el-tag').count()) >= 2
  } catch {}
  record(
    133,
    '③ 添加审批节点（卡片 +1）+ id/name 填写 + 审批人双 tag（dept_leader 默认 + role:admin）',
    cardsAfterAdd === cardsBefore + 1 && assigneeOk,
    `cards=${cardsBefore}→${cardsAfterAdd}, assignees=${assigneeOk}`
  )

  // ④ 连线补充断言：a1→ap_e2e133、ap_e2e133→end（新审批节点必须有入边+出边才通过
  //    validateGraph 连通性校验，故两次添加、各断言边卡片 +1，随保存链一起提交）
  const edge1 = await addEdgeViaDialog('a1', 'ap_e2e133')
  const edge2 = await addEdgeViaDialog('ap_e2e133', 'end')
  record(
    133,
    '④ 添加连线弹窗（a1→ap_e2e133、ap_e2e133→end，边卡片各 +1）',
    edge1 && edge2,
    `edge1=${edge1}, edge2=${edge2}`
  )

  // ⑤ 保存闭环：先挂 POST 监听再点保存 → 200 + 操作成功 toast + 回列表态
  const saveP = page
    .waitForResponse(
      (r) => r.url().endsWith('/system/flow/definition') && r.request().method() === 'POST' && r.status() === 200,
      { timeout: 10000 }
    )
    .catch(() => null)
  await page
    .getByRole('button', { name: /保存/ })
    .first()
    .evaluate((el) => el.click())
    .catch(() => {})
  const saveResp = await saveP
  const saveBody = saveResp ? await saveResp.json().catch(() => null) : null
  let flowId = saveBody?.data?.flowId || null
  let flowCode = saveBody?.data?.flowCode || ''
  if (!flowId) {
    // 兜底：POST 响应无 data 时按列表回查（flow_<ts> 为前端自动编码，种子 demo_v2 不匹配）
    const lst = await apiWithBackoff('/system/flow/definition/list?pageNum=1&pageSize=50', { headers: jsonHeaders })
    const newest =
      (lst.body?.rows || [])
        .filter((x) => /^flow_\d+/.test(x.flowCode || '') && x.isLatest)
        .sort((a, b) => b.flowId - a.flowId)[0] || null
    if (newest) {
      flowId = newest.flowId
      flowCode = newest.flowCode
    }
  }
  const toastOk = await page
    .locator('.el-message--success')
    .filter({ hasText: '操作成功' })
    .first()
    .waitFor({ state: 'visible', timeout: 4000 })
    .then(() => true)
    .catch(() => false)
  const backOk = await page
    .getByRole('button', { name: ADD_NODE })
    .first()
    .waitFor({ state: 'hidden', timeout: 6000 })
    .then(() => true)
    .catch(() => false)
  record(
    133,
    '⑤ 保存（POST /system/flow/definition 200 + 操作成功 toast + 回列表态）',
    !!saveResp && toastOk && backOk,
    `resp=${saveResp ? saveResp.status() : 'none'}, flowId=${flowId}, code=${flowCode}, toast=${toastOk}, back=${backOk}`
  )

  // ⑥ 列表新 flow_code 行 + API 复核
  let rowOk = false
  let apiHit = false
  if (flowCode) {
    const row = page.locator('.el-table__row').filter({ hasText: flowCode }).first()
    await row.waitFor({ state: 'visible', timeout: 10000 }).catch(() => {})
    rowOk = await row.isVisible().catch(() => false)
    const apiList = await apiWithBackoff(
      `/system/flow/definition/list?pageNum=1&pageSize=10&flowCode=${encodeURIComponent(flowCode)}`,
      { headers: jsonHeaders }
    )
    apiHit = (apiList.body?.rows || []).some((x) => x.flowId === flowId)
  }
  record(133, '⑥ 列表出现新 flow_code 行且 API 复核命中', rowOk && apiHit, `ui=${rowOk}, api=${apiHit}`)

  // ⑦ 尾部清理：API 删除自建 definition + 复核已删（恢复初态）
  let cleanOk = false
  if (flowId) {
    const del = await apiWithBackoff(`/system/flow/definition/${flowId}`, { method: 'DELETE', headers: jsonHeaders })
    const check = flowCode
      ? await apiWithBackoff(
          `/system/flow/definition/list?pageNum=1&pageSize=10&flowCode=${encodeURIComponent(flowCode)}`,
          { headers: jsonHeaders }
        )
      : { body: { rows: [1] } }
    cleanOk = del.status === 200 && (check.body?.rows || []).length === 0
  }
  record(133, '⑦ 尾部删除自建 definition（API 复核已删，恢复初态）', cleanOk, `flowId=${flowId}, ok=${cleanOk}`)

  // ⑧ 负路径：删掉中间审批节点 a1 使图断裂（start→a1→end 边悬空）→ 保存被
  //    前端 validateGraph 先行拦截：el-alert 错误清单 + graphInvalid toast + 无 POST（无落库）
  const edit2 = await enterEditMode()
  if (edit2) {
    await page
      .locator('.el-card')
      .nth(1)
      .locator('button[aria-label="删除"]')
      .first()
      .evaluate((el) => el.click())
    await sleep(300)
    const postP2 = page
      .waitForResponse((r) => r.url().endsWith('/system/flow/definition') && r.request().method() === 'POST', {
        timeout: 2500
      })
      .then(() => true)
      .catch(() => false)
    await page
      .getByRole('button', { name: /保存/ })
      .first()
      .evaluate((el) => el.click())
      .catch(() => {})
    const alertOk = await page
      .locator('.el-alert--error')
      .first()
      .waitFor({ state: 'visible', timeout: 4000 })
      .then(() => true)
      .catch(() => false)
    const alertText = alertOk
      ? await page
          .locator('.el-alert--error')
          .first()
          .innerText()
          .catch(() => '')
      : ''
    const toastNeg = await page
      .locator('.el-message--error')
      .filter({ hasText: '流程图校验未通过' })
      .first()
      .waitFor({ state: 'visible', timeout: 3000 })
      .then(() => true)
      .catch(() => false)
    const postFired = await postP2
    const stillEdit = await page
      .getByRole('button', { name: ADD_NODE })
      .first()
      .isVisible()
      .catch(() => false)
    record(
      133,
      '⑧ 断图保存被前端拦截（错误清单+graphInvalid toast+无 POST+保持编辑态）',
      alertOk && toastNeg && !postFired && stillEdit,
      `alert=${alertOk}, toast=${toastNeg}, post=${postFired}, edit=${stillEdit}, list="${alertText.replace(/\s+/g, ' ').slice(0, 60)}"`
    )
    await backToList()
  } else {
    record(133, '⑧ 断图保存被前端拦截（错误清单+graphInvalid toast+无 POST+保持编辑态）', false, '再次进入编辑态失败')
  }
  await dismissAllOverlays(page)
}

// ==================== 功能 134：msg-channel 渠道连通性测试（site 成功链 + email 负路径） ====================
/**
 * 页面 /system/msg/channel（菜单 141，F87 同路由）。链路：列表行「测试」按钮
 * （msg.channel.btn.test，v-hasPermi=system:msg:channel:test）→「渠道连通性测试」对话框
 * （descriptions 只读）→「开始测试」→ POST /system/msg/channel/test/{id}：
 * - site 渠道后端无条件成功（sys_msg_service.rs "site" => Ok(())）→ 200 + 渠道测试通过
 *   toast（msg.channel.testSuccess）+ 对话框关闭。
 * - email 渠道：本机 mailer 未启用 → 400 error.msg.mail_disabled（后端 tr! 已译
 *   「邮件服务未启用，无法发送邮件」）→ 先 API 探针定性行为，再按实际断言
 *   （错误 toast + runTest 失败路径 .then 跳过 → 对话框保持打开）。
 * 零数据变更（测试不发消息、不写发送日志），尾部仅关闭对话框 + dismissAllOverlays。
 */
async function testFeature134(page) {
  log('=== 功能 134：消息渠道连通性测试（site 成功 + email mail_disabled 负路径） ===')
  const ok = await openPage(page, '/system/msg/channel', 'msg/channel')
  record(134, '① 渠道页可达（/system/msg/channel）', ok)
  if (!ok) return
  await dismissAllOverlays(page)

  const token = await sessionTokenOf(page)
  const jsonHeaders = { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }
  const listRows = async () => {
    const r = await apiWithBackoff('/system/msg/channel/list?pageNum=1&pageSize=50', { headers: jsonHeaders })
    return r.body?.rows || []
  }
  const apiRows = await listRows()
  const siteRow = apiRows.find((x) => x.channelCode === 'site') || null
  const emailRow = apiRows.find((x) => x.channelCode === 'email') || null
  record(
    134,
    '①b API 复核 site/email 种子渠道存在（不新建渠道）',
    !!siteRow && !!emailRow,
    `site=${siteRow ? `id=${siteRow.channelId}` : 'miss'}, email=${emailRow ? `id=${emailRow.channelId}` : 'miss'}`
  )

  /** 行内「测试」按钮（JS click）→「渠道连通性测试」对话框 */
  const openTestDialog = async (rowText) => {
    const row = page.locator('.el-table__row').filter({ hasText: rowText }).first()
    const rowOk = await row
      .waitFor({ state: 'visible', timeout: 6000 })
      .then(() => true)
      .catch(() => false)
    if (!rowOk) return null
    await row
      .getByRole('button', { name: '测试' })
      .first()
      .evaluate((el) => el.click())
      .catch(() => {})
    const dlg = page.locator('.el-dialog:visible').last()
    const dlgOk = await dlg
      .waitFor({ state: 'visible', timeout: 5000 })
      .then(() => true)
      .catch(() => false)
    if (!dlgOk) return null
    const title = await dlg
      .locator('.el-dialog__header')
      .innerText()
      .catch(() => '')
    const descOk = (await dlg.locator('.el-descriptions__label').count()) >= 3
    return { dlg, title, descOk }
  }

  // ② site 渠道成功链：先挂 POST 监听再点「开始测试」→ 200 + 渠道测试通过 + 对话框关闭
  const s = await openTestDialog(siteRow?.channelName || '站内信')
  if (!s) {
    record(134, '② site 测试链（POST 200 + 渠道测试通过 toast + 对话框关闭）', false, '测试对话框未打开')
  } else {
    record(
      134,
      '② site 行「测试」打开对话框（标题+descriptions 只读渲染）',
      s.title.includes('渠道连通性测试') && s.descOk,
      `title=${s.title.trim().slice(0, 20)}, desc=${s.descOk}`
    )
    if (siteRow) {
      const testP = page
        .waitForResponse(
          (r) => r.url().includes(`/system/msg/channel/test/${siteRow.channelId}`) && r.request().method() === 'POST',
          { timeout: 10000 }
        )
        .catch(() => null)
      await s.dlg
        .getByRole('button', { name: '开始测试' })
        .first()
        .evaluate((el) => el.click())
        .catch(() => {})
      const resp = await testP
      const toastOk = await page
        .locator('.el-message--success')
        .filter({ hasText: '渠道测试通过' })
        .first()
        .waitFor({ state: 'visible', timeout: 4000 })
        .then(() => true)
        .catch(() => false)
      const closed = await s.dlg
        .waitFor({ state: 'hidden', timeout: 5000 })
        .then(() => true)
        .catch(() => false)
      record(
        134,
        '② site 测试链（POST 200 + 渠道测试通过 toast + 对话框关闭）',
        !!resp && resp.status() === 200 && toastOk && closed,
        `resp=${resp ? resp.status() : 'none'}, toast=${toastOk}, closed=${closed}`
      )
    } else {
      await s.dlg
        .getByRole('button', { name: /取\s*消/ })
        .first()
        .evaluate((el) => el.click())
        .catch(() => {})
      record(134, '② site 测试链（POST 200 + 渠道测试通过 toast + 对话框关闭）', false, 'API 无 site 渠道')
    }
  }

  // ③ email 负路径：先 API 探针观察真实行为（400 mail_disabled），再按实际断言 UI 行为
  if (emailRow) {
    const probe = await apiWithBackoff(`/system/msg/channel/test/${emailRow.channelId}`, {
      method: 'POST',
      headers: jsonHeaders
    })
    const probeMsg = probe.body?.msg || ''
    const e = await openTestDialog(emailRow.channelName || '邮件')
    if (!e) {
      record(134, '③ email 负路径（错误 toast + 对话框按探针定性实际行为）', false, '测试对话框未打开')
    } else {
      const testP2 = page
        .waitForResponse(
          (r) => r.url().includes(`/system/msg/channel/test/${emailRow.channelId}`) && r.request().method() === 'POST',
          { timeout: 10000 }
        )
        .catch(() => null)
      await e.dlg
        .getByRole('button', { name: '开始测试' })
        .first()
        .evaluate((el) => el.click())
        .catch(() => {})
      const resp2 = await testP2
      const errToast = await page
        .locator('.el-message--error, .el-message--warning')
        .first()
        .waitFor({ state: 'visible', timeout: 4000 })
        .then(() => true)
        .catch(() => false)
      const errText = errToast
        ? await page
            .locator('.el-message--error, .el-message--warning')
            .first()
            .innerText()
            .catch(() => '')
        : ''
      const dlgStillOpen = await e.dlg.isVisible().catch(() => false)
      // 探针定性：失败（非 200）⇒ 期望 UI 同样失败路径（错误 toast + runTest .then 跳过 ⇒ 对话框保持打开）
      const expectFail = probe.status !== 200
      const behavOk = expectFail
        ? !!resp2 && resp2.status() !== 200 && errToast && dlgStillOpen
        : !!resp2 && resp2.status() === 200
      record(
        134,
        '③ email 负路径（错误 toast + 对话框按探针定性实际行为）',
        behavOk,
        `probe=${probe.status}/${probeMsg.slice(0, 40)}, resp=${resp2 ? resp2.status() : 'none'}, toast=${errToast}("${errText.trim().slice(0, 40)}"), dlgOpen=${dlgStillOpen}`
      )
      if (dlgStillOpen) {
        await e.dlg
          .getByRole('button', { name: /取\s*消/ })
          .first()
          .evaluate((el) => el.click())
          .catch(() => {})
        await e.dlg.waitFor({ state: 'hidden', timeout: 4000 }).catch(() => {})
      }
    }
  } else {
    record(134, '③ email 负路径（错误 toast + 对话框按探针定性实际行为）', false, 'API 无 email 渠道')
  }

  // ④ 尾部：零数据变更（测试不发消息、不写发送日志），仅确认对话框全关闭
  await dismissAllOverlays(page)
  const leftoverDialogs = await page.locator('.el-dialog:visible').count()
  record(134, '④ 尾部收尾（无数据变更 + 对话框全关闭）', leftoverDialogs === 0, `dialogs=${leftoverDialogs}`)
}

// ==================== 功能 135：运行时 metrics 捕获维度（批四十七新捕获面）====================
// /metrics（public.rs 公开端点，Prometheus 文本格式，5544 行）此前不在 e2e 捕获面内——
// 本用例把「运行时指标异常」纳入捕获：结构健全性 + 5xx 计数 + 任务失败计数 + DB 池健康。
// 设计要点：负向用例会产生 4xx（403/429/400 预期），不纳入异常；503（auth 闸门 fail-closed）
// 是环境风暴信号——超阈值即 FAIL（r55 实证风暴轮 503 计数会暴涨）。
async function testFeature135(page) {
  log('=== 功能 135：运行时 metrics 捕获维度 ===')
  const token = await sessionTokenOf(page)
  const jsonHeaders = { Authorization: `Bearer ${token}` }
  let raw = ''
  try {
    raw = await apiWithBackoff('/metrics', { headers: jsonHeaders })
      .then((r) => r.body)
      .catch(() => null)
    if (typeof raw !== 'string') {
      // apiWithBackoff 可能 JSON.parse 失败回退——直接 fetch 兜底
      raw = await fetch(`${CONFIG.backendUrl}/metrics`, { headers: jsonHeaders })
        .then((r) => r.text())
        .catch(() => '')
    }
  } catch (err) {
    record(135, '① /metrics 可达', false, `异常: ${err.message.slice(0, 100)}`)
    return
  }
  record(
    135,
    '① /metrics 可达（Prometheus 文本格式）',
    raw.length > 1000 && raw.includes('# HELP'),
    `bytes=${raw.length}`
  )

  const metrics = new Map()
  for (const line of raw.split('\n')) {
    const m = line.match(/^(stepby_[a-z_]+)(\{[^}]*\})?\s+(.+)$/)
    if (m) metrics.set(`${m[1]}${m[2] || ''}`, m[3].trim())
  }

  // ② 结构健全性：进程/DB/共享态关键 gauge（store kind 为带 label 形态——前缀匹配，批四十七修正）
  const uptime = Number(metrics.get('stepby_uptime_seconds') || 0)
  let dbConnected = 0
  for (const [k, v] of metrics) {
    if (k.startsWith('stepby_db_connected{')) dbConnected = Number(v) || 0
  }
  let storeKind = ''
  for (const [k, v] of metrics) {
    if (k.startsWith('stepby_shared_store_kind{')) storeKind = String(v).replace(/"/g, '')
  }
  record(
    135,
    '② 结构健全性（uptime>0 / db_connected=1 / shared_store_kind 在位）',
    uptime > 0 && dbConnected === 1 && storeKind.length > 0,
    `uptime=${uptime}s, db_connected=${dbConnected}, store=${storeKind}`
  )

  // ③ 5xx 计数（批四十七修正：计数器为进程启动以来累计值——固定阈值错误，首轮即 76 含 r55 风暴史）
  // 改跨轮快照 delta 语义：screenshots/_metrics_5xx_baseline.json 存上轮总量，本轮 delta ≤ 阈值；
  // 首轮无基线时建立基线并 PASS（记录口径）。负向用例只产 4xx；5xx 暴涨 = 环境风暴信号（r55 实证）。
  let total5xx = 0
  const fiveXXPaths = []
  for (const [key, val] of metrics) {
    if (key.startsWith('stepby_http_requests_total{') && /status="5\d\d"/.test(key)) {
      total5xx += Number(val) || 0
      fiveXXPaths.push(key.replace('stepby_http_requests_total', '').slice(0, 60))
    }
  }
  const FIVE_XX_DELTA_THRESHOLD = 10
  const baselinePath = path.join(CONFIG.screenshotDir, '_metrics_5xx_baseline.json')
  let prev5xx = null
  try {
    if (fs.existsSync(baselinePath)) prev5xx = JSON.parse(fs.readFileSync(baselinePath, 'utf8')).total5xx ?? null
  } catch {
    prev5xx = null
  }
  fs.writeFileSync(baselinePath, JSON.stringify({ total5xx, ts: new Date().toISOString() }))
  const delta5xx = prev5xx === null ? null : Math.max(0, total5xx - prev5xx)
  const fiveXXOk = prev5xx === null || delta5xx <= FIVE_XX_DELTA_THRESHOLD
  record(
    135,
    `③ 5xx 轮内增量 ≤ ${FIVE_XX_DELTA_THRESHOLD}（累计计数器跨轮快照 delta，环境风暴信号）`,
    fiveXXOk,
    prev5xx === null
      ? `首轮建立基线：total5xx=${total5xx}（下轮起按 delta 判定）`
      : `prev=${prev5xx}, now=${total5xx}, delta=${delta5xx}${fiveXXPaths.length ? ', sample=' + fiveXXPaths.slice(0, 3).join(' ; ') : ''}`
  )

  // ④ 任务失败计数：内置定时任务应全部成功（outcome/status=fail 家族）
  let jobFail = 0
  for (const [key, val] of metrics) {
    if (key.startsWith('stepby_job_executions_total{') && /(fail|error|timeout)/i.test(key)) {
      jobFail += Number(val) || 0
    }
  }
  record(135, '④ 定时任务失败计数 = 0', jobFail === 0, `job_fail_total=${jobFail}`)

  // ⑤ DB 池结构健康（批四十七修正：local 档 SQLite max_connections=1，单次抓取 busy=1/1 是
  // 瞬时正常态）——断言池已上报且未超订（busy ≤ size），busy 值留档供趋势观察
  const poolSize = Number(
    metrics.get('stepby_db_pool_size{backend="sqlite"}') || metrics.get('stepby_db_pool_size') || 0
  )
  const poolBusy = Number(
    metrics.get('stepby_db_pool_busy{backend="sqlite"}') || metrics.get('stepby_db_pool_busy') || 0
  )
  record(
    135,
    '⑤ DB 池结构健康（已上报且 busy ≤ size）',
    poolSize > 0 && poolBusy <= poolSize,
    `busy=${poolBusy}/${poolSize}（size=1 为 SQLite 档配置，单次抓取 busy=1 属瞬时正常）`
  )
}

// ==================== 功能 136-140：测试域广度补强（批六十四循环） ====================
// 覆盖此前 e2e/deep-e2e/collect 三套件引用次数最低的页面（运行监控 / 变更留痕 /
// 我的导航 / 域名管理 / 报表看板），补齐"页面可达 + 工具栏 + 真实数据链 + 档位判定"。

/** 通用：元素可见等待（禁 isVisible({timeout})——不接受 timeout 立即返回） */
async function _visible(loc, timeout = 5000) {
  return loc
    .first()
    .waitFor({ state: 'visible', timeout })
    .then(() => true)
    .catch(() => false)
}

/** 通用：overlay-safe 点击（.evaluate 原生 click 穿透遮罩） */
async function _click(loc) {
  await loc
    .first()
    .evaluate((el) => el.click())
    .catch(() => {})
}

/** 功能 136：运行监控页（慢请求/错误聚合 + 共享态档位判定） */
async function testFeature136(page) {
  log('=== 功能 136：运行监控页（慢请求/错误聚合 + 共享态档位判定） ===')
  const ok = await openPage(page, '/monitor/observability', 'observability')
  record(136, '① 页面可达（/monitor/observability）', ok)
  if (!ok) return
  await dismissAllOverlays(page)

  const tabSlow = await _visible(page.getByRole('tab', { name: '慢请求' }))
  const tabErr = await _visible(page.getByRole('tab', { name: '错误聚合' }))
  record(136, '② 页签渲染（慢请求 / 错误聚合）', tabSlow && tabErr, `slow=${tabSlow}, error=${tabErr}`)

  const labels = await page
    .locator('.stat-label')
    .allInnerTexts()
    .catch(() => [])
  const hasSlow = labels.some((x) => x.includes('慢请求数'))
  const hasErr = labels.some((x) => x.includes('错误总数'))
  record(136, '③ 统计卡渲染（慢请求数 + 错误总数）', hasSlow && hasErr, `labels=${labels.join(' / ')}`)

  const rows = await page
    .locator('.el-table__body tr')
    .count()
    .catch(() => 0)
  record(136, '④ 慢请求表格渲染（有行）', rows > 0, `rows=${rows}`)

  // 注意：顶栏（TagsView）也有一个 role=button 的「刷新」（tab.refreshPage）——必须限定在
  // 页面容器内，否则会误点布局刷新（F136 首轮实测：误点布局刷新崩 /500，反而揪出 tab.refreshPage 真实缺陷）
  const pageRoot = page.locator('.app-container').first()
  await _click(pageRoot.getByRole('button', { name: '刷新' }))
  const toastOk = await _visible(page.locator('.el-message--success'), 6000)
  record(136, '⑤ 页面「刷新」按钮 → 成功 toast', toastOk)

  // ⑥ 共享态档位判定（b64 修复回归锁）：local 档 Redis 专属指标显示「—」+ 档位提示
  const token = await sessionTokenOf(page)
  const rs = await apiWithBackoff('/monitor/redis/stats', { headers: { Authorization: `Bearer ${token}` } })
  const kind = rs.body?.data?.storeKind
  const hint = await _visible(page.locator('.el-alert__title').filter({ hasText: 'local 档' }), 4000)
  if (kind === 'local') {
    const dash = await page
      .locator('.stat-value')
      .filter({ hasText: '—' })
      .count()
      .catch(() => 0)
    record(
      136,
      '⑥ local 档：Redis 专属指标显示「—」+ 档位提示（防 0 值误导）',
      dash >= 4 && hint,
      `storeKind=${kind}, dashCards=${dash}, hint=${hint}`
    )
  } else {
    record(136, '⑥ redis 档：Redis 专属指标显示真实值（无 local 提示）', !hint, `storeKind=${kind}`)
  }

  // ⑦ 切「错误聚合」页签 → 该面板专属按钮渲染
  await _click(page.getByRole('tab', { name: '错误聚合' }))
  await sleep(700)
  const errBtn = await _visible(pageRoot.getByRole('button', { name: '清空错误日志' }), 5000)
  record(136, '⑦ 切「错误聚合」页签 → 面板渲染（清空错误日志按钮）', errBtn)

  // ⑧ 顶栏「刷新」按钮回归锁（b64 修复 tab.refreshPage 同步 action 误当 Promise 崩 /500）：
  // 点击后应重挂载当前页而非跳 500；且页面容器仍在。
  const tagRefresh = page.locator('.tags-refresh-btn').first()
  if (await _visible(tagRefresh, 4000)) {
    await _click(tagRefresh)
    await sleep(2500)
    const url = page.url()
    const on500 = /\/500/.test(url)
    const containerAlive = await _visible(page.locator('.app-container'), 6000)
    record(
      136,
      '⑧ 顶栏「刷新」按钮不崩页（tab.refreshPage 回归锁，b64 修复）',
      !on500 && containerAlive,
      `url=${url}, on500=${on500}, container=${containerAlive}`
    )
  } else {
    record(136, '⑧ 顶栏「刷新」按钮不崩页（tab.refreshPage 回归锁，b64 修复）', false, '.tags-refresh-btn 未找到')
  }
}

/** 功能 137：变更留痕页（列表/搜索过滤/重置/导出/展开明细） */
async function testFeature137(page) {
  log('=== 功能 137：变更留痕页（列表/搜索过滤/重置/导出/展开明细） ===')
  const ok = await openPage(page, '/system/log/auditChange', 'auditChange')
  record(137, '① 页面可达（/system/log/auditChange）', ok)
  if (!ok) return
  await dismissAllOverlays(page)

  const rows = await page
    .locator('.el-table__body tr')
    .count()
    .catch(() => 0)
  record(137, '② 列表渲染（有行）', rows > 0, `rows=${rows}`)

  const search = await _visible(page.getByRole('button', { name: '搜索' }))
  const reset = await _visible(page.getByRole('button', { name: '重置' }))
  const exp = await _visible(page.getByRole('button', { name: '导出' }))
  record(
    137,
    '③ 工具栏按钮（搜索/重置/导出）',
    search && reset && exp,
    `search=${search}, reset=${reset}, export=${exp}`
  )

  // ④ 搜索过滤：不存在的表名 → 0 行
  const input = page.locator('input[placeholder="请输入被变更的表名"]').first()
  if (await _visible(input, 4000)) {
    // ④ 搜索过滤：不存在的表名 → 0 行。时序敏感根治（探针实证：深链慢挂载时 fill/点击
    // 可落在表单就绪前，固定 sleep 两侧都会假失败）——等待**带 tableName 的列表请求**
    // 作为"过滤真的下发"的取证，再核对 0 行。
    const needle = 'zzz_no_such_table_e2e137'
    const pFiltered = page
      .waitForResponse((r) => r.url().includes('/system/audit-change/list') && r.url().includes(needle), {
        timeout: 8000
      })
      .catch(() => null)
    await input.fill(needle)
    await _click(page.getByRole('button', { name: '搜索' }))
    const rf = await pFiltered
    await sleep(600)
    const filtered = await page
      .locator('.el-table__body tr')
      .count()
      .catch(() => 0)
    record(
      137,
      '④ 搜索过滤生效（不存在的表名 → 0 行）',
      !!rf && filtered === 0,
      `filterReq=${rf ? 'OK' : '未捕获带参请求'}, filteredRows=${filtered}`
    )
    // ⑤ 重置恢复：等待**不带过滤值**的列表请求（resetFields→handleQuery 的取证）+ 行数还原
    const pReset = page
      .waitForResponse((r) => r.url().includes('/system/audit-change/list') && !r.url().includes(needle), {
        timeout: 8000
      })
      .catch(() => null)
    await _click(page.getByRole('button', { name: '重置' }))
    const rr = await pReset
    let back = 0
    for (let i = 0; i < 10; i++) {
      await sleep(500)
      back = await page
        .locator('.el-table__body tr')
        .count()
        .catch(() => 0)
      if (back > 0) break
    }
    record(137, '⑤ 重置恢复（行数还原 > 0）', back > 0 && !!rr, `resetReq=${rr ? 'OK' : '未捕获'}, rows=${back}`)
  } else {
    record(137, '④ 搜索过滤生效（不存在的表名 → 0 行）', false, '表名输入框未找到')
    record(137, '⑤ 重置恢复（行数还原 > 0）', false, '前置搜索框缺失')
  }

  // ⑥ 导出接口 200（响应监听须在点击前挂载——b35 铁律）。
  // 重置会触发 URL 变化 → fullPath 重挂载（out-in 过渡），点击前必须等新实例按钮就绪，
  // 否则 evaluate 点击落在 detached 节点上被静默吞掉（首轮实测 ⑥ 偶发未捕获）。
  const exportReady = await _visible(page.locator('.app-container').first().getByRole('button', { name: '导出' }), 8000)
  const respP = page
    .waitForResponse((r) => r.url().includes('/system/audit-change/export') && r.status() === 200, { timeout: 10000 })
    .catch(() => null)
  if (exportReady) {
    await _click(page.locator('.app-container').first().getByRole('button', { name: '导出' }))
  }
  const resp = await respP
  record(
    137,
    '⑥ 导出接口 200（/system/audit-change/export）',
    !!resp,
    resp ? `status=${resp.status()}` : `未捕获 200 响应（exportReady=${exportReady}）`
  )

  // ⑦ 展开行 → 变更明细渲染
  const expander = page.locator('.el-table__expand-icon').first()
  if (await _visible(expander, 4000)) {
    await _click(expander)
    await sleep(700)
    const detail = await page
      .locator('.el-table__expanded-cell')
      .count()
      .catch(() => 0)
    record(137, '⑦ 展开行 → 变更明细渲染', detail > 0, `expandedCells=${detail}`)
  } else {
    record(137, '⑦ 展开行 → 变更明细渲染', false, '无展开图标')
  }
}

